-- =====================================================================
-- Paralegix - Postgres schema
-- Source of truth: backend/db/schema/*.sql
-- Generated by:    npm run db:schema:build
-- Apply with:      npx tsx backend/db/apply-schema.ts
-- Idempotent-ish:  uses IF NOT EXISTS where possible.
-- =====================================================================

-- >>> 00_extensions.sql <<<
-- ---------- extensions ----------
create extension if not exists pgcrypto;   -- gen_random_uuid()
create extension if not exists citext;     -- case-insensitive emails
create extension if not exists pg_trgm;    -- indexed substring search

-- ---------- shared trigger fn: updated_at ----------
create or replace function set_updated_at() returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

-- >>> 10_identity.sql <<<
-- =====================================================================
-- IDENTITY & TENANCY
-- =====================================================================

create table if not exists users (
  id                    text primary key,                 -- Firebase UID
  email                 citext not null,
  name                  text,
  photo_object_path     text,                             -- per-user profile picture (GCS object path; migration 0101)
  user_type             text not null default 'pending'
                          check (user_type in ('firm_member','client','pending')),
  is_admin              boolean not null default false,   -- platform super-admin (migration 0023)
  terms_accepted_at     timestamptz,
  privacy_accepted_at   timestamptz,
  consent_version       text,
  consent_ip            text,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  -- Folded off the 1:1 `user_settings` satellite by migration 0217.
  timezone         text,
  preferences      jsonb not null default '{}',
  -- Set by the privacy erase, which anonymizes this row rather than deleting
  -- it so every reference to the account stays valid (migration 0224). A live
  -- account has this null; a tombstone has it set.
  deleted_at       timestamptz,
  identity_erased_at timestamptz
);
comment on column users.deleted_at is
  'Set by the privacy erase when the account is anonymized. The row is kept as a tombstone so every reference to it stays valid; this column is what distinguishes a tombstone from a live account.';
comment on column users.identity_erased_at is
  'Set only after privacy identity cleanup, including Firebase deletion, completes. A deleted_at tombstone with this null remains queued for recovery.';
create index if not exists users_pending_erasure_idx on users (deleted_at)
  where deleted_at is not null and identity_erased_at is null;
-- NOTE: email is NOT unique; duplicate and blank emails are possible, so the
-- Firebase UID (users.id) is the real identity key.
create index if not exists users_email_idx on users (email);
-- Supports findUserByEmail's `where lower(email) = $1` predicate.
create index if not exists users_lower_email_idx on users (lower(email));
-- Admin console list sorts, newest first, across every firm (migration 0132).
-- These are global rather than per-firm on purpose: the admin console reads
-- the whole table, so a law_firm_id-leading index cannot serve the sort.
create index if not exists users_created_at_idx on users (created_at desc);

-- DB-backed email-verification whitelist. Auth treats an address as verified if
-- it is on the EMAIL_VERIFICATION_WHITELIST env var OR in this table, so admins
-- can whitelist test accounts live (no redeploy). See shared/utils/emailWhitelist.js.
create table if not exists email_verification_whitelist (
  email       citext primary key,
  note        text,
  created_by  text references users(id) on delete set null,
  created_at  timestamptz not null default now()
);
-- Serves the on-delete walk of email_verification_whitelist_created_by_fkey (migration 0224).
create index if not exists email_verification_whitelist_created_by_idx on email_verification_whitelist (created_by);

create table if not exists law_firms (
  id                        uuid primary key default gen_random_uuid(),
  name                      text not null,
  description               text,
  address                   text,
  city                      text,
  state                     text,
  zip                       text,
  phone                     text,
  website                   text,
  email                     citext,
  logo_object_path          text,
  plan_id                   text not null default 'starter'
                              check (plan_id in ('starter','basic','professional','enterprise')),
  billing_status            text not null default 'comped'
                              check (billing_status in ('comped','active','trialing','incomplete','past_due','canceled')),
  plan                      jsonb not null default '{}',
  stripe_account_id         text,
  stripe_charges_enabled    boolean not null default false,
  stripe_onboarding_complete boolean not null default false,
  -- Direct-charge migration (docs/DIRECT_CHARGE_MIGRATION.md) cutover flag. When true,
  -- client payments are created as DIRECT charges on this firm's connected account (the
  -- firm is merchant of record and bears its own disputes) instead of destination
  -- charges on the platform. Default false = current destination-charge behavior.
  -- NOT READ BY ANY CODE PATH YET, and deliberately so: this is Phase 0 of that
  -- migration, which lands the column ahead of the behaviour. Not dead weight.
  direct_charges_enabled    boolean not null default false,
  storage_quota_bytes       bigint check (storage_quota_bytes is null or storage_quota_bytes >= 0),
  storage_used_bytes        bigint not null default 0 check (storage_used_bytes >= 0),
  -- Retired. Upload reservations are rows in `storage_reservations` (migration
  -- 0015) and nothing adds to this column any more. It stays until a contract
  -- migration folds any remaining balance out of `storage_used_bytes` and drops
  -- it; the recount zeroes it until then so that fold stays accurate.
  storage_reserved_bytes    bigint not null default 0 check (storage_reserved_bytes >= 0),
  storage_hard_limit        boolean not null default false,
  -- Percent-of-quota at which the UI warns. See DEFAULT_STORAGE_WARN_AT_PERCENT.
  storage_warn_at_percent   int not null default 85
                              check (storage_warn_at_percent between 1 and 100),
  -- When the usage figure last CHANGED (bumped by every upload/delete delta).
  storage_usage_updated_at  timestamptz,
  -- When usage was last RECONCILED against the bucket by a full recount, and the
  -- object count that recount saw. Distinct from the column above so a staleness
  -- check is not reset by ordinary uploads. See migration 0124.
  storage_usage_recounted_at timestamptz,
  storage_file_count        bigint,
  -- Soft-delete: see migration 0159 for the full rationale (retention protection
  -- for signature/invoice/matter records that legally cannot be destroyed the
  -- instant a firm account is closed).
  pending_deletion_at       timestamptz,
  deletion_purge_after      timestamptz,
  deletion_requested_by     text references users(id) on delete restrict,
  settings                  jsonb not null default '{}',
  created_at                timestamptz not null default now(),
  updated_at                timestamptz not null default now(),
  unique (id)                                            -- redundant but documents composite-FK target
);
create index if not exists law_firms_plan_idx on law_firms (plan_id, billing_status);
-- Admin console list sorts, newest first, across every firm (migration 0132).
-- These are global rather than per-firm on purpose: the admin console reads
-- the whole table, so a law_firm_id-leading index cannot serve the sort.
create index if not exists law_firms_created_at_idx on law_firms (created_at desc);
create index if not exists law_firms_purge_eligible_idx
  on law_firms (deletion_purge_after)
  where pending_deletion_at is not null;

-- `plan_id` and `billing_status` are AUTHORITATIVE. They are not mirrored from
-- the `plan` jsonb and the jsonb does not carry `planId` / `billingStatus` at
-- all (migration 0200). Until then a BEFORE trigger copied those two keys into
-- these columns, and the same normalization was written a second time in
-- lawfirms.repository, with a comment saying the two had to match. The columns
-- are CHECK-constrained and indexed; the jsonb copy was neither.
--
-- The jsonb keeps the eighteen keys that have no duplicate: the Stripe
-- subscription/customer/price ids, billing interval and period bounds, the trial
-- and comp metadata, and the plan overrides. Readers still see `plan.planId` and
-- `plan.billingStatus`, filled from these columns by loadFirmPlan and
-- lawfirms.repository.toEntity.

create table if not exists user_oauth_tokens (
  user_id          text not null references users(id) on delete cascade,
  provider         text not null check (provider in ('google','microsoft')),
  access_token     text,
  refresh_token    text,
  token_updated_at timestamptz,
  expires_at       timestamptz,
  scope            text,
  meta             jsonb not null default '{}',
  -- Per-provider sync state, folded off `user_settings` by migration 0217. It
  -- lived there as seven columns that named Google explicitly, so a third
  -- provider meant three more columns and two more booleans on a table that has
  -- nothing to do with providers. Keyed by provider it is five columns, and a
  -- new provider is a new row.
  calendar_id      text,   -- which provider calendar this user syncs with
  app_calendar_id  text,   -- the calendar this app created there, if any
  sync_cursor      text,   -- incremental sync position (Google's syncToken)
  is_sync_to_provider   boolean not null default false,
  is_sync_from_provider boolean not null default false,
  primary key (user_id, provider)
);

create table if not exists oauth_states (
  state        text primary key,
  user_id      text references users(id) on delete cascade,
  provider     text check (provider in ('google','microsoft')),
  redirect_uri text,
  return_url   text,
  created_at   timestamptz not null default now()
);
-- Serves the on-delete walk of oauth_states_user_id_fkey (migration 0224).
create index if not exists oauth_states_user_id_idx on oauth_states (user_id);

create table if not exists firm_counters (
  law_firm_id  uuid not null references law_firms(id) on delete cascade,
  counter_type text not null check (counter_type in ('matter_reference','invoice_number')),
  next_val     bigint not null default 1,
  primary key (law_firm_id, counter_type)
);

-- Shared rate-limit store (migration 0079) backing the express-rate-limit
-- Postgres store, so per-IP/per-token caps are coordinated across instances.
-- Keyed by "<limiter-prefix>:<client-key>"; expired windows are swept by the store.
create table if not exists rate_limits (
  key         text primary key,
  hits        integer not null default 0,
  expires_at  timestamptz not null
);
create index if not exists rate_limits_expires_at_idx on rate_limits (expires_at);

-- Stripe webhook idempotency ledger, one row per (endpoint, event id). Each
-- webhook endpoint claims an event before running its handler: 'processing'
-- while a delivery holds it, 'done' once the handler succeeded. Keyed per
-- endpoint because both endpoints receive invoice.paid under the same event id
-- and each must process it. A 'processing' row older than the stale threshold
-- (STRIPE_EVENT_CLAIM_STALE_SECONDS) is reclaimed, so a process that died
-- mid-handler cannot strand the event. Migration 0045.
create table if not exists stripe_events (
  event_id     text not null,
  processed_at timestamptz,
  endpoint     text not null default 'payments',
  status       text not null default 'processing',
  claimed_at   timestamptz not null default now(),
  primary key (endpoint, event_id),
  constraint stripe_events_endpoint_check check (endpoint in ('payments', 'subscriptions')),
  constraint stripe_events_status_check check (status in ('processing', 'done')),
  constraint stripe_events_processed_when_done check ((status = 'done') = (processed_at is not null))
);

-- =====================================================================
-- MEMBERS & ROLES
-- =====================================================================

create table if not exists roles (
  id                  uuid not null default gen_random_uuid(),
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  name                text not null,
  is_built_in         boolean not null default false,
  permissions         text[] not null default '{}',
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  unique (law_firm_id, name)
);
create index if not exists roles_perms_gin on roles using gin (permissions);

create table if not exists members (
  law_firm_id               uuid not null references law_firms(id) on delete cascade,
  user_id                   text not null references users(id) on delete cascade,
  role_id                   uuid,
  is_owner                  boolean not null default false,
  default_hourly_rate_cents bigint check (default_hourly_rate_cents is null or default_hourly_rate_cents >= 0),
  present_as_firm           boolean not null default false,                     -- "send as firm" member preference (migration 0107)
  joined_at                 timestamptz,
  invited_at                timestamptz,
  invited_by                text references users(id) on delete restrict,
  created_at                timestamptz not null default now(),
  updated_at                timestamptz not null default now(),
  primary key (law_firm_id, user_id),
  -- Single column, not (law_firm_id, role_id). A composite key with ON DELETE
  -- SET NULL nulls EVERY column of the key, including the NOT NULL tenant
  -- column, so deleting a role that anyone held failed with 23502 (migration
  -- 0186). Tenant agreement is the application's job: the role is fetched with
  -- its own law_firm_id predicate, so a foreign role id resolves to null and
  -- the member degrades to the baseline.
  constraint members_role_fk foreign key (role_id) references roles(id) on delete set null
);
create index if not exists members_user_idx on members (user_id);
-- At most one owner per firm (migration 0223). Not "exactly one": a partial
-- unique cannot say "at least one", and a firm with two owners has no obvious
-- recovery while a firm with none does. The transfer flow demotes before it
-- promotes, inside one transaction, so it never violates this.
create unique index if not exists members_one_owner_per_firm_idx
  on members (law_firm_id) where is_owner;

-- Column comments. These were written by earlier migrations and never carried
-- into the domain files, so a database built from schema.sql lacked them while
-- a migrated one had them. They are the reference for what each column means.
comment on column law_firms.deletion_purge_after is 'Earliest the firm may be hard-purged (row + GCS bytes actually deleted, by the housekeeping cron). Computed at soft-delete time as pending_deletion_at plus the configured retention window (FIRM_DELETION_RETENTION_YEARS, default 10). Null while pending_deletion_at is null.';
comment on column law_firms.deletion_requested_by is 'User id who triggered the soft delete, for support/audit purposes when investigating a pending deletion.';
comment on column law_firms.pending_deletion_at is 'Set when firm deletion is requested (self-serve delete, or the sole owner leaving). Non-null means the firm is soft-deleted: access is revoked (assertLawFirmMembership / loadResolvedMember treat it as gone) and billing is stopped, but the row and every child record are retained until deletion_purge_after so retention-protected records (signatures, invoices, matters) cannot be destroyed before their legal retention window clears.';
comment on column law_firms.storage_reserved_bytes is 'Retired. Upload reservations live in storage_reservations; nothing adds to this column any more. The recount still zeroes it until a contract migration folds any remaining balance out of storage_used_bytes and drops it.';

-- >>> 15_catalogs.sql <<<
-- =====================================================================
-- REFERENCE CATALOG (global, NOT tenant-scoped)
-- Read-only shared lists firms pick from (copy-on-adopt). Written only by the
-- import scripts in db/seed/, never by app request paths. Defined before the
-- per-firm tables below so their inline catalog_* FKs resolve. (migration 0083)
-- =====================================================================

create table if not exists court_catalog (
  id              uuid primary key default gen_random_uuid(),
  source          text not null default 'courtlistener',
  source_id       text,
  full_name       text not null,
  short_name      text,
  citation_abbrev text,
  jurisdiction    text,                                    -- 'federal' | 'state'
  court_type      text,                                    -- 'appellate' | 'trial' | 'supreme' | 'district' | ...
  state           text,
  url             text,
  in_use          boolean not null default true,
  search          tsvector generated always as (
                    to_tsvector('english',
                      coalesce(full_name,'') || ' ' || coalesce(short_name,'') || ' ' ||
                      coalesce(citation_abbrev,'') || ' ' || coalesce(state,''))
                  ) stored,
  created_at      timestamptz not null default now(),
  unique (source, source_id)
);
create index if not exists court_catalog_search_gin on court_catalog using gin (search);
create index if not exists court_catalog_state_idx on court_catalog (state, court_type);

create table if not exists utbms_codes (
  id           uuid primary key default gen_random_uuid(),
  code         text not null,
  name         text not null,
  code_type    text not null check (code_type in ('task','activity','expense')),
  practice_set text,
  is_active    boolean not null default true,
  unique (code)
);
create index if not exists utbms_codes_type_idx on utbms_codes (code_type, practice_set);

-- =====================================================================
-- MATTERS (+ junctions, notes)
-- =====================================================================

create table if not exists practice_areas (
  id                  uuid not null default gen_random_uuid(),
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  name                text not null,
  sort_order          int,
  created_by          text references users(id) on delete restrict,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id)
);

create table if not exists courts (
  id                  uuid not null default gen_random_uuid(),
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  name                text not null,
  abbreviation        text,
  city                text,
  state               text,
  address             text,
  court_type          text,
  sort_order          int,
  -- provenance link to the global court_catalog row this was adopted from
  -- (migration 0083); null = pure custom court. The copy is freely editable;
  -- the link only drives the "already added" indicator + double-import guard.
  catalog_court_id    uuid references court_catalog(id) on delete set null,
  created_by          text references users(id) on delete restrict,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id)
);
create index if not exists courts_catalog_idx on courts (law_firm_id, catalog_court_id) where catalog_court_id is not null;

-- Firm-configurable note types and note templates (migration 0150), so a firm
-- can extend the built-in note-type vocabulary and reusable note templates
-- from the note composer instead of being limited to the hardcoded frontend
-- lists. `note_types.value` is the slug actually stored in *_notes.note_type;
-- `label` is the display text. `color` (migration 0153) is a StatusVariant key
-- (e.g. "info", "purple"); null falls back to the built-in/default color. A row
-- whose value matches a built-in slug can exist purely to carry a color
-- override, without introducing a second dropdown option for that slug.

-- >>> 20_parties.sql <<<
-- =====================================================================
-- PARTIES & CLIENTS
-- =====================================================================

-- =====================================================================
-- CLIENTS
-- =====================================================================

create table if not exists clients (
  id                       uuid not null default gen_random_uuid(),
  law_firm_id              uuid not null references law_firms(id) on delete cascade,
  user_id                  text references users(id) on delete set null,
  email                    citext,
  name                     text not null,
  phone                    text,
  organization             text,
  address                  text,
  preferred_contact_method text,
  status                   text not null default 'active'
    check (status in ('active', 'inactive', 'archived')),
  portal_invite_pending    boolean not null default false,
  invited_at               timestamptz,
  invited_by               text references users(id) on delete restrict,
  joined_at                timestamptz,
  stripe_customer_id       text,
  billing_rates            jsonb not null default '{}',
  settings                 jsonb not null default '{}',
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now(),
  invitation_sent_at       timestamptz,
  invitation_resend_count  integer not null default 0,
  invitation_failed        boolean not null default false,
  last_resend_at           timestamptz,
  -- person or company, immutable after insert (clients_type_immutable trigger
  -- below). A company is one clients row whose people are their own standalone
  -- person clients, joined to it through client_company_links (migration 0174,
  -- replacing the old contact_clients roster). It is not a synthetic user, and
  -- not a collection of personal clients.
  client_type              text not null default 'person' check (client_type in ('person', 'company')),
  -- Legal hold: when set, the record is preserved against destruction (a
  -- litigation hold blocks deletion). Enforced in the application delete paths.
  primary key (id),
  unique (law_firm_id, id),
  -- A company row must never carry clients.user_id directly. A company does not
  -- sign in; its linked person clients do, each holding their own user_id.
  constraint clients_company_no_user_id_check check (client_type <> 'company' or user_id is null)
);
create index if not exists clients_firm_email_idx on clients (law_firm_id, email) where email is not null;
create index if not exists clients_firm_type_idx on clients (law_firm_id, client_type);
-- Serves the on-delete walk of clients_user_id_fkey (migration 0224).
create index if not exists clients_user_id_idx on clients (user_id);

create or replace function clients_type_immutable() returns trigger as $$
begin
  if new.client_type is distinct from old.client_type then
    raise exception 'clients.client_type is immutable after insert (id=%)', old.id;
  end if;
  return new;
end;
$$ language plpgsql;

drop trigger if exists clients_type_immutable on clients;
create trigger clients_type_immutable before update on clients
  for each row execute function clients_type_immutable();
create index if not exists clients_firm_name_idx on clients (law_firm_id, name);
create index if not exists clients_email_idx on clients (email);
-- Admin console list sorts, newest first, across every firm (migration 0132).
-- These are global rather than per-firm on purpose: the admin console reads
-- the whole table, so a law_firm_id-leading index cannot serve the sort.
create index if not exists clients_created_at_idx on clients (created_at desc);
-- Firm-scoped lower() expression indexes for the conflict-of-interest check and
-- the name-array client dedup lookup (lower(name|email|organization) = any(...)).
create index if not exists clients_firm_lower_name_idx on clients (law_firm_id, lower(name));
create index if not exists clients_firm_lower_email_idx on clients (law_firm_id, lower(email::text)) where email is not null;
create index if not exists clients_firm_lower_org_idx on clients (law_firm_id, lower(organization)) where organization is not null;

-- The people at a client (in-house counsel, an office manager, a spouse) are
-- rows in the firm-wide `contacts` directory linked here, NOT their own records:
-- an in-house counsel who is also co-counsel on a matter is one person, and used
-- to be two independently-editable copies. The table that held those copies
-- (`client_contacts`) was folded into the directory by migration 0136.
--
-- Defined further down, next to `contacts`, because it references it.


-- rather than holding their own copy, so a changed phone number is corrected in
-- one place and every matter that party touches is correct. (migration 0135)
--
-- Distinct from `clients` (which carries billing rates, a Stripe customer and a
-- portal login) and from `client_contacts` (the people at one client).
create table if not exists contacts (
  id            uuid not null default gen_random_uuid(),
  law_firm_id   uuid not null references law_firms(id) on delete cascade,
  -- A company row (an insurance carrier, an expert firm) uses `name` for the
  -- organization and leaves `organization` null.
  contact_type  text not null default 'person'
                check (contact_type in ('person','company')),
  name          text not null,
  -- What this contact usually IS, independent of any one matter. The per-matter
  -- role lives on `matter_contacts.role` and may differ (an attorney who is
  -- opposing counsel on one matter can be co-counsel on another), so the two
  -- share a vocabulary but not a value.
  category      text not null default 'other'
                check (category in ('opposing_counsel','opposing_party','co_counsel','judge','witness',
                                    'expert','adjuster','court_clerk','mediator','guardian_ad_litem',
                                    'court_reporter','vendor','other')),
  organization  text,
  title         text,
  bar_number    text,
  email         citext,
  phone         text,
  phone_alt     text,
  fax           text,
  website       text,
  address       text,
  -- Judges and court clerks belong to a court. Single-column FK (not the
  -- composite tenant form) matching `matters.court_id`: a composite
  -- `on delete set null` would try to null `law_firm_id` too, which is not null.
  -- Tenant agreement is enforced in the service layer, as it is for matters.
  court_id      uuid,
  notes         text,
  tags          text[] not null default '{}',
  is_archived   boolean not null default false,
  -- Scoped to the single matter it was created for. Excluded from the
  -- directory list and every contact picker unless explicitly asked for.
  one_time      boolean not null default false,
  created_by    text references users(id) on delete restrict,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  foreign key (court_id) references courts (id) on delete set null
);
create index if not exists contacts_firm_name_idx on contacts (law_firm_id, name);
create index if not exists contacts_firm_category_idx on contacts (law_firm_id, category);
create index if not exists contacts_firm_court_idx on contacts (law_firm_id, court_id) where court_id is not null;
-- Firm-scoped lower() expression indexes, mirroring `clients`: these back the
-- duplicate-on-create lookup and the conflict-of-interest check, both of which
-- match case-insensitively on name / email / organization.
create index if not exists contacts_firm_lower_name_idx on contacts (law_firm_id, lower(name));
create index if not exists contacts_firm_lower_email_idx on contacts (law_firm_id, lower(email::text)) where email is not null;
create index if not exists contacts_firm_lower_org_idx on contacts (law_firm_id, lower(organization)) where organization is not null;
-- Deliberately NO unique constraint on (firm, name) or (firm, email): two real
-- people share a name, and one person legitimately appears under a personal and
-- a work address. Duplicates are a soft warning at create time (the service
-- returns near-matches so the UI can offer to link the existing contact), which
-- a hard constraint would turn into a dead end.

-- The people at a client. This is what `client_contacts` used to be, except the
-- person is a directory row, so the same in-house counsel who is also co-counsel
-- on a matter is one record rather than two. (migration 0136)


create table if not exists contact_clients (
  id            uuid not null default gen_random_uuid(),
  law_firm_id   uuid not null references law_firms(id) on delete cascade,
  contact_id    uuid not null,
  client_id     uuid not null,
  -- How this person relates to that client ("General Counsel", "Spouse"). Free
  -- text, as it was on client_contacts: firms describe these relationships in
  -- their own words and an enum would not survive contact with reality.
  relationship  text,
  is_primary    boolean not null default false,
  created_by    text references users(id) on delete restrict,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  -- Delivery and access preferences for this contact on this client. The
  -- portal identity columns that used to sit here (user_id and the four portal
  -- lifecycle fields) went with migration 0261: a company's people are ordinary
  -- Person clients linked by client_company_links, so the identity lives on
  -- their own clients row.
  is_email_recipient     boolean not null default false,
  can_view_billing       boolean not null default false,
  primary key (id),
  unique (law_firm_id, id),
  constraint contact_clients_unique_link unique (law_firm_id, contact_id, client_id),
  foreign key (law_firm_id, contact_id) references contacts (law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, client_id) references clients (law_firm_id, id) on delete cascade
);
create index if not exists contact_clients_client_idx on contact_clients (law_firm_id, client_id);
-- One primary contact per client, enforced here rather than by hand in the
-- service, so a concurrent pair of writes cannot leave a client with two.
create unique index if not exists contact_clients_one_primary_idx
  on contact_clients (law_firm_id, client_id) where is_primary;
-- Billing-recipient fan-out (invoice delivery).
create index if not exists contact_clients_email_recipient_idx
  on contact_clients (law_firm_id, client_id) where is_email_recipient;

-- Real client-to-client company relationships (migration 0174), replacing
-- contact_clients as the way a company client's people are modeled: a
-- linked person is a real client_type='person' clients row (its own matters,
-- billing, and portal identity), not a lightweight contacts-directory entry.
-- The service layer enforces person_client_id/company_client_id's client_type
-- before insert; Postgres cannot express that as a cross-row CHECK.
--
-- No portal identity columns: a linked person carries all of that on their own
-- clients row. contact_clients had a mirror set for the design this replaced,
-- and migration 0261 dropped them there too. relationship/is_primary/
-- is_email_recipient/can_view_billing mirror contact_clients's columns of the
-- same name and same semantics unchanged.
create table if not exists client_company_links (
  id                    uuid not null default gen_random_uuid(),
  law_firm_id           uuid not null references law_firms(id) on delete cascade,
  person_client_id      uuid not null,
  company_client_id     uuid not null,
  relationship          text,
  is_primary            boolean not null default false,
  is_email_recipient    boolean not null default false,
  can_view_billing      boolean not null default false,
  created_by            text references users(id) on delete restrict,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  constraint client_company_links_unique unique (law_firm_id, person_client_id, company_client_id),
  constraint client_company_links_not_self check (person_client_id <> company_client_id),
  foreign key (law_firm_id, person_client_id) references clients (law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, company_client_id) references clients (law_firm_id, id) on delete cascade
);
-- One primary person per company, enforced here rather than by hand in the
-- service, so a concurrent pair of writes cannot leave a company with two.
create unique index if not exists client_company_links_one_primary_idx
  on client_company_links (law_firm_id, company_client_id) where is_primary;
-- A company's people (roster listing, billing/messaging/signature fan-out).
create index if not exists client_company_links_company_idx
  on client_company_links (law_firm_id, company_client_id);
-- client_company_links_person_idx removed by migration 0195: client_company_links_unique
-- (law_firm_id, person_client_id, company_client_id) covers the same rows.
-- Client-email fan-out for company-linked people.
create index if not exists client_company_links_email_recipient_idx
  on client_company_links (law_firm_id, company_client_id) where is_email_recipient;

-- The central association resolver's company arm becomes a clients.user_id
-- lookup instead of contact_clients.user_id (which had its own partial
-- indexes, dropped with the column by migration 0261). clients had no
-- user_id index at all before this migration - the person arm apparently got
-- away without one at current scale, but consolidating the company arm's
-- traffic onto the same unindexed column would make an already-hot lookup
-- path measurably slower, so add the equivalent partial index here.
create index if not exists clients_firm_user_idx
  on clients (law_firm_id, user_id) where user_id is not null;

-- Client identity verification through Credence ID (migration 0049). A row keeps
-- the credential's name, issuer, document type, expiry and check results, and
-- never the portrait, signature, license number, address or birth date.
create table if not exists client_identity_verifications (
  id                     uuid not null default gen_random_uuid(),
  law_firm_id            uuid not null references law_firms(id) on delete cascade,
  client_id              uuid not null,
  -- The portal user who started the attempt. Only they may complete or poll it.
  user_id                text not null references users(id) on delete restrict,
  method                 text not null
    check (method in ('mdoc_dcapi', 'openid4vp_dcapi', 'w3c_openid4vp')),
  status                 text not null default 'pending'
    check (status in ('pending', 'verified', 'failed', 'cancelled', 'expired')),
  -- The provider's session handle. Never sent to the browser.
  provider_session_id    text not null,
  -- The name as the credential states it, which is the record of what was
  -- verified, not a copy of the client's name.
  verified_given_name    text,
  verified_family_name   text,
  -- Issuing jurisdiction, e.g. "California" or "US-CA".
  issuer                 text,
  -- The provider's document type, e.g. "org.iso.18013.5.1.mDL". Open vocabulary.
  doc_type               text,
  credential_expires_on  date,
  -- Whether the credential's name matches the client record. A flag, not a gate:
  -- a differing name is still verified.
  is_name_match          boolean,
  -- Pass or fail of each provider check, keyed by check name.
  checks                 jsonb not null default '{}',
  failure_reason         text,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  completed_at           timestamptz,
  expires_at             timestamptz not null default (now() + interval '10 minutes'),
  primary key (id),
  unique (law_firm_id, id),
  constraint client_identity_verifications_provider_session_key unique (provider_session_id),
  constraint client_identity_verifications_client_fkey
    foreign key (law_firm_id, client_id) references clients (law_firm_id, id) on delete cascade,
  -- A finished attempt says when it finished.
  constraint client_identity_verifications_completed_check
    check (status = 'pending' or completed_at is not null)
);
-- The firm's client record reads the latest attempt and the latest verified
-- one; this also serves the composite foreign key's cascade.
create index if not exists client_identity_verifications_client_idx
  on client_identity_verifications (law_firm_id, client_id, created_at desc);
-- Serves the on-delete walk of the users foreign key.
create index if not exists client_identity_verifications_user_idx
  on client_identity_verifications (user_id);
comment on table client_identity_verifications is 'One identity verification attempt by a portal client through Credence ID. Keeps the verified name, issuer, document type, expiry and check results only; never the portrait, signature, license number, address or birth date.';


-- Column comments. These were written by earlier migrations and never carried
-- into the domain files, so a database built from schema.sql lacked them while
-- a migrated one had them. They are the reference for what each column means.
comment on column client_company_links.is_email_recipient is 'Whether this linked person receives client-facing email communications.';
comment on column clients.client_type is 'person or company, immutable after insert (see the clients_type_immutable trigger). A company is one clients row whose people are Person clients joined by client_company_links, not a synthetic user or a collection of personal clients.';
comment on column contact_clients.can_view_billing is 'A preference on a person client''s own contact roster, shown and edited in the client screen. It authorizes nothing: the portal billing gate is client_company_links.can_view_billing, which is a different table and a different relationship.';
comment on column contact_clients.is_email_recipient is 'Whether this linked contact receives client-facing email communications.';
comment on column contacts.one_time is 'Scoped to the single matter it was created for. Excluded from the directory list and every contact picker unless explicitly asked for. Flip to false ("promote") to make it a normal reusable directory contact.';

-- >>> 30_matters.sql <<<
create table if not exists matter_categories (
  id                  uuid not null default gen_random_uuid(),
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  name                text not null,
  parent_id           uuid,
  path                text,
  level               int not null default 0,
  sort_order          int not null default 0,
  created_by          text references users(id) on delete restrict,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id)
);
create index if not exists matter_categories_parent_idx on matter_categories (parent_id);

drop trigger if exists set_updated_at on matter_categories;
create trigger set_updated_at before update on matter_categories
  for each row execute function set_updated_at();

create table if not exists matter_stage_pipelines (
  id                uuid not null default gen_random_uuid(),
  law_firm_id       uuid not null references law_firms(id) on delete cascade,
  practice_area_id  uuid references practice_areas(id) on delete set null,
  name              text not null,
  is_default        boolean not null default false,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id)
);
create index if not exists matter_stage_pipelines_firm_pa_idx
  on matter_stage_pipelines (law_firm_id, practice_area_id);
-- At most one default pipeline per (firm, scope). A plain unique index treats
-- NULLs as always distinct, so coalesce collapses the nullable
-- practice_area_id to a sentinel to make unscoped rows conflict too.
create unique index if not exists matter_stage_pipelines_one_default_idx
  on matter_stage_pipelines (law_firm_id, coalesce(practice_area_id, '00000000-0000-0000-0000-000000000000'::uuid))
  where is_default;

-- Ordered stage a matter progresses through (kanban pipeline), belonging to
-- exactly one matter_stage_pipelines row. is_closed marks a terminal stage.
create table if not exists matter_stages (
  id                uuid not null default gen_random_uuid(),
  law_firm_id       uuid not null references law_firms(id) on delete cascade,
  pipeline_id       uuid not null references matter_stage_pipelines(id) on delete cascade,
  name              text not null,
  color             text,
  sort_order        integer not null default 0,
  is_closed         boolean not null default false,
  parent_stage_id   uuid references matter_stages(id) on delete set null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id)
);
create index if not exists matter_stages_parent_idx on matter_stages (law_firm_id, parent_stage_id);
create index if not exists matter_stages_pipeline_idx on matter_stages (law_firm_id, pipeline_id);

create table if not exists matters (
  id                  uuid not null default gen_random_uuid(),
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  name                text not null,
  matter_number         text,
  matter_reference_id   text not null,
  description         text,
  status              text not null default 'active'    -- vocabulary mirrors VALID_MATTER_STATUSES (matters.validation.js)
                      check (status in ('active','pending','on_hold','completed','blocked','closed','archived')),
  -- Manual "payment ongoing" override: money still expected on a functionally-done
  -- matter (payment plan, or a balance expected but not yet invoiced). Orthogonal
  -- to status. The effective flag the app shows is (this) OR (outstanding invoice
  -- balance), surfaced only on terminal statuses. See matters.repository.js hydrate.
  payment_ongoing     boolean not null default false,
  category            text,
  practice_area_id    uuid,
  court_id            uuid,
  lead_user_id        text references users(id) on delete restrict,
  custom_fields       jsonb not null default '{}',
  -- Legal hold: when set, the record is preserved against destruction (a
  -- litigation hold blocks deletion). Enforced in the application delete paths.
  -- Billing preferences and key dates (migration 0116). `stage_id` and
  -- `stage_pipeline_id` are NOT here: they reference matter_stages /
  -- matter_stage_pipelines, which this file creates further down, so they are
  -- added in the DEFERRED MATTER STAGE COLUMNS block after those tables exist.
  billing_method      text not null default 'hourly'
                        check (billing_method in ('hourly','flat','contingency','pro_bono')),
  is_billable         boolean not null default true,
  budget_cents        bigint check (budget_cents is null or budget_cents >= 0),
  budget_includes_expenses boolean not null default true,
  contingency_percent numeric check (contingency_percent is null or (contingency_percent >= 0 and contingency_percent <= 100)),
  open_date           date,
  close_date          date,
  statute_of_limitations_date date,
  created_by          text references users(id) on delete restrict,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  unique (law_firm_id, matter_reference_id),
  -- single-column FKs: ON DELETE SET NULL on a composite (incl. law_firm_id) FK
  -- would null the tenant id too, so these reference only the parent id.
  foreign key (practice_area_id) references practice_areas (id) on delete set null,
  foreign key (court_id)         references courts (id) on delete set null
);
create index if not exists matters_firm_status_idx on matters (law_firm_id, status);

create table if not exists matter_members (
  matter_id           uuid not null,
  user_id           text not null references users(id) on delete cascade,
  law_firm_id       uuid not null,
  role              text not null default 'member' check (role in ('lead','member')),
  hourly_rate_cents bigint check (hourly_rate_cents is null or hourly_rate_cents >= 0),
  -- `joined_at` is nullable and unset for a row created any way other than an
  -- accepted invitation, so it is NOT a creation stamp; this table still owes a
  -- `created_at`. `role` and the rate are updated in place, which is what the
  -- `updated_at` added by migration 0211 records.
  joined_at         timestamptz,
  updated_at        timestamptz not null default now(),
  primary key (matter_id, user_id),
  foreign key (law_firm_id, matter_id) references matters (law_firm_id, id) on delete cascade
);
create index if not exists matter_members_user_idx on matter_members (user_id);
-- The primary key (matter_id, user_id) serves a lookup by matter but not by
-- (law_firm_id, matter_id), which is the composite foreign key's shape and the
-- one a matter delete cascades on (migration 0206).
create index if not exists matter_members_firm_matter_idx
  on matter_members (law_firm_id, matter_id);

create table if not exists matter_clients (
  matter_id     uuid not null,
  client_id   uuid not null,
  law_firm_id uuid not null,
  -- Share of this matter's invoices this client pays, in basis points
  -- (10000 = 100%). Null means no split is configured. Basis points rather than
  -- a percentage for the same reason money is cents: three equal shares must
  -- come to exactly 100%. The cross-row rule that a matter's portions sum to
  -- 10000 is enforced in the service, inside the transaction that replaces the
  -- junction set, since a table check cannot span rows.
  billing_portion_bp integer
    constraint matter_clients_billing_portion_bp_range
    check (billing_portion_bp is null or (billing_portion_bp >= 0 and billing_portion_bp <= 10000)),
  -- Mutable: rows are inserted ON CONFLICT DO NOTHING and their portion is then
  -- updated in place, so a row survives across edits (migration 0211).
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  primary key (matter_id, client_id),
  foreign key (law_firm_id, matter_id)   references matters (law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, client_id) references clients (law_firm_id, id) on delete cascade
);
create index if not exists matter_clients_client_idx on matter_clients (client_id);

-- Hierarchical matter category tree (each row may reference a parent in the same
-- table). parent_id is intentionally not FK-constrained; the application enforces
-- tree integrity (no self-parent, no cycles, no delete-with-children).

-- Firm-defined custom fields applied to matters. practice_area_id NULL = applies
-- to every matter. Values are stored on matters.custom_fields keyed by this id.
create table if not exists matter_field_defs (
  id                uuid not null default gen_random_uuid(),
  law_firm_id       uuid not null references law_firms(id) on delete cascade,
  practice_area_id  uuid references practice_areas(id) on delete cascade,
  label             text not null,
  field_type        text not null default 'text'
                    check (field_type in ('text','textarea','number','currency','date','select','multiselect','checkbox','url','email','phone')),
  options           jsonb not null default '[]',
  help_text         text,
  required          boolean not null default false,
  sort_order        integer not null default 0,
  archived          boolean not null default false,
  created_by        text references users(id) on delete restrict,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id)
);
create index if not exists matter_field_defs_firm_pa_idx on matter_field_defs (law_firm_id, practice_area_id);

-- A named, optionally practice-area-scoped stage pipeline a matter can be
-- assigned to. Multiple pipelines may share the same scope (including
-- multiple unscoped firm-wide pipelines); at most one per scope is is_default.

-- Links a directory contact to a matter (opposing counsel, judge, etc.).
--
-- This holds only what is genuinely per-matter: the role that contact plays on
-- THIS matter, matter-specific notes, and display order. Name, organization and
-- contact details live on the `contacts` row it points at, so they are edited
-- once and correct on every matter. (migration 0135 -- before it, each row
-- carried its own free-typed copy of the person.)
create table if not exists matter_contacts (
  id                uuid not null default gen_random_uuid(),
  law_firm_id       uuid not null,
  matter_id         uuid not null,
  contact_id        uuid not null,
  role              text not null default 'other'
                    check (role in ('opposing_counsel','opposing_party','co_counsel','judge','witness','expert','adjuster','court_clerk','mediator','guardian_ad_litem','other')),
  notes             text,
  sort_order        integer not null default 0,
  created_by        text references users(id) on delete restrict,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  -- One link per contact per matter; the role lives on the link, so a contact
  -- who changes hats on a matter is an update, not a second row.
  constraint matter_contacts_unique_link unique (law_firm_id, matter_id, contact_id),
  foreign key (law_firm_id, matter_id) references matters (law_firm_id, id) on delete cascade,
  constraint matter_contacts_contact_fk
    foreign key (law_firm_id, contact_id) references contacts (law_firm_id, id) on delete cascade
);
create index if not exists matter_contacts_matter_idx on matter_contacts (matter_id);
create index if not exists matter_contacts_contact_idx on matter_contacts (law_firm_id, contact_id);

-- ---------- leads pipeline + intake forms (0146) ----------
-- Prospects are separate from clients so they never count against plan client
-- limits and never surface ClientDetail tabs that assume financial history.

create table if not exists lead_stages (
  id                uuid not null default gen_random_uuid(),
  law_firm_id       uuid not null references law_firms(id) on delete cascade,
  practice_area_id  uuid references practice_areas(id) on delete set null,
  name              text not null,
  color             text,
  sort_order        integer not null default 0,
  is_closed         boolean not null default false,
  parent_stage_id   uuid references lead_stages(id) on delete set null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id)
);
create index if not exists lead_stages_firm_pa_idx on lead_stages (law_firm_id, practice_area_id);
create index if not exists lead_stages_parent_idx on lead_stages (law_firm_id, parent_stage_id);

create table if not exists leads (
  id                   uuid not null default gen_random_uuid(),
  law_firm_id          uuid not null references law_firms(id) on delete cascade,
  stage_id             uuid,
  stage_date           date,
  name                 text not null,
  email                text,
  phone                text,
  organization         text,
  referral_source      text,
  notes                text,
  disqualify_reason    text,
  converted_client_id  uuid,
  converted_matter_id  uuid,
  converted_at         timestamptz,
  created_by           text references users(id) on delete restrict,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  constraint leads_stage_fk
    foreign key (law_firm_id, stage_id) references lead_stages(law_firm_id, id) on delete set null,
  -- SINGLE column, deliberately, and not composite like leads_stage_fk above.
  -- ON DELETE SET NULL nulls EVERY column of the key it fires on, so a composite
  -- key carrying law_firm_id makes Postgres emit
  --     UPDATE ONLY leads SET law_firm_id = NULL, converted_matter_id = NULL ...
  -- against a NOT NULL column, and deleting a matter or client that a lead was
  -- converted into died on 23502 and surfaced as a 500. Same reasoning as
  -- matters.practice_area_id, matters.court_id and contacts.court_id, which are
  -- single column for exactly this hazard. Tenant scoping is the application's
  -- job on these columns; leads.law_firm_id keeps its own FK to law_firms.
  -- Introduced by migration 0184, since folded into this file with the rest of
  -- the chain.
  -- No foreign key on converted_client_id. It is a soft reference: deleting a
  -- client leaves the lead holding an id that no longer resolves.
  -- Migrations 0224 and 0225 retired the sweep that used to drop such keys, so
  -- a key declared here now survives. Adding one is a behaviour change: it
  -- would make deleting a converted client fail instead of leaving the id.
  constraint leads_converted_matter_fk
    foreign key (converted_matter_id) references matters(id) on delete set null
);
create index if not exists leads_firm_stage_idx on leads (law_firm_id, stage_id);
create index if not exists leads_firm_email_idx on leads (law_firm_id, lower(email)) where email is not null;


create table if not exists intake_form_templates (
  id                uuid not null default gen_random_uuid(),
  law_firm_id       uuid not null references law_firms(id) on delete cascade,
  practice_area_id  uuid references practice_areas(id) on delete set null,
  name              text not null,
  public_token      text not null,
  fields            jsonb not null default '[]'::jsonb,
  access_code_hash  text,
  is_active         boolean not null default true,
  created_by        text references users(id) on delete restrict,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  unique (public_token)
);
-- intake_form_templates_firm_idx removed by migration 0195: covered by
-- intake_form_templates_law_firm_id_id_key.

create table if not exists intake_submissions (
  id                       uuid not null default gen_random_uuid(),
  law_firm_id              uuid not null references law_firms(id) on delete cascade,
  intake_form_template_id  uuid not null,
  token                    text not null,
  field_values             jsonb not null default '{}'::jsonb,
  status                   text not null default 'sent'
    check (status in ('sent', 'completed', 'rejected')),
  delivery_status          text not null default 'sent'
    check (delivery_status in ('pending', 'sent', 'failed')),
  lead_id                  uuid,
  sent_to_email            text,
  sent_by                  text references users(id) on delete restrict,
  sent_at                  timestamptz,
  opened_at                timestamptz,
  submitted_ip             text,
  created_at               timestamptz not null default now(),
  completed_at             timestamptz,
  primary key (id),
  unique (law_firm_id, id),
  unique (token),
  constraint intake_submissions_template_fk
    foreign key (law_firm_id, intake_form_template_id)
    references intake_form_templates(law_firm_id, id) on delete cascade,
  -- Single column, not (law_firm_id, lead_id). A composite key with ON DELETE
  -- SET NULL nulls EVERY column of the key, including the NOT NULL tenant
  -- column, so deleting a lead that had ever received or submitted an intake
  -- form failed with 23502 (migration 0187). Tenant scoping is unaffected:
  -- law_firm_id keeps its own CASCADE to law_firms and every read carries its
  -- own predicate.
  constraint intake_submissions_lead_fk
    foreign key (lead_id) references leads(id) on delete set null
);
create index if not exists intake_submissions_template_idx
  on intake_submissions (law_firm_id, intake_form_template_id);
create index if not exists intake_submissions_lead_idx
  on intake_submissions (law_firm_id, lead_id);

-- Column comments. These were written by earlier migrations and never carried
-- into the domain files, so a database built from schema.sql lacked them while
-- a migrated one had them. They are the reference for what each column means.
comment on column leads.stage_date is 'Date associated with the lead''s current stage (e.g. a scheduled consultation or follow-up date). Not tied to stage_id changing.';
comment on column matter_clients.billing_portion_bp is 'Share of this matter''s invoices this client pays, in basis points (10000 = 100%). Null means no split is configured. Portions across a matter must sum to 10000; enforced in matterClients service, not by a table check.';

-- >>> 40_tasks.sql <<<
-- =====================================================================
-- TASKS (+ junctions, notes)
-- =====================================================================

create table if not exists tasks (
  id                  uuid not null default gen_random_uuid(),
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  title               text not null,
  description         text,
  location            text,
  status              text not null default 'open'
    check (status in ('open', 'in_progress', 'completed', 'blocked')),
  priority            text not null default 'medium',   -- app-managed vocabulary
  due_date            date,
  due_date_timezone   text,
  due_at              timestamptz,                       -- time-precision companion for calendar sync (migration 0021)
  -- Optional end (migration 0039). Timed: an instant after due_at. All-day:
  -- the exclusive day after the last day, at noon UTC, as events.ends_at.
  ends_at             timestamptz,
  all_day             boolean not null default false,    -- all-day vs timed, captured from provider sync (migration 0099)
  source              text,
  matter_id             uuid,
  practice_area_id    uuid,
  court_id            uuid,
  -- calendar sync state (migration 0021): per-user provider event-id map + sync/modified stamps
  calendar_sync          jsonb,
  google_event_id        text,
  outlook_id             text,
  outlook_change_key     text,
  google_calendar_id     text,
  last_synced_to_google  timestamptz,
  last_synced_to_outlook timestamptz,
  google_last_modified   timestamptz,
  outlook_last_modified  timestamptz,
  recurrence             jsonb,
  reminder_recipient_ids text[] not null default '{}',
  send_reminder_early    boolean not null default false,
  created_by          text references users(id) on delete restrict,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  foreign key (law_firm_id, matter_id)          references matters (law_firm_id, id) on delete cascade,
  foreign key (practice_area_id) references practice_areas (id) on delete set null,
  foreign key (court_id)         references courts (id) on delete set null,
  constraint tasks_ends_after_start check (
    ends_at is null
    or (
      due_date is not null
      and ends_at > coalesce(due_at, (due_date + time '12:00') at time zone 'UTC')
    )
  )
);
create index if not exists tasks_firm_matter_idx on tasks (law_firm_id, matter_id);
create index if not exists tasks_firm_status_idx on tasks (law_firm_id, status);
-- FK probe support (see migration 0130): deleting a practice area, court or user.
create index if not exists tasks_practice_area_idx
  on tasks (practice_area_id) where practice_area_id is not null;
create index if not exists tasks_court_idx
  on tasks (court_id) where court_id is not null;
create index if not exists tasks_created_by_idx
  on tasks (created_by) where created_by is not null;
create index if not exists tasks_firm_due_idx on tasks (law_firm_id, due_date);

-- The three task junctions carry law_firm_id and a COMPOSITE foreign key to the
-- task (migration 0208). tasks.repository.ts guards each of these in the service
-- against a cross-firm write, with a comment on each saying the foreign key is
-- not firm-scoped; the composite key is what makes that a guarantee rather than
-- a convention a fourth writer could skip.
create table if not exists task_assignees (
  law_firm_id uuid not null references law_firms(id) on delete cascade,
  task_id uuid not null,
  user_id text not null references users(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (task_id, user_id),
  foreign key (law_firm_id, task_id) references tasks (law_firm_id, id) on delete cascade
);
create index if not exists task_assignees_user_idx on task_assignees (user_id);
-- Serves the composite foreign key's cascade; the primary key does not lead
-- with law_firm_id.
create index if not exists task_assignees_firm_task_idx on task_assignees (law_firm_id, task_id);
-- "My tasks" without scanning `tasks`: the assignee list is the selective side.
create index if not exists task_assignees_firm_user_idx on task_assignees (law_firm_id, user_id);

create table if not exists task_clients (
  law_firm_id uuid not null references law_firms(id) on delete cascade,
  task_id   uuid not null,
  -- Single-column, unlike the composite key the tenancy convention asks for.
  -- It predates the retirement of the SOFT-REFERENCE sweep (migrations 0224
  -- and 0225), which used to drop every key pointing at `clients`.
  client_id uuid not null references clients(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (task_id, client_id),
  foreign key (law_firm_id, task_id) references tasks (law_firm_id, id) on delete cascade
);
create index if not exists task_clients_firm_task_idx on task_clients (law_firm_id, task_id);
-- client-id-keyed cleanup (clients.repository deletes by client_id on client removal)
create index if not exists task_clients_client_idx on task_clients (client_id);

create table if not exists task_dependencies (
  law_firm_id        uuid not null references law_firms(id) on delete cascade,
  task_id            uuid not null,
  -- Both arms are firm-scoped. The second is the one the repository's cycle
  -- guard calls out as global, and the path a cross-tenant edge would take.
  depends_on_task_id uuid not null,
  created_at         timestamptz not null default now(),
  primary key (task_id, depends_on_task_id),
  check (task_id <> depends_on_task_id),
  foreign key (law_firm_id, task_id) references tasks (law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, depends_on_task_id) references tasks (law_firm_id, id) on delete cascade
);
create index if not exists task_dependencies_depends_on_idx on task_dependencies (depends_on_task_id);
create index if not exists task_dependencies_firm_task_idx on task_dependencies (law_firm_id, task_id);
create index if not exists task_dependencies_firm_depends_on_idx on task_dependencies (law_firm_id, depends_on_task_id);

-- Lightweight checklist / subtask items under a task.
create table if not exists task_subtasks (
  id                uuid not null default gen_random_uuid(),
  law_firm_id       uuid not null,
  task_id           uuid not null references tasks(id) on delete cascade,
  title             text not null,
  is_completed      boolean not null default false,
  assignee_user_id  text references users(id) on delete set null,
  sort_order        integer not null default 0,
  created_by        text references users(id) on delete restrict,
  completed_at      timestamptz,
  completed_by      text references users(id) on delete restrict,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id)
);
create index if not exists task_subtasks_task_idx on task_subtasks (task_id, sort_order);
-- Serves the on-delete walk of task_subtasks_assignee_user_id_fkey (migration 0224).
create index if not exists task_subtasks_assignee_user_id_idx on task_subtasks (assignee_user_id);

-- >>> 50_notes.sql <<<
create table if not exists note_types (
  id           uuid not null default gen_random_uuid(),
  law_firm_id  uuid not null references law_firms(id) on delete cascade,
  value        text not null,
  label        text not null,
  color        text,
  created_by   text references users(id) on delete restrict,
  created_at   timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  unique (law_firm_id, value)
);

create table if not exists note_templates (
  id            uuid not null default gen_random_uuid(),
  law_firm_id   uuid not null references law_firms(id) on delete cascade,
  label         text not null,
  note_type     text not null default 'general',
  subject       text not null default '',
  content_html  text not null default '',
  created_by    text references users(id) on delete restrict,
  created_at    timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id)
);

create index if not exists note_types_law_firm_idx on note_types (law_firm_id, label);
create index if not exists note_templates_law_firm_idx on note_templates (law_firm_id, label);

-- Firm-wide contact directory: the canonical record for every non-client person
-- or organization the firm deals with (opposing counsel, judges, experts,
-- adjusters, court reporters). Matters link to these through `matter_contacts`

-- =====================================================================
-- NOTES (matter, task and client, in one table)
-- =====================================================================
-- One `notes` table replaces `matter_notes`, `task_notes` and `client_notes`,
-- one `note_versions` replaces their three version tables, and one
-- `note_replies` replaces their three reply tables. Ten tables became four
-- (migration 0202).
--
-- The three were already ONE implementation: `shared/notes/notesEngine.ts`,
-- `notesRepository.ts`, `noteRepliesRepository.ts` and `notesRouter.ts` are
-- parameterized by table and by which column names the parent, and the fourteen
-- REST endpoints are generated from that factory. Only the storage was
-- triplicated, and the copies had already drifted: `matter_notes` grew four
-- columns the other two never got.
--
-- THE PARENT IS THREE NULLABLE FOREIGN KEYS, NOT A (parent_type, parent_id)
-- PAIR. That is the whole design decision here, and it is deliberate:
--
--   * A polymorphic `parent_id` can carry no foreign key, so deleting a matter
--     would leave its notes behind instead of cascading. Every note table today
--     cascades from its parent, and the app has no sweep that would replace it.
--   * The CHECK below makes "exactly one parent" a database rule rather than a
--     convention, which a polymorphic column cannot express either.
--   * The shared factories take a `parentColumn` name already, so pointing them
--     at one table is a smaller change than a discriminator would have been.
--
-- The clients foreign key is declared and kept. It used to be removed by the
-- SOFT-REFERENCE sweep, which migrations 0224 and 0225 retired, so deleting a
-- client now has to go through `clients.service.removeClient`, which deletes
-- the children itself in one transaction.

create table if not exists notes (
  id                  uuid primary key default gen_random_uuid(),
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  -- Exactly one of these three is set; see notes_one_parent below.
  matter_id           uuid,
  -- Composite, like the matter arm: a single-column link would let a note name
  -- a task in another firm (migration 0213).
  task_id             uuid,
  client_id           uuid,
  content             text not null default '',
  content_html        text,
  subject             text,
  note_type           text default 'general',
  mentions            jsonb not null default '[]',
  created_by          text references users(id) on delete restrict,
  edited_by           text references users(id) on delete restrict,
  edited_at           timestamptz,
  -- The date the work happened, set by the author. Separate from created_at,
  -- which is when the row was saved; a note written up on Friday about
  -- Tuesday's call belongs to Tuesday.
  note_date           date default current_date,
  pinned_at           timestamptz,
  pinned_by           text references users(id) on delete restrict,
  -- A note is retracted, never hard-deleted: it is a record of work performed,
  -- and its time entries and links point at it from the billing and task tables.
  retracted_at        timestamptz,
  retracted_by        text references users(id) on delete restrict,
  retraction_reason   text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (law_firm_id, id),
  foreign key (law_firm_id, task_id) references tasks (law_firm_id, id) on delete cascade,
  constraint notes_one_parent check (
    (matter_id is not null)::int + (task_id is not null)::int + (client_id is not null)::int = 1
  ),
  foreign key (law_firm_id, matter_id) references matters (law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, client_id) references clients (law_firm_id, id) on delete cascade
);
create index if not exists notes_matter_date_idx
  on notes (matter_id, note_date desc, created_at desc) where matter_id is not null;
create index if not exists notes_task_date_idx
  on notes (task_id, note_date desc, created_at desc) where task_id is not null;
create index if not exists notes_client_date_idx
  on notes (client_id, note_date desc, created_at desc) where client_id is not null;
create index if not exists notes_pinned_idx
  on notes (law_firm_id, pinned_at desc) where pinned_at is not null;
-- The firm-wide notes list orders by note_date across every matter in the firm.
-- Serves the composite foreign key to `tasks` added by migration 0213.
create index if not exists notes_firm_task_idx on notes (law_firm_id, task_id);
create index if not exists notes_firm_date_idx
  on notes (law_firm_id, note_date desc, created_at desc);
create index if not exists notes_author_idx
  on notes (law_firm_id, created_by) where created_by is not null;
create index if not exists notes_firm_matter_created_idx
  on notes (law_firm_id, matter_id, created_at desc, id desc) where matter_id is not null;
create index if not exists notes_firm_task_created_idx
  on notes (law_firm_id, task_id, created_at desc, id desc) where task_id is not null;
create index if not exists notes_firm_client_created_idx
  on notes (law_firm_id, client_id, created_at desc, id desc) where client_id is not null;

-- Append-only history of a note's prior states. Version N holds the content
-- that version N+1 replaced, written immediately before the update lands.
-- Scoped by note_id alone: the note already pins the parent.
create table if not exists note_versions (
  id              uuid primary key default gen_random_uuid(),
  law_firm_id     uuid not null references law_firms(id) on delete cascade,
  -- Composite: a single-column link guarantees the note exists but not that the
  -- version belongs to the same firm as the note it versions (migration 0213).
  note_id         uuid not null,
  version         integer not null,
  content         text not null default '',
  content_html    text,
  subject         text,
  note_type       text,
  note_date       date,
  edited_by       text references users(id) on delete restrict,
  created_at      timestamptz not null default now(),
  unique (note_id, version),
  unique (law_firm_id, id),
  foreign key (law_firm_id, note_id) references notes (law_firm_id, id) on delete cascade
);
create index if not exists note_versions_firm_note_idx on note_versions (law_firm_id, note_id);

-- Replies under a note: the note stays the work product, the conversation about
-- it lives here. The parent columns mirror `notes`, so a reply cascades with its
-- parent entity as well as with its note.
create table if not exists note_replies (
  id              uuid primary key default gen_random_uuid(),
  law_firm_id     uuid not null references law_firms(id) on delete cascade,
  -- A reply's parent is its note, and nothing else. It carried copies of the
  -- note's matter_id / task_id / client_id until migration 0207: written on
  -- every insert, never read back, and free to disagree with the note.
  note_id         uuid not null,
  content         text not null default '',
  content_html    text,
  mentions        jsonb not null default '[]',
  created_by      text references users(id) on delete restrict,
  edited_at       timestamptz,
  retracted_at    timestamptz,
  retracted_by    text references users(id) on delete restrict,
  retraction_reason text,
  parent_reply_id uuid references note_replies(id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (law_firm_id, id),
  foreign key (law_firm_id, note_id) references notes (law_firm_id, id) on delete cascade
);
create index if not exists note_replies_note_idx on note_replies (note_id, created_at);
create index if not exists note_replies_firm_note_idx on note_replies (law_firm_id, note_id);
create index if not exists note_replies_parent_idx on note_replies (parent_reply_id);

-- Connections out of a note: to a task, or to a document. One row per
-- connection, discriminated by link_type. file_id carries no foreign key on
-- purpose: `files` is a best-effort mirror of GCS written outside the request
-- transaction, so a mirror gap must not be able to reject a link the user can
-- plainly see in the file browser. Matter notes are the only kind that links
-- today; the table is parent-agnostic because the note already names the parent.
create table if not exists note_links (
  id            uuid primary key default gen_random_uuid(),
  law_firm_id   uuid not null references law_firms(id) on delete cascade,
  note_id       uuid not null,
  link_type     text not null check (link_type in ('task', 'file')),
  -- The FK to tasks is added in DEFERRED CROSS-TABLE FOREIGN KEYS below, since
  -- `tasks` is created after this table.
  task_id       uuid,
  file_id       uuid,
  -- Set when the link was made from a reply rather than the note itself.
  reply_id      uuid references note_replies(id) on delete set null,
  -- True when the linked record was created from the note rather than picked
  -- from a list. Drives the "Created from this note" label.
  created_from_note boolean not null default false,
  created_by    text references users(id) on delete restrict,
  created_at    timestamptz not null default now(),
  -- Exactly one target, matching link_type. Added by migration 0202; a link
  -- row that names neither a task nor a file has no meaning, and one that
  -- names both is ambiguous to every reader.
  constraint note_links_target_ck check (
    (link_type = 'task' and task_id is not null and file_id is null) or
    (link_type = 'file' and file_id is not null and task_id is null)
  ),
  unique (law_firm_id, id),
  foreign key (law_firm_id, note_id) references notes (law_firm_id, id) on delete cascade
);
-- Partial uniques rather than one composite unique: Postgres treats nulls as
-- distinct, so a composite key over two nullable target columns would let the
-- same link be inserted twice.
create unique index if not exists note_links_task_uniq
  on note_links (note_id, task_id) where task_id is not null;
create unique index if not exists note_links_file_uniq
  on note_links (note_id, file_id) where file_id is not null;
create index if not exists note_links_note_idx on note_links (note_id);
create index if not exists note_links_firm_note_idx on note_links (law_firm_id, note_id);
create index if not exists note_links_firm_task_idx on note_links (law_firm_id, task_id);
create index if not exists note_links_task_idx
  on note_links (law_firm_id, task_id) where task_id is not null;
create index if not exists note_links_file_idx
  on note_links (law_firm_id, file_id) where file_id is not null;

-- Append-only chronological activity feed for a matter (also an audit trail).
-- One activity feed for all three parents, not a matter-only one (migration
-- 0214). The client and task arms are empty today and exist so the feed is not
-- built a second and third time, which is what happened to notes and events.
create table if not exists activity_log (
  id                uuid not null default gen_random_uuid(),
  law_firm_id       uuid not null,
  -- Exactly one parent; see activity_log_one_parent below.
  matter_id         uuid,
  client_id         uuid,
  task_id           uuid,
  activity_type     text not null,
  actor_user_id     text references users(id) on delete restrict,
  actor_name        text,
  summary           text not null,
  metadata          jsonb not null default '{}',
  created_at        timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  constraint activity_log_one_parent check (num_nonnulls(matter_id, client_id, task_id) = 1),
  foreign key (law_firm_id, matter_id) references matters (law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, task_id) references tasks (law_firm_id, id) on delete cascade
);
-- listForMatter filters (law_firm_id, matter_id) and orders by (created_at
-- desc, id desc), optionally narrowing by activity_type. Both indexes carry the
-- tenant column first and the full sort key, so the paged read needs no sort
-- step (migration 0206). They differ at the third column, so neither is a
-- redundant prefix of the other.
create index if not exists activity_log_firm_matter_time_idx
  on activity_log (law_firm_id, matter_id, created_at desc, id desc);
-- Supports the timeline's "Notes only" filter without scanning the matter's
-- whole history.
create index if not exists activity_log_firm_matter_type_time_idx
  on activity_log (law_firm_id, matter_id, activity_type, created_at desc);
-- One partial index per arm, so a feed read seeks rather than scanning a column
-- that is null for almost every row (migration 0214).
create index if not exists activity_log_firm_client_time_idx
  on activity_log (law_firm_id, client_id, created_at desc, id desc)
  where client_id is not null;
create index if not exists activity_log_firm_task_time_idx
  on activity_log (law_firm_id, task_id, created_at desc, id desc)
  where task_id is not null;

-- >>> 60_calendar.sql <<<
-- =====================================================================
-- CALENDAR
-- =====================================================================

create table if not exists calendar_events (
  id                    uuid primary key default gen_random_uuid(),
  stable_id             text,
  law_firm_id           uuid not null references law_firms(id) on delete cascade,
  title                 text not null,
  description           text,
  notes                 text,
  location              text,
  starts_at             timestamptz,
  ends_at               timestamptz,
  all_day               boolean not null default false,
  provider              text check (provider in ('google','outlook')),
  source                text,
  external_event_id     text,
  google_event_id       text,
  outlook_id            text,
  outlook_change_key    text,
  calendar_id           text,
  start_time_zone       text,
  -- Provider-owned meeting snapshot. These people need not have local records.
  provider_details      jsonb not null default '{}',
  last_synced_to_google timestamptz,
  last_synced_to_outlook timestamptz,
  google_last_modified  timestamptz,
  outlook_last_modified timestamptz,
  -- (migration 0016) the invitation's iCalendar UID, the same on Google and
  -- Outlook, and the provider id of the series this row is an occurrence of.
  ical_uid              text,
  series_event_id       text,
  created_by            text references users(id) on delete restrict,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now()
);
create index if not exists calendar_events_google_idx on calendar_events (law_firm_id, google_event_id) where google_event_id is not null;
create index if not exists calendar_events_outlook_idx on calendar_events (law_firm_id, outlook_id) where outlook_id is not null;
create index if not exists calendar_events_stable_id_idx on calendar_events (law_firm_id, stable_id);
-- (migration 0125): the calendar reads external events for a firm over the date
-- range it is drawing, which the firm-only indexes cannot narrow.
create index if not exists calendar_events_firm_start_idx on calendar_events (law_firm_id, starts_at);
create index if not exists calendar_events_ical_uid_idx
  on calendar_events (law_firm_id, created_by, ical_uid) where ical_uid is not null;
create index if not exists calendar_events_series_idx
  on calendar_events (law_firm_id, created_by, series_event_id) where series_event_id is not null;
-- (migration 0036) every member imports their own copy of a shared Google
-- meeting, which carries the same event id on every attendee's calendar, so the
-- inbound lookup is per owner.
create index if not exists calendar_events_owner_google_idx
  on calendar_events (law_firm_id, created_by, google_event_id) where google_event_id is not null;

-- Calendar sync ENGINE bookkeeping (relational, migration 0031; formerly jsonb
-- kv tables, now real columns). Provider event id -> source Paralegix entity is
-- resolved via entity_type/entity_id/scope_id.
create table if not exists calendar_mappings (
  provider          text not null check (provider in ('google','outlook')),
  external_event_id text not null,
  calendar_id       text,
  user_id           text references users(id) on delete restrict,
  law_firm_id       uuid references law_firms(id) on delete cascade,
  entity_type       text
    check (entity_type is null or entity_type in
      ('task', 'matterEvent', 'clientEvent', 'externalEvent', 'invoiceBilling')),
  entity_id         text,
  scope_id          text,           -- matterId / clientId / lawFirmId for nested entities
  item_key          text,
  -- (migration 0036) the version the provider reported for this member's copy
  -- right after Paralegix last wrote it (Google etag, Outlook changeKey) and its
  -- modified time, so an inbound echo of that write is recognised per copy.
  pushed_version    text,
  pushed_modified_at timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  primary key (provider, external_event_id)
);
create index if not exists calendar_mappings_entity_idx on calendar_mappings (entity_type, entity_id);
create index if not exists calendar_mappings_user_idx on calendar_mappings (user_id);

-- One row per provider push subscription. Google calls it a watch channel and
-- Outlook calls it a subscription; they carry the same seven facts, so they are
-- one table discriminated by `provider` (migration 0203). The two
-- provider-specific names are generalized:
--
--   google  resource_id -> resource, token        -> secret
--   outlook resource    -> resource, client_state -> secret
--
-- `calendarSync.repository` keeps returning each provider's own key names, so
-- no caller of that module learns about this.
create table if not exists calendar_subscriptions (
  id                    text primary key,   -- Google channel id / Graph subscription id
  provider              text not null check (provider in ('google','outlook')),
  user_id               text references users(id) on delete restrict,   -- auth uid (soft-referenced; may have no app users row)
  law_firm_id           uuid references law_firms(id) on delete cascade,
  calendar_id           text,
  -- Google: the resource id its channel watches. Outlook: the Graph resource path.
  resource              text,
  -- The shared secret echoed back on a push, so a notification can be
  -- authenticated. Google's channel token; Outlook's clientState.
  secret                text,
  expiration            timestamptz,
  last_outbound_push_at timestamptz,
  created_at            timestamptz not null default now()
);
create index if not exists calendar_subscriptions_user_idx
  on calendar_subscriptions (provider, user_id);
create index if not exists calendar_subscriptions_expiration_idx
  on calendar_subscriptions (provider, expiration);
create index if not exists calendar_subscriptions_firm_idx
  on calendar_subscriptions (law_firm_id);

-- One durable retry / dead-letter queue for two kinds of failed calendar work
-- (migration 0215 merged `calendar_webhook_failures` and
-- `google_watch_channel_stop_failures`).
--
--   webhook       A push notification that failed to process. Retrying means
--                 re-running the user's incremental sync, which is idempotent,
--                 so repeated failures for one (provider, user) coalesce onto a
--                 single row rather than queueing per event.
--   stop_channel  A Google watch channel this backend failed to stop. The
--                 calendar_subscriptions row is deleted after every stop attempt
--                 and holds the only copy of the id + resource id that
--                 channels/stop needs, so an unstopped channel is written here
--                 first; otherwise Google keeps pushing to a channel nothing can
--                 address.
--
-- NOT a union of the two old column lists, which would have left five columns
-- permanently null per kind and needed a partial unique per kind so each could
-- match its own `on conflict` target. The two queues differ only in what makes a
-- row unique, the retry budget, and whether a row can go stale on its own, so
-- `dedupe_key` holds whatever identifies the item for its kind, `payload` holds
-- the arguments to re-run it, and the budget stays in code.
create table if not exists calendar_sync_failures (
  id              uuid primary key default gen_random_uuid(),
  -- Nullable, and no foreign key: a webhook failure is recorded from the
  -- provider's push before the firm has been resolved. Nothing cascades these,
  -- which is why deleteWebhookFailuresForLawFirm exists.
  law_firm_id     uuid,
  -- 'webhook' is also an inbound push persisted before it is processed (a
  -- pending row); 'outbound' (migration 0036) is a provider write that failed
  -- transiently.
  kind            text not null check (kind in ('webhook', 'stop_channel', 'outbound')),
  -- Unique WITHIN its kind: 'google:<uid>' for a webhook, the channel id for a
  -- stop. Coalescing on it stops a storm of failures becoming a storm of rows.
  dedupe_key      text not null,
  provider        text check (provider is null or provider in ('google', 'outlook')),
  user_id         text references users(id) on delete restrict,
  -- The arguments needed to re-run the work: changeType / eventId / resource for
  -- a webhook, resourceId for a stop. Job arguments, not a relation.
  payload         jsonb not null default '{}',
  -- Past this the row is pointless rather than merely overdue. Only a channel
  -- sets it, from its own 7-day expiry at Google.
  expires_at      timestamptz,
  attempts        integer not null default 0,
  next_attempt_at timestamptz not null default now(),
  last_error      text,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (kind, dedupe_key)
);
create index if not exists calendar_sync_failures_due_idx
  on calendar_sync_failures (kind, next_attempt_at);
create index if not exists calendar_sync_failures_firm_idx
  on calendar_sync_failures (law_firm_id)
  where law_firm_id is not null;

-- Events are relational (migration 0027). Hybrid: columns for queryable,
-- scoping and sync fields, jsonb for irregular nested data.
--
-- ONE TABLE FOR BOTH PARENTS (migration 0205). This was `matter_events` and
-- `client_events`, two tables sharing 26 identically-typed columns -- the whole
-- core plus every provider-sync column -- and two repositories whose methods
-- differed only in which column named the parent. The parent is now two nullable
-- foreign keys with a CHECK rather than a (parent_type, parent_id) pair, for the
-- reason migration 0202 gives for notes: a polymorphic parent id can carry no
-- foreign key, and both halves cascade from their parent today.
--
-- `calendar_events` is deliberately NOT part of this. It holds events synced
-- INTO Paralegix from Google and Outlook; these are the firm's own records,
-- which sync OUT. Opposite directions, different lifecycles.
create table if not exists events (
  id                     uuid primary key default gen_random_uuid(),
  law_firm_id            uuid not null references law_firms(id) on delete cascade,

  -- Exactly one of these is set; see events_parent_ck below. The FK to `clients`
  -- is declared and kept: the SOFT-REFERENCE sweep that used to drop it was
  -- retired by migrations 0224 and 0225, and clients.service does the cleanup.
  matter_id              uuid references matters(id) on delete cascade,
  client_id              uuid references clients(id) on delete cascade,

  -- ---- shared by both parents ----
  type                   text
    check (type is null or type in (
      'court_date', 'hearing', 'deposition', 'filing_deadline', 'discovery_cutoff',
      'mediation', 'arbitration', 'trial', 'appeal_deadline',
      'statute_of_limitations', 'meeting', 'other')),
  title                  text not null,
  notes                  text,
  location_name          text,
  location               text,
  status                 text not null default 'upcoming'
    check (status in ('upcoming', 'completed', 'cancelled')),
  date                   timestamptz,
  -- The event's end, so it syncs with its real duration. Nullable because an end
  -- is genuinely optional: a filing deadline is an instant, not a span, and the
  -- sync engine falls back to a one-hour block for those (migration 0220).
  ends_at                timestamptz,
  all_day                boolean not null default false,   -- all-day vs timed, captured from provider sync (migration 0099)
  created_by             text references users(id) on delete restrict,
  client_visible         boolean not null default false,   -- surfaces in the client portal agenda
  -- [{ fileId, name, size, contentType, scope, scopeId, linkedBy, linkedAt }]
  -- `fileId` is the link; the rest is a snapshot the calendar renders without a
  -- join. It was the object path, which a rename or a move rewrote.
  linked_files           jsonb not null default '[]',
  google_event_id        text,
  outlook_id             text,
  outlook_change_key     text,
  google_calendar_id     text,
  calendar_sync          jsonb not null default '{}',
  last_synced_to_google  timestamptz,
  last_synced_to_outlook timestamptz,
  google_last_modified   timestamptz,
  outlook_last_modified  timestamptz,

  -- ---- matter events only; left at their defaults on a client event ----
  -- These are per-parent FEATURES, not drift: a standalone client event has
  -- never had recurrence, dependencies, cancellation lineage, postponement
  -- history or reminder state.
  depends_on             jsonb not null default '[]',
  recurrence             jsonb,
  time_zone              text,
  client_description     text,
  recurrence_group_id    text,
  recurrence_index       int,
  is_recurrence_parent   boolean not null default false,
  cancellation_reason    text,
  cancelled_by           text references users(id) on delete restrict,
  cancelled_at           timestamptz,
  postponement_count     int not null default 0,
  postponement_history   jsonb not null default '[]',

  -- ---- client events only; null on a matter event, whose MATTER carries one ----
  -- Single-column FK, matching matters.court_id and contacts.court_id: an
  -- ON DELETE SET NULL on a composite (law_firm_id, court_id) key would null the
  -- NOT NULL tenant column too. Tenant agreement is the service's job.
  -- The court's NAME is read by joining `courts`, the way matters.repository,
  -- tasks.repository and contacts.repository all read it; the denormalized
  -- court_name copy client_events carried was dropped with the merge.
  court_id               uuid references courts (id) on delete set null,

  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),

  unique (law_firm_id, id),
  -- An end before its start is a data error, not a short event: the engine only
  -- honours an end strictly after the start and would silently discard it.
  constraint events_ends_after_start check (ends_at is null or date is null or ends_at > date),
  constraint events_parent_ck check (
    (matter_id is not null and client_id is null) or
    (client_id is not null and matter_id is null)
  )
);
-- Serves the on-delete walk of events_client_id_fkey (migration 0225).
create index if not exists events_client_id_idx on events (client_id);
-- Partial on the parent so a scan for one kind of event does not walk the other.
create index if not exists events_matter_fk_idx
  on events (matter_id) where matter_id is not null;
create index if not exists events_firm_matter_date_idx
  on events (law_firm_id, matter_id, date) where matter_id is not null;
create index if not exists events_firm_client_date_idx
  on events (law_firm_id, client_id, date) where client_id is not null;
-- (migration 0125, now covering both parents): the calendar reads events
-- firm-wide over the date range it is drawing, which neither per-parent index
-- above can narrow.
create index if not exists events_firm_date_idx on events (law_firm_id, date);
create index if not exists events_firm_status_date_idx on events (law_firm_id, status, date);
create index if not exists events_google_idx on events (google_event_id) where google_event_id is not null;
create index if not exists events_outlook_idx on events (outlook_id) where outlook_id is not null;
create index if not exists events_recur_idx on events (recurrence_group_id) where recurrence_group_id is not null;
create index if not exists events_client_visible_idx
  on events (law_firm_id, matter_id, date) where client_visible and status <> 'cancelled';
create index if not exists events_court_idx on events (court_id) where court_id is not null;
-- Named `set_updated_at`, which is also what the whole-schema trigger sweep at
-- the foot of schema.sql creates. A differently-named trigger here would leave a
-- schema.sql-built database carrying TWO of them and a migrated one carrying a
-- different single trigger, which is the drift migration 0202 avoided the same way.
drop trigger if exists set_updated_at on events;
create trigger set_updated_at before update on events
  for each row execute function set_updated_at();

-- Attendees who are not firm members. `event_assignees` covers the firm's own
-- people; a deposition or mediation also involves opposing counsel, a court
-- reporter and an expert, and those are directory contacts.
-- (migrations 0136 and 0178, merged into one table by 0205.)
-- Assignees are ROWS, not a jsonb array (migration 0218), mirroring
-- task_assignees. The array held a list of ids the application joined on,
-- which nothing could constrain: no key to users, so a removed member was
-- pruned by a listener rather than a cascade, and the digest's containment
-- test had no index to use. Names are joined from users at read.
create table if not exists event_assignees (
  law_firm_id uuid not null references law_firms(id) on delete cascade,
  event_id    uuid not null,
  user_id     text not null references users(id) on delete cascade,
  created_at  timestamptz not null default now(),
  primary key (event_id, user_id),
  foreign key (law_firm_id, event_id) references events (law_firm_id, id) on delete cascade
);
create index if not exists event_assignees_firm_event_idx on event_assignees (law_firm_id, event_id);
-- "My calendar" without scanning events, the shape task_assignees has for tasks.
create index if not exists event_assignees_firm_user_idx on event_assignees (law_firm_id, user_id);
-- Serves the on-delete walk of event_assignees_user_id_fkey (migration 0224).
create index if not exists event_assignees_user_id_idx on event_assignees (user_id);

create table if not exists event_contacts (
  id            uuid primary key default gen_random_uuid(),
  law_firm_id   uuid not null references law_firms(id) on delete cascade,
  event_id      uuid not null references events(id) on delete cascade,
  contact_id    uuid not null,
  created_at    timestamptz not null default now(),
  unique (law_firm_id, id),
  constraint event_contacts_unique_link unique (law_firm_id, event_id, contact_id),
  foreign key (law_firm_id, contact_id) references contacts (law_firm_id, id) on delete cascade
);
create index if not exists event_contacts_contact_idx on event_contacts (law_firm_id, contact_id);

-- Deadline Set templates (migration 0112). A firm-defined recipe that turns one
-- trigger/anchor date into a cascade of matter events. `items` is jsonb: an
-- ordered array of { title, type, offsetDays, offsetDirection, relativeTo,
-- clientVisible, notes } where `type` is a matter-event type,
-- `offsetDirection` is 'before' | 'after', and `relativeTo` is
-- 'trigger' | 'previous' (the date computed for the item before it in the
-- array; always 'trigger' for the first item).
create table if not exists deadline_set_templates (
  id                   uuid not null default gen_random_uuid(),
  law_firm_id          uuid not null references law_firms(id) on delete cascade,
  name                 text not null,
  description          text,
  adjust_for_weekends  boolean not null default false,
  items                jsonb not null default '[]',
  created_by           text references users(id) on delete restrict,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id)
);

-- >>> 70_billing.sql <<<
-- =====================================================================
-- BILLING
-- =====================================================================

-- The firm's pick lists for work: charge codes (`kind = 'charge'`, which carry
-- an hourly rate) and expense categories (`kind = 'expense'`). One table since
-- migration 0231; the two route files each filter on their kind, so the API
-- did not change. Ids were preserved, so `activities.billing_code_id` (the
-- former `charge_code_id` and `expense_category_id`) points here unchanged.
create table if not exists billing_codes (
  id             uuid primary key default gen_random_uuid(),
  law_firm_id    uuid not null references law_firms(id) on delete cascade,
  kind           text not null check (kind in ('charge', 'expense')),
  code           text not null,
  name           text not null,
  is_active      boolean not null default true,
  -- Seeded by the application rather than entered by the firm. Only expense
  -- categories are seeded lazily today; charge codes are seeded at firm
  -- creation and were never flagged.
  is_default     boolean not null default false,
  sort_order     int,
  -- Charge codes only: the hourly rate in dollars, and per-member overrides.
  default_rate   numeric,
  default_rate_cents bigint check (default_rate_cents is null or default_rate_cents >= 0),
  member_rates   jsonb not null default '{}',
  -- Provenance link to the UTBMS code this was adopted from; null is a custom code.
  utbms_code_id  uuid references utbms_codes(id) on delete set null,
  created_by     text references users(id) on delete restrict,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  unique (law_firm_id, id),
  unique (law_firm_id, kind, code),
  constraint billing_codes_rate_only_on_charge check (
    kind = 'charge' or (default_rate is null and default_rate_cents is null and member_rates = '{}'::jsonb)
  )
);
create index if not exists billing_codes_firm_kind_idx on billing_codes (law_firm_id, kind, sort_order);
create index if not exists billing_codes_utbms_idx
  on billing_codes (law_firm_id, utbms_code_id) where utbms_code_id is not null;

create table if not exists invoices (
  id                          uuid not null default gen_random_uuid(),
  law_firm_id                 uuid not null references law_firms(id) on delete cascade,
  matter_id                     uuid,
  client_context_id           uuid references clients(id) on delete restrict,  -- part of the XOR check below; restrict, so a client with invoices cannot be deleted
  client_id                   uuid references clients(id) on delete set null,
  context_type                text
    check (context_type is null or context_type in ('matter', 'client')),
  invoice_name                text,
  invoice_number              text not null,
  invoice_date                date,
  due_date                    date,
  billing_email               citext,
  notes                       text,
  client_name                 text,
  client_email                citext,
  matter_client_id              uuid,
  remit_to                    text,
  remit_to_name               text,
  remit_to_address            text,
  remit_to_city               text,
  remit_to_state              text,
  remit_to_zip                text,
  -- 'draft' is the column default, written by _createTx and then overwritten in
  -- the same transaction by deriveInvoiceStatus, which never returns it, so no
  -- stored invoice reads 'draft'. 'voided' is written by the void route and is
  -- terminal: deriveInvoiceStatus keeps it, every money total excludes it, and
  -- the billed-source trigger ignores line items on it.
  status                      text not null default 'draft'
    check (status in ('draft', 'outstanding', 'overdue', 'partially_paid', 'paid', 'credited', 'voided')),
  total_cents                 bigint not null default 0 check (total_cents >= 0),
  flat_fees_amount_cents      bigint not null default 0,
  tax_rate                    numeric,                       -- optional sales/gross-receipts tax %
  tax_cents                   bigint not null default 0,     -- computed tax, already included in total_cents
  total_hours                 numeric,
  amount_paid_cents           bigint not null default 0 check (amount_paid_cents >= 0),
  -- Accounts for write-offs so fully-written-off invoices are not treated as
  -- outstanding by invoices_outstanding_idx. Matches the app's remainingBalance
  -- (total - amountPaid - totalWrittenOff).
  balance_due_cents           bigint generated always as (total_cents - amount_paid_cents - coalesce(total_written_off_cents, 0)) stored,
  total_written_off_cents     bigint not null default 0,
  is_paid                     boolean not null default false,
  paid_date                   timestamptz,
  next_payment_date           date,
  -- payment-plan header (the installment schedule lives in invoice_expected_payments)
  payment_plan_enabled        boolean not null default false,
  plan_installment_cents      bigint,
  plan_frequency_days         int,
  plan_start_date             date,
  plan_regular_start_date     date,
  plan_down_payment_cents     bigint,
  plan_pre_reminder_days      int,
  billing_plan_id             uuid,
  billing_plan_period_id      uuid,
  billing_plan_name           text,
  billing_plan_type           text
    check (billing_plan_type is null or billing_plan_type in ('retainer')),
  is_recurring_retainer       boolean not null default false,
  split_group_id              uuid,
  split_mode                  text,
  split_recipient_count       int,
  split_share_cents           bigint check (split_share_cents is null or split_share_cents >= 0),
  split_share_percent         numeric,
  stripe_invoice_id           text,
  -- Account the hosted invoice / checkout session was created on: 'platform' or an
  -- acct_ id. Null = unknown (row predates the column); teardown then uses the
  -- firm's current charge setup.
  stripe_invoice_account_id   text,
  stripe_checkout_session_id  text,
  stripe_checkout_session_account_id text,
  stripe_payment_intent_id    text,
  -- The application's words, not Stripe's: stripe.service.ts maps open / void /
  -- uncollectible / paid onto these four before any write.
  stripe_payment_status       text
    check (stripe_payment_status is null or stripe_payment_status in ('completed', 'pending', 'voided', 'failed')),
  stripe_payment_requested    boolean not null default false,
  stripe_payment_requested_by text references users(id) on delete restrict,
  google_last_modified        timestamptz,
  outlook_last_modified       timestamptz,
  -- per-user calendar_sync map + cross-sync stamps for billing calendar items (migration 0031)
  calendar_sync               jsonb,
  last_synced_to_google       timestamptz,
  last_synced_to_outlook      timestamptz,
  created_by                  text references users(id) on delete restrict,
  updated_by                  text references users(id) on delete restrict,
  created_at                  timestamptz not null default now(),
  updated_at                  timestamptz not null default now(),
  -- Billing recipient / bill-to snapshot (organization-clients plan). Recorded
  -- once, atomically, on an invoice's first external issue so later roster
  -- changes never rewrite billing history; null/empty until then, including
  -- on newly drafted invoices. billing_client_address mirrors clients.address
  -- (plain text) - there is no structured street/city/state/zip anywhere on
  -- the client model, unlike the firm's own remit_to_* address.
  billing_emails               text[] not null default '{}',
  -- Client display/legal name, distinct from billing_contact_name (the
  -- attention contact, a company roster contact).
  billing_client_name          text,
  billing_contact_name         text,
  billing_contact_title        text,
  billing_contact_email        text,
  billing_client_address       text,
  billing_snapshot_at          timestamptz,
  -- Who pays the online processing fee on this invoice's payment request, per
  -- method: false means the firm absorbs it, true adds it on top of what the
  -- client pays. Set when the firm requests payment (migration 0041).
  is_card_fee_passed_on        boolean not null default false,
  is_bank_fee_passed_on        boolean not null default false,
  -- The secure payment link's token, the only credential for the no-login pay
  -- page. Null until the firm requests payment; a new request replaces it and
  -- voiding the request clears it (migration 0042).
  pay_link_token               text,
  -- The payment-plan installment the payment link asks for, by the row's
  -- stable installment_id; null asks for the full balance (migration 0044).
  pay_link_installment_id      text,
  -- A card-form PaymentIntent waiting on the client's bank or on Stripe, and
  -- the account it lives on. Nothing else may charge the invoice while it is
  -- set (migration 0047).
  stripe_card_payment_intent_id text,
  stripe_card_payment_intent_account_id text,
  primary key (id),
  unique (law_firm_id, id),
  foreign key (law_firm_id, matter_id) references matters (law_firm_id, id) on delete cascade,
  check ( (matter_id is not null) <> (client_context_id is not null) )
);
create unique index if not exists invoices_pay_link_token_key
  on invoices (pay_link_token)
  where pay_link_token is not null;
-- invoices_number_idx removed by migration 0195: the planner prefers
-- invoices_number_unique_idx for the (law_firm_id, invoice_number) lookup either way.
-- BL3 (migration 0034): a firm's invoice_number must be unique (allocator-backed).
create unique index if not exists invoices_number_unique_idx
  on invoices (law_firm_id, invoice_number)
  where invoice_number is not null and invoice_number <> '';
-- BL11 (migration 0034): a firm's invoice_name must be unique within a billing context.
create unique index if not exists invoices_name_unique_idx
  on invoices (law_firm_id, coalesce(matter_id, client_context_id), lower(invoice_name))
  where invoice_name is not null and invoice_name <> '';
-- (migration 0050): supports the left-anchored `invoice_name LIKE 'prefix%'` prefix
-- scan in billingReads.nextInvoiceNumber's non-authoritative next-number preview.
create index if not exists invoices_name_prefix_idx
  on invoices (law_firm_id, invoice_name text_pattern_ops)
  where invoice_name is not null;
-- invoices_firm_due_idx removed by migration 0195: its `status <> 'paid'` predicate is
-- unreachable (no query uses it) and invoices_firm_due_all_idx covers the columns.
-- (migration 0125): unpartitioned twin of the above, for the calendar's date-window
-- probe. That probe has no status predicate and must see paid invoices too, so the
-- partial index cannot serve it.
create index if not exists invoices_firm_due_all_idx on invoices (law_firm_id, due_date);
create index if not exists invoices_outstanding_idx on invoices (law_firm_id) where balance_due_cents > 0;
-- FK probe support (see migration 0130): deleting a client or a billing plan.
create index if not exists invoices_client_fk_idx
  on invoices (client_id) where client_id is not null;
create index if not exists invoices_billing_plan_idx
  on invoices (billing_plan_id) where billing_plan_id is not null;
create index if not exists invoices_billing_plan_period_idx
  on invoices (billing_plan_period_id) where billing_plan_period_id is not null;
-- (migration 0122): the matters list sums each row's invoices for its outstanding
-- balance and billed-to-date figures, correlating on (law_firm_id, matter_id).
-- Without this the nearest index is (law_firm_id, id), so every invoice in the firm
-- is read once per row on the page. Costs scale with firm invoice count, not page size.
create index if not exists invoices_firm_matter_idx
  on invoices (law_firm_id, matter_id)
  where matter_id is not null;




-- One row per time-entry / flat-fee / expense line on an invoice. Every field
-- the app reads by name is a real column (split allocations, recurring plan
-- fees, LEDES utbms task/activity codes…); there is no value-bag jsonb.
-- source_id is text because line ids aren't always uuids.
create table if not exists invoice_line_items (
  id                 uuid primary key default gen_random_uuid(),
  invoice_id         uuid not null references invoices(id) on delete cascade,
  law_firm_id        uuid not null references law_firms(id) on delete cascade,
  -- The formulation that makes a child pointing at an invoice in another firm
  -- impossible rather than merely unusual (migration 0246).
  foreign key (law_firm_id, invoice_id) references invoices (law_firm_id, id) on delete cascade,
  kind               text not null check (kind in ('time_entry','flat_fee','expense')),
  sort_order         int not null default 0,
  source_id          text,
  name               text,
  description        text,
  line_date          date,
  quantity           numeric,
  rate_cents         bigint,
  amount_cents       bigint not null default 0,
  user_id            text references users(id) on delete restrict,
  user_name          text,
  charge_code_id     uuid,
  allocation_percent numeric,
  allocation_amount_cents bigint,
  utbms_task_code     text,                 -- LEDES 1998B task code
  utbms_activity_code text                  -- LEDES 1998B activity code
);
create index if not exists invoice_line_items_invoice_idx on invoice_line_items (invoice_id, kind, sort_order);
create index if not exists invoice_line_items_firm_invoice_idx on invoice_line_items (law_firm_id, invoice_id);
-- "Is this entry already billed?" is answered by looking for a line item whose
-- (kind, source_id) points back at the row; the work tables' own billed columns
-- are never maintained (billingReads.isSourceBilled). NOT unique: billingReads
-- documents that a source may appear on more than one line and that the first
-- row wins, so uniqueness would refuse a write the code tolerates (0206).
create index if not exists invoice_line_items_source_idx
  on invoice_line_items (kind, source_id)
  where source_id is not null;

-- payments[] -- ordered; expectedPayments.matchedPaymentIndex is the array
-- position, so sort_order is the index consumers rely on.
create table if not exists invoice_payments (
  id                       uuid primary key default gen_random_uuid(),
  invoice_id               uuid not null references invoices(id) on delete cascade,
  law_firm_id              uuid not null references law_firms(id) on delete cascade,
  -- The formulation that makes a child pointing at an invoice in another firm
  -- impossible rather than merely unusual (migration 0246).
  foreign key (law_firm_id, invoice_id) references invoices (law_firm_id, id) on delete cascade,
  sort_order               int not null default 0,
  amount_cents             bigint not null,
  payment_date             date,
  payment_source           text,
  note                     text,
  recorded_by              text references users(id) on delete restrict,
  invoice_number           text,
  trust_transaction_id     uuid,
  trust_account_id         uuid,
  stripe_session_id        text,
  stripe_invoice_id        text,
  stripe_payment_intent_id text,
  -- Cumulative amount reversed by Stripe (refund/dispute) for this payment. Stripe's
  -- charge.amount_refunded is cumulative, so tracking what we've already reversed lets
  -- the reversal converge to (original - amount_refunded) idempotently across multiple
  -- partial refunds and out-of-order webhook deliveries.
  stripe_refunded_cents    bigint not null default 0 check (stripe_refunded_cents >= 0),
  -- Connect charge model this payment was collected under (docs/DIRECT_CHARGE_MIGRATION.md).
  -- 'destination' = destination charge on the platform (platform bears disputes, current
  -- default); 'direct' = direct charge on the firm's connected account (firm bears them).
  -- Webhook refund/dispute handlers branch on this during the coexistence window.
  -- Only ever written as 'destination' today: Phase 0 of that migration lands the
  -- column ahead of the behaviour, so an unused value here is expected.
  charge_model             text not null default 'destination' check (charge_model in ('destination','direct')),
  -- The part of stripe_refunded_cents that a dispute took, so a won dispute
  -- restores only what it removed and never a refund that really went back.
  stripe_disputed_cents    bigint not null default 0,
  -- The processing fee the client paid on top of this payment, kept apart from
  -- amount_cents so it never counts toward the invoice balance (migration 0041).
  surcharge_cents          bigint not null default 0,
  -- Fee reversals are separate from invoice money. The disputed portion is
  -- restored only when Stripe reports the dispute won.
  surcharge_refunded_cents bigint not null default 0,
  surcharge_disputed_cents bigint not null default 0,
  constraint invoice_payments_stripe_disputed_cents_check
    check (stripe_disputed_cents >= 0 and stripe_disputed_cents <= stripe_refunded_cents),
  constraint invoice_payments_surcharge_cents_check check (surcharge_cents >= 0),
  constraint invoice_payments_surcharge_refunded_cents_check
    check (surcharge_refunded_cents >= 0 and surcharge_refunded_cents <= surcharge_cents),
  constraint invoice_payments_surcharge_disputed_cents_check
    check (surcharge_disputed_cents >= 0 and surcharge_disputed_cents <= surcharge_refunded_cents)
);
create index if not exists invoice_payments_invoice_idx on invoice_payments (invoice_id, sort_order);
create index if not exists invoice_payments_firm_invoice_idx on invoice_payments (law_firm_id, invoice_id);
create index if not exists invoice_payments_trust_txn_idx on invoice_payments (law_firm_id, trust_transaction_id);
-- The calendar's window probe compares payment_date against a date range. It was an
-- expression index on left(payment_date, 10) while the column was text (migration
-- 0125); migration 0196 made the column a date, so it indexes the column directly.
create index if not exists invoice_payments_paid_day_idx on invoice_payments (payment_date);

-- paymentPlan.expectedPayments[] -- installment schedule. installment_id is the
-- string `inst_<hex>` id; matched_payment_index is the integer index into payments[].
create table if not exists invoice_expected_payments (
  id                       uuid primary key default gen_random_uuid(),
  invoice_id               uuid not null references invoices(id) on delete cascade,
  law_firm_id              uuid not null references law_firms(id) on delete cascade,
  -- The formulation that makes a child pointing at an invoice in another firm
  -- impossible rather than merely unusual (migration 0246).
  foreign key (law_firm_id, invoice_id) references invoices (law_firm_id, id) on delete cascade,
  sort_order               int not null default 0,
  installment_id           text,
  due_date                 date,
  amount_cents             bigint not null default 0,
  -- 'overdue' is derived at read time and never written back, so it is absent.
  status                   text not null default 'pending'
    check (status in ('pending', 'paid', 'unpaid')),
  matched_payment_index    int,
  is_down_payment          boolean not null default false,
  pre_due_reminder_sent_at timestamptz,
  stripe_invoice_id        text,
  -- Account stripe_invoice_id was created on: 'platform' or an acct_ id. Null =
  -- unknown (row predates the column); teardown then uses the firm's current
  -- charge setup.
  stripe_invoice_account_id text,
  stripe_payment_status    text
    check (stripe_payment_status is null or stripe_payment_status in ('completed', 'pending', 'voided', 'failed'))
);
create index if not exists invoice_expected_invoice_idx on invoice_expected_payments (invoice_id, sort_order);
create index if not exists invoice_expected_firm_invoice_idx on invoice_expected_payments (law_firm_id, invoice_id);
-- Same story as invoice_payments_paid_day_idx: an expression index on
-- left(due_date, 10) until migration 0196 made the column a date.
create index if not exists invoice_expected_due_day_idx on invoice_expected_payments (due_date);

-- The credits and charges applied to an invoice after its lines were set:
-- `creditNotes[]` are the `credit` rows, `amountAdjustmentNotes[]` the `charge`
-- rows (migration 0230 merged the two tables that held them). Rewritten
-- whole on every invoice save, like the other children.
create table if not exists invoice_adjustments (
  id            uuid primary key default gen_random_uuid(),
  law_firm_id   uuid not null references law_firms(id) on delete cascade,
  invoice_id    uuid not null,
  direction     text not null check (direction in ('credit', 'charge')),
  kind          text check (kind is null or kind in ('write_off', 'discount', 'adjustment', 'late_fee')),
  external_id   text,
  amount_cents  bigint not null,
  description   text,
  sort_order    int not null default 0,
  created_by    text references users(id) on delete restrict,
  created_at    timestamptz not null default now(),
  constraint invoice_adjustments_kind_matches_direction check (
    (direction = 'credit' and (kind is null or kind in ('write_off', 'discount', 'adjustment')))
    or (direction = 'charge' and (kind is null or kind = 'late_fee'))
  ),
  foreign key (law_firm_id, invoice_id) references invoices (law_firm_id, id) on delete cascade
);
create index if not exists invoice_adjustments_invoice_idx
  on invoice_adjustments (law_firm_id, invoice_id, direction, sort_order);


create table if not exists billing_plans (
  id                  uuid not null default gen_random_uuid(),
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  matter_id             uuid,
  client_id           uuid references clients(id) on delete restrict,
  plan_type           text not null default 'retainer' check (plan_type in ('retainer')),
  name                text not null,
  status              text not null default 'active' check (status in ('active','paused','ended')),
  interval_unit       text check (interval_unit in ('week','month')),
  interval_count      int check (interval_count is null or interval_count > 0),
  start_date          date,
  next_run_date       date,
  end_condition       text default 'manual' check (end_condition in ('manual','matter_closed','date')),
  end_date            date,
  amount_cents        bigint check (amount_cents is null or amount_cents >= 0),
  included_hours      numeric check (included_hours is null or included_hours >= 0),
  billing_email       citext,
  default_due_days    int,
  default_client_id   uuid references clients(id) on delete set null,
  notes               text,
  created_by          text references users(id) on delete restrict,
  updated_by          text references users(id) on delete restrict,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  foreign key (law_firm_id, matter_id) references matters (law_firm_id, id) on delete cascade,
  check ( (matter_id is not null) <> (client_id is not null) )
);
-- Serves the on-delete walk of billing_plans_client_id_fkey (migration 0225).
create index if not exists billing_plans_client_id_idx on billing_plans (client_id);
-- Serves the on-delete walk of billing_plans_default_client_id_fkey (migration 0225).
create index if not exists billing_plans_default_client_id_idx on billing_plans (default_client_id);

create table if not exists billing_plan_periods (
  id                  uuid primary key default gen_random_uuid(),
  billing_plan_id     uuid not null references billing_plans(id) on delete cascade,
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  period_start_date   date,
  period_end_date     date,
  due_date            date,
  status              text not null default 'ready_to_bill'
                        check (status in ('ready_to_bill','draft_created','skipped')),
  amount_cents        bigint check (amount_cents is null or amount_cents >= 0),
  included_hours      numeric,
  consumed_hours      numeric,
  overage_hours       numeric,
  generated_invoice_id uuid,
  generated_at        timestamptz,
  generated_invoice_context_type text
    check (generated_invoice_context_type is null or generated_invoice_context_type in ('matter', 'client')),
  generated_invoice_entity_id    uuid,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (billing_plan_id, period_start_date)
);

-- =====================================================================
-- ACTIVITIES: the firm's billable and non-billable work, one table
-- =====================================================================
-- Time entries, expenses and flat fees are rows of one table told apart by
-- `kind` (migration 0232). The three route files each filter on their kind,
-- so the API did not change. Ids were preserved across the merge, which is
-- what keeps `invoice_line_items.source_id` valid.
--
-- `amount_cents` is generated: hours times the EXPLICIT rate for time (zero
-- when the rate is resolved at read time, so never sum it for revenue), and
-- the entered `charge_cents` for an expense or fee. A CHECK per kind pins
-- which columns that kind may set. A retainer period's coverage is
-- `billing_plan_period_id` + `coverage` on the row; an activity belongs to at
-- most one period. `source_event_id`'s key to `events` is attached in the
-- deferred block further down, because `events` is created later.
--
-- An activity that is on an invoice is frozen where it counts and cannot be
-- deleted: `activities_billed_immutable` below mirrors the services'
-- FROZEN_ONCE_BILLED lists column for column. Billed means a line item of the
-- matching kind names the row, on any non-voided invoice of the firm; voiding an
-- invoice releases what it held.
create table if not exists activities (
  id                     uuid primary key default gen_random_uuid(),
  law_firm_id            uuid not null references law_firms(id) on delete cascade,
  kind                   text not null check (kind in ('time', 'expense', 'flat_fee')),
  -- Exactly one billing context.
  matter_id              uuid,
  client_id              uuid references clients(id) on delete restrict,
  -- The timekeeper for time, the member who incurred an expense.
  user_id                text references users(id) on delete restrict,
  -- The day the work happened or the cost was incurred. Required for time; an
  -- expense or fee may be recorded without one.
  activity_date          date,
  description            text,
  name                   text,
  billable               boolean not null default true,
  -- Time only.
  hours                  numeric(6,2) check (hours is null or hours >= 0),
  -- The explicit override the member typed, if any.
  rate_cents             bigint check (rate_cents is null or rate_cents >= 0),
  -- The rate the entry was resolved at when written (migration 0233), and which
  -- of the eight sources supplied it. Written again only when the entry's
  -- inputs change or the firm asks to re-rate, so a rate change stops moving
  -- old work. Both null on a row nothing has resolved yet, which readers treat
  -- as "resolve live"; `'none'` with no cents is a resolution that found no
  -- rate at all.
  resolved_rate_cents    bigint check (resolved_rate_cents is null or resolved_rate_cents >= 0),
  rate_source            text check (rate_source is null or rate_source in (
    'time entry override', 'matter member rate', 'client member rate', 'client default rate',
    'charge code member rate', 'charge code default', 'user default rate', 'firm default rate', 'none')),
  -- Expense and flat fee only: the amount as entered.
  charge_cents           bigint check (charge_cents is null or charge_cents >= 0),
  -- What the row is worth. Generated so it cannot disagree with its inputs: hours
  -- times the resolved rate for time, so it CAN be summed for unbilled value; the
  -- entered amount for an expense or fee.
  amount_cents           bigint generated always as (
    case when kind = 'time' then round(coalesce(hours, 0) * coalesce(resolved_rate_cents, rate_cents, 0))::bigint
         else coalesce(charge_cents, 0) end
  ) stored,
  -- The charge code (time) or expense category (expense).
  billing_code_id        uuid,
  -- Time only: which clients on the matter the work was for, validated against
  -- matter_clients on write; the UTBMS codes; where the time came from.
  matter_client_ids      jsonb,
  utbms_task_code        text,
  utbms_activity_code    text,
  source                 text,
  source_task_id         uuid references tasks (id) on delete set null,
  source_event_id        uuid,
  linked_note_id         uuid,
  -- Expense only.
  vendor                 text,
  category               text,
  receipt_object_path    text,
  -- The retainer period this activity was counted against, if any, and
  -- whether it fell inside the allowance or over it. Both set or both null.
  billing_plan_period_id uuid references billing_plan_periods(id) on delete set null,
  coverage               text check (coverage is null or coverage in ('covered', 'overage')),
  created_by             text references users(id) on delete restrict,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  unique (law_firm_id, id),
  foreign key (law_firm_id, matter_id) references matters (law_firm_id, id) on delete cascade,
  -- Composite so a row can only name its own firm's code; deleting the code
  -- clears billing_code_id and nothing else.
  foreign key (law_firm_id, billing_code_id) references billing_codes (law_firm_id, id) on delete set null (billing_code_id),
  check ( (matter_id is not null) <> (client_id is not null) ),
  check ( source_task_id is null or source_event_id is null ),
  check ( (billing_plan_period_id is null) = (coverage is null) ),
  constraint activities_rate_only_on_time check (
    kind = 'time' or (resolved_rate_cents is null and rate_source is null)
  ),
  constraint activities_time_shape check (
    kind <> 'time' or (activity_date is not null and charge_cents is null and vendor is null and category is null and receipt_object_path is null)
  ),
  constraint activities_expense_shape check (
    kind <> 'expense' or (hours is null and rate_cents is null and matter_client_ids is null and utbms_task_code is null
      and utbms_activity_code is null and source is null and source_task_id is null and source_event_id is null
      and linked_note_id is null and billing_plan_period_id is null)
  ),
  constraint activities_flat_fee_shape check (
    kind <> 'flat_fee' or (hours is null and rate_cents is null and matter_client_ids is null and utbms_task_code is null
      and utbms_activity_code is null and source is null and source_task_id is null and source_event_id is null
      and linked_note_id is null and billing_plan_period_id is null and billing_code_id is null and vendor is null
      and category is null and receipt_object_path is null and user_id is null)
  )
);
-- Reads: a context's work of one kind, a member's time on a matter, a firm's
-- work by day, and the retainer period's coverage.
create index if not exists activities_firm_kind_matter_idx on activities (law_firm_id, kind, matter_id, user_id);
create index if not exists activities_firm_kind_client_idx on activities (law_firm_id, kind, client_id);
create index if not exists activities_firm_kind_date_idx on activities (law_firm_id, kind, activity_date);
create index if not exists activities_firm_matter_hours_idx on activities (law_firm_id, matter_id) include (hours) where kind = 'time';
create index if not exists activities_period_idx on activities (law_firm_id, billing_plan_period_id) where billing_plan_period_id is not null;
create index if not exists activities_linked_note_idx on activities (law_firm_id, linked_note_id) where linked_note_id is not null;
-- Foreign-key probes: a parent delete supplies only its own column.
create index if not exists activities_client_fk_idx on activities (client_id) where client_id is not null;
create index if not exists activities_user_fk_idx on activities (user_id) where user_id is not null;
create index if not exists activities_firm_billing_code_fk_idx on activities (law_firm_id, billing_code_id) where billing_code_id is not null;
create index if not exists activities_source_task_fk_idx on activities (source_task_id) where source_task_id is not null;
create index if not exists activities_source_event_fk_idx on activities (source_event_id) where source_event_id is not null;
create index if not exists activities_period_fk_idx on activities (billing_plan_period_id) where billing_plan_period_id is not null;

create or replace function activity_billed_immutable() returns trigger
  language plpgsql as $$
declare
  line_kind text := case old.kind when 'time' then 'time_entry' else old.kind end;
  placed boolean;
begin
  -- A voided invoice was cancelled by the firm, so its line items no longer
  -- hold the work they name.
  select exists (
    select 1 from invoice_line_items li
      join invoices i on i.law_firm_id = li.law_firm_id and i.id = li.invoice_id
     where li.law_firm_id = old.law_firm_id
       and li.kind = line_kind
       and li.source_id = old.id::text
       and i.status <> 'voided'
  ) into placed;
  if not placed then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    raise exception 'this % is on an invoice and cannot be deleted (id=%)', line_kind, old.id
      using errcode = 'restrict_violation';
  end if;

  if old.kind = 'time' then
    if new.hours is distinct from old.hours
       or new.rate_cents is distinct from old.rate_cents
       or new.resolved_rate_cents is distinct from old.resolved_rate_cents
       or new.activity_date is distinct from old.activity_date
       or new.billing_code_id is distinct from old.billing_code_id
       or new.matter_client_ids is distinct from old.matter_client_ids
       or new.billable is distinct from old.billable
       or new.matter_id is distinct from old.matter_id then
      raise exception 'this time entry is on an invoice: its hours, rate, date, charge code, client split, billable flag and matter are frozen (id=%)', old.id
        using errcode = 'restrict_violation';
    end if;
  elsif old.kind = 'flat_fee' then
    if new.charge_cents is distinct from old.charge_cents
       or new.activity_date is distinct from old.activity_date then
      raise exception 'this flat fee is on an invoice: its amount and date are frozen (id=%)', old.id
        using errcode = 'restrict_violation';
    end if;
  else
    if new.charge_cents is distinct from old.charge_cents
       or new.activity_date is distinct from old.activity_date
       or new.billable is distinct from old.billable then
      raise exception 'this expense is on an invoice: its amount, date and billable flag are frozen (id=%)', old.id
        using errcode = 'restrict_violation';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists activities_billed_immutable on activities;
create trigger activities_billed_immutable before update or delete on activities
  for each row execute function activity_billed_immutable();

-- Column comments. These were written by earlier migrations and never carried
-- into the domain files, so a database built from schema.sql lacked them while
-- a migrated one had them. They are the reference for what each column means.
comment on column invoices.billing_client_address is 'Billing address, frozen at first external issue. Plain text, mirroring clients.address.';
comment on column invoices.billing_client_name is 'Client display/legal name, frozen at first external issue. Distinct from billing_contact_name (the attention contact). Empty until snapshotted.';
comment on column invoices.billing_contact_email is 'Primary billing email, frozen at first external issue.';
comment on column invoices.billing_contact_name is 'Attention contact name, frozen at first external issue.';
comment on column invoices.billing_contact_title is 'Attention contact title/role, frozen at first external issue.';
comment on column invoices.billing_emails is 'Complete billing email list, frozen at first external issue. Empty until snapshotted.';
comment on column invoices.billing_snapshot_at is 'When the billing recipient / bill-to snapshot was taken. Null = never snapshotted (draft, or predates this feature).';
comment on column invoices.stripe_invoice_account_id is 'Stripe account stripe_invoice_id was created on: ''platform'' or an acct_ id. Null = unknown (row predates the column); teardown then uses the firm''s current charge setup.';
comment on column invoices.stripe_card_payment_intent_id is 'PaymentIntent of a card-form payment not yet settled; cleared when it succeeds, fails or is cancelled.';
comment on column invoices.stripe_card_payment_intent_account_id is 'Stripe account stripe_card_payment_intent_id was created on (an acct_ id).';
comment on column invoices.stripe_checkout_session_account_id is 'Stripe account stripe_checkout_session_id was created on: ''platform'' or an acct_ id. Null = unknown (row predates the column); teardown then uses the firm''s current charge setup.';
comment on column invoice_expected_payments.stripe_invoice_account_id is 'Stripe account stripe_invoice_id was created on: ''platform'' or an acct_ id. Null = unknown (row predates the column); teardown then uses the firm''s current charge setup.';
comment on column invoice_payments.stripe_disputed_cents is 'The part of stripe_refunded_cents that a dispute took (cumulative reversal minus refunds). A won dispute restores at most this much.';

-- >>> 80_trust.sql <<<
-- =====================================================================
-- TRUST (append-only ledger)
-- =====================================================================

create table if not exists trust_accounts (
  id                   uuid not null default gen_random_uuid(),
  law_firm_id          uuid not null references law_firms(id) on delete cascade,
  name                 text not null,
  bank_name            text,
  account_number_last4 text check (account_number_last4 is null or account_number_last4 ~ '^[0-9]{4}$'),
  routing_number_last4 text,
  -- 'iolta' = pooled interest-to-bar-foundation account; 'trust' = non-IOLTA
  -- retainer/escrow account; 'separate_interest' = client-specific
  -- interest-bearing account (interest to the client).
  account_type         text not null default 'iolta'
    check (account_type in ('iolta','trust','separate_interest')),
  iolta_tin            text,
  interest_beneficiary text
    check (interest_beneficiary is null or interest_beneficiary in ('bar_foundation','client','firm')),
  -- Period lock: transactions dated on/before this are in a closed period and
  -- cannot be posted or voided (enforced in the application layer).
  book_close_date      date,
  status               text not null default 'active' check (status in ('active','inactive')),
  book_balance_cents   bigint not null default 0
    constraint trust_accounts_book_balance_nonneg check (book_balance_cents >= 0),
  -- Stripe connected account dedicated to this trust/IOLTA bank account. Electronic
  -- (ACH) trust deposits are destination charges routed here so client funds settle
  -- into the trust bank account, never the firm's operating account. Separate from
  -- law_firms.stripe_account_id (the operating account).
  stripe_connected_account_id text,
  stripe_charges_enabled      boolean not null default false,
  stripe_onboarding_complete  boolean not null default false,
  created_by           text references users(id) on delete restrict,
  updated_by           text references users(id) on delete restrict,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id)
);
create unique index if not exists trust_accounts_stripe_acct_uidx
  on trust_accounts (stripe_connected_account_id)
  where stripe_connected_account_id is not null;

-- Processing fees for electronic (ACH) trust deposits. The deposit posts to trust
-- in full; the fee Paralegix fronts is billed back to the firm's operating side via
-- an invoice item on their subscription customer. One row per deposit (idempotent).
create table if not exists trust_deposit_fees (
  id                     uuid not null default gen_random_uuid(),
  law_firm_id            uuid not null references law_firms(id) on delete cascade,
  trust_transaction_id   uuid not null,
  fee_cents              bigint not null check (fee_cents >= 0),
  stripe_invoice_item_id text,
  -- The one-off fee invoice, persisted at finalize time (before pay) so a retry
  -- reuses it instead of creating a second charge once the Stripe idempotency key
  -- (24h TTL) has expired.
  stripe_invoice_id      text,
  status                 text not null default 'accrued'
                           check (status in ('accrued','billed','waived')),
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, trust_transaction_id)
);

-- Cash automatic Stripe recovery took back for a clawed-back payment (a trust
-- deposit or an invoice payment), one row per Stripe object that moved it, and
-- how much of it has been given back. A won dispute or a failed refund returns
-- exactly this, to where it came from, whatever the ledger or the invoice did
-- (migration 0046).
create table if not exists stripe_fund_recoveries (
  id                        uuid not null default gen_random_uuid(),
  law_firm_id               uuid not null references law_firms(id) on delete cascade,
  stripe_payment_intent_id  text not null,
  -- trust_transfer / firm_transfer: reversed out of that connected account;
  -- firm_card: charged to the firm's operating card on file.
  source                    text not null
                              check (source in ('trust_transfer', 'firm_transfer', 'firm_card')),
  -- The transfer reversal, or the recovery payment intent a refund is made against.
  stripe_object_id          text not null,
  recovered_cents           bigint not null check (recovered_cents > 0),
  restored_cents            bigint not null default 0,
  created_at                timestamptz not null default now(),
  updated_at                timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  unique (stripe_object_id),
  constraint stripe_fund_recoveries_restored_cents_check
    check (restored_cents >= 0 and restored_cents <= recovered_cents)
);
create index if not exists stripe_fund_recoveries_payment_idx
  on stripe_fund_recoveries (law_firm_id, stripe_payment_intent_id);

create table if not exists trust_transactions (
  id                          uuid primary key default gen_random_uuid(),
  law_firm_id                 uuid not null references law_firms(id) on delete cascade,
  trust_account_id            uuid not null,
  type                        text not null check (type in ('deposit','withdrawal','transfer','refund')),
  amount_cents                bigint not null check (amount_cents > 0),
  client_id                   uuid references clients(id) on delete restrict,
  matter_id                     uuid,
  txn_date                    date not null,
  description                 text,
  reference_number            text,
  payee                       text,
  transfer_to                 text check (transfer_to in ('operating','other')),
  -- Double-entry trust→trust transfer: when a transfer targets another trust
  -- account, two linked legs are posted (withdrawal from source, deposit into
  -- destination) sharing one transfer_group_id. transfer_to_account_id is the
  -- destination account on the source (withdrawal) leg.
  transfer_to_account_id      uuid,
  transfer_group_id           uuid,
  source                      text check (source in ('check','wire','ach','cash','credit_card','interest','stripe','other')),
  invoice_id                  uuid,
  -- Stripe-funded deposit linkage (electronic trust payments). The partial
  -- unique index below makes a replayed webhook idempotent.
  stripe_session_id           text,
  stripe_payment_intent_id    text,
  -- Connect charge model for a Stripe-funded deposit (docs/DIRECT_CHARGE_MIGRATION.md).
  -- 'destination' (default) = destination charge on the platform; 'direct' = direct
  -- charge on the trust connected account. Clawback handling branches on this.
  -- Only ever written as 'destination' today: Phase 0 of that migration lands the
  -- column ahead of the behaviour, so an unused value here is expected.
  charge_model                text not null default 'destination' check (charge_model in ('destination','direct')),
  -- restrict, not cascade: a reversing entry must never outlive the entry it
  -- reverses, because the pair is the void lineage the ledger rests on.
  reverses_transaction_id     uuid references trust_transactions(id) on delete restrict,
  status                      text not null default 'completed' check (status in ('completed','pending','void')),
  client_balance_after_cents  bigint,
  account_balance_after_cents bigint,
  -- Bank-reconciliation tracking: a completed entry is `cleared` once a
  -- reconciliation that did not flag it as outstanding is recorded. "Currently
  -- outstanding" = completed rows with cleared_at IS NULL. (No FK on
  -- cleared_in_reconciliation_id: reconciliations are append-only and never
  -- deleted, so it is a soft audit link.)
  cleared_at                  timestamptz,
  cleared_in_reconciliation_id uuid,
  voided_by                   text references users(id) on delete restrict,
  voided_at                   timestamptz,
  void_reason                 text,
  created_by                  text references users(id) on delete restrict,
  created_at                  timestamptz not null default now(),
  updated_at                  timestamptz not null default now(),
  -- restrict: an account with ledger entries against it cannot be deleted.
  foreign key (law_firm_id, trust_account_id) references trust_accounts (law_firm_id, id) on delete restrict,
  foreign key (law_firm_id, transfer_to_account_id) references trust_accounts (law_firm_id, id) on delete restrict,
  foreign key (law_firm_id, matter_id)          references matters (law_firm_id, id) on delete set null,
  -- tenant-scoped FK on the billing→trust link (migration 0064). SET NULL only
  -- nulls invoice_id (not law_firm_id) on invoice delete -- column-list form, PG 15+.
  constraint trust_txn_invoice_fk
    foreign key (law_firm_id, invoice_id)     references invoices (law_firm_id, id) on delete set null (invoice_id)
);
-- Serves the on-delete walk of trust_transactions_client_id_fkey (migration 0225).
create index if not exists trust_transactions_client_id_idx on trust_transactions (client_id);
-- Firm-leading: every read in trust.repository.ts filters law_firm_id together
-- with the account or client and orders by txn_date desc, so these seek on both
-- columns instead of seeking on one and filtering the other (migration 0206).
create index if not exists trust_txn_firm_account_date_idx
  on trust_transactions (law_firm_id, trust_account_id, txn_date desc);
create index if not exists trust_txn_firm_client_date_idx
  on trust_transactions (law_firm_id, client_id, txn_date desc);
-- trust_txn_firm_date_idx removed by migration 0195: covered by
-- trust_txn_firm_date_created_idx; the `status <> 'void'` predicate excludes almost nothing.
create index if not exists trust_txn_uncleared_idx on trust_transactions (law_firm_id, trust_account_id) where status = 'completed' and cleared_at is null;
-- FK probe support (see migration 0130): deleting a matter or an invoice.
create index if not exists trust_transactions_matter_idx
  on trust_transactions (law_firm_id, matter_id) where matter_id is not null;
create index if not exists trust_transactions_invoice_idx
  on trust_transactions (law_firm_id, invoice_id) where invoice_id is not null;
create index if not exists trust_txn_transfer_group_idx on trust_transactions (transfer_group_id) where transfer_group_id is not null;
create unique index if not exists trust_txn_stripe_session_uidx on trust_transactions (law_firm_id, stripe_session_id) where stripe_session_id is not null;
-- ACH deposits post on payment_intent.succeeded (no session id in that event), so
-- the payment intent id is the idempotency key. Void reversals carry no PI id.
create unique index if not exists trust_txn_stripe_pi_uidx on trust_transactions (law_firm_id, stripe_payment_intent_id) where stripe_payment_intent_id is not null and status <> 'void';

create table if not exists trust_reconciliations (
  id                            uuid primary key default gen_random_uuid(),
  law_firm_id                   uuid not null references law_firms(id) on delete cascade,
  trust_account_id              uuid not null,
  reconciliation_date           date not null,
  bank_statement_balance_cents  bigint not null,
  book_balance_cents            bigint not null,
  client_ledger_total_cents     bigint not null,
  is_reconciled                 boolean not null default false,
  discrepancy_cents             bigint not null,
  adjustments                   jsonb not null default '[]',
  outstanding_transaction_ids   uuid[],
  notes                         text,
  reconciled_by                 text references users(id) on delete restrict,
  reconciled_at                 timestamptz,
  created_by                    text references users(id) on delete restrict,
  created_at                    timestamptz not null default now(),
  updated_at                    timestamptz not null default now(),
  -- restrict: an account with a reconciliation against it cannot be deleted.
  foreign key (law_firm_id, trust_account_id) references trust_accounts (law_firm_id, id) on delete restrict
);

-- Evergreen retainer thresholds: the minimum balance a client should keep in an
-- account before a replenishment alert fires. Absent row = no minimum.
create table if not exists trust_minimum_balances (
  id               uuid primary key default gen_random_uuid(),
  law_firm_id      uuid not null references law_firms(id) on delete cascade,
  client_id        uuid not null references clients(id) on delete restrict,
  trust_account_id uuid not null,
  minimum_cents    bigint not null default 0 check (minimum_cents >= 0),
  created_by       text references users(id) on delete restrict,
  updated_by       text references users(id) on delete restrict,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (law_firm_id, client_id, trust_account_id),
  foreign key (law_firm_id, trust_account_id) references trust_accounts (law_firm_id, id) on delete cascade
);
-- Serves the on-delete walk of trust_minimum_balances_client_id_fkey (migration 0225).
create index if not exists trust_minimum_balances_client_id_idx on trust_minimum_balances (client_id);

-- IOLTA interest remittance tracking: interest earned on a pooled account and
-- the remittance of that interest to the state bar foundation / IOLTA program.
create table if not exists trust_interest_remittances (
  id                    uuid primary key default gen_random_uuid(),
  law_firm_id           uuid not null references law_firms(id) on delete cascade,
  trust_account_id      uuid not null,
  period_start          date,
  period_end            date,
  interest_earned_cents bigint not null default 0,
  amount_remitted_cents bigint not null default 0,
  remitted_to           text,
  remittance_date       date,
  reference_number      text,
  notes                 text,
  status                text not null default 'pending' check (status in ('pending','remitted')),
  created_by            text references users(id) on delete restrict,
  updated_by            text references users(id) on delete restrict,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  foreign key (law_firm_id, trust_account_id) references trust_accounts (law_firm_id, id) on delete cascade
);
create index if not exists trust_interest_remit_account_idx
  on trust_interest_remittances (law_firm_id, trust_account_id, period_end desc);

-- =====================================================================
-- TRUST LEDGER IMMUTABILITY (upgrade #3)
--   completed transactions cannot be UPDATEd or DELETEd; corrections are
--   posted as reversing entries.
-- =====================================================================
create or replace function trust_txn_immutable() returns trigger as $$
declare
  frozen trust_transactions%rowtype;
  declared_remap text;
begin
  if (tg_op = 'DELETE') then
    -- Both completed and void entries are permanent: the void lineage rows are the
    -- correction trail the ledger depends on, so deleting them would destroy
    -- tamper-evidence. Only a non-terminal row (should never exist today) may be deleted.
    if old.status in ('completed', 'void') then
      raise exception 'trust_transactions are append-only: % entries cannot be deleted (id=%)', old.status, old.id;
    end if;
    return old;
  end if;

  -- A void entry is terminal and fully immutable. In particular it can never be
  -- flipped back to completed, which would resurrect a reversed entry and silently
  -- inflate every SUM-derived balance without touching book_balance_cents.
  if old.status = 'void' then
    raise exception 'trust_transactions are append-only: void entries are immutable (id=%)', old.id;
  end if;

  -- A completed entry may only stay completed or transition to void; no other target
  -- status (e.g. pending) is allowed.
  if old.status = 'completed' and new.status not in ('completed', 'void') then
    raise exception 'trust_transactions are append-only: completed entries may only be voided (id=%)', old.id;
  end if;

  -- A completed entry that remains completed is frozen in place: the only fields
  -- that may change are the bank-clearing stamps (cleared_at,
  -- cleared_in_reconciliation_id) and updated_at. Normalize those, then require
  -- the rest of the row to be byte-for-byte identical, so attribution
  -- (client/matter/date), amount, and every other field stay tamper-evident.
  -- Corrections must be reversing entries, not in-place edits.
  if old.status = 'completed' and new.status = 'completed' then
    frozen := new;
    frozen.cleared_at := old.cleared_at;
    frozen.cleared_in_reconciliation_id := old.cleared_in_reconciliation_id;
    frozen.updated_at := old.updated_at;

    -- The single declared exception (migration 0183): a client-identity merge
    -- folding a duplicate client row into the record that survives it. The two
    -- rows are the same person by construction (same email, one never claimed),
    -- so the money did not move between people, only the record it hangs off
    -- did. `mergePlaceholder` must repoint client_id before deleting the
    -- duplicate, because the FK to clients(id) has no delete action.
    --
    -- The caller names the exact pair it intends to remap, transaction-locally:
    --   select set_config('paralegix.trust_client_remap', '<from>:<to>', true);
    -- Anything else -- a different pair, no setting, or any other altered column
    -- -- still raises, and normalizing client_id here keeps every OTHER column
    -- inside the byte-for-byte comparison below.
    declared_remap := current_setting('paralegix.trust_client_remap', true);
    if declared_remap is not null
       and new.client_id is distinct from old.client_id
       and declared_remap = old.client_id::text || ':' || new.client_id::text then
      frozen.client_id := old.client_id;
    end if;

    if frozen is distinct from old then
      raise exception 'trust_transactions are append-only: post a reversing entry instead of editing (id=%)', old.id;
    end if;
  end if;

  -- The completed -> void transition may ONLY set the void bookkeeping fields; every
  -- other column (amount, client, matter, date, ...) must stay identical, so a void
  -- cannot smuggle in an edit alongside the status change.
  if old.status = 'completed' and new.status = 'void' then
    frozen := new;
    frozen.status := old.status;
    frozen.voided_by := old.voided_by;
    frozen.voided_at := old.voided_at;
    frozen.void_reason := old.void_reason;
    frozen.cleared_at := old.cleared_at;
    frozen.cleared_in_reconciliation_id := old.cleared_in_reconciliation_id;
    frozen.updated_at := old.updated_at;
    if frozen is distinct from old then
      raise exception 'trust_transactions are append-only: a void may only set the void fields (id=%)', old.id;
    end if;
  end if;

  return new;
end;
$$ language plpgsql;

drop trigger if exists trust_txn_immutable on trust_transactions;
create trigger trust_txn_immutable before update or delete on trust_transactions
  for each row execute function trust_txn_immutable();

