-- =====================================================================
-- TEMPLATES
-- =====================================================================

create table if not exists template_folders (
  id                  uuid primary key default gen_random_uuid(),
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  name                text not null,
  color               text,
  parent_folder_id    uuid references template_folders(id) on delete set null,
  sort_order          int,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
-- non-unique sibling-name index. Promote to UNIQUE once duplicate sibling
-- folder names are de-duplicated in existing data.
create index if not exists template_folders_sibling_name_idx on template_folders (law_firm_id, parent_folder_id, lower(name));

create table if not exists templates (
  id                        uuid primary key default gen_random_uuid(),
  law_firm_id               uuid not null references law_firms(id) on delete cascade,
  name                      text not null,
  type                      text not null default 'html' check (type in ('html','docx','overlay')),
  fields                    text[] not null default '{}',
  repeaters                 jsonb not null default '[]',
  folder_id                 uuid references template_folders(id) on delete set null,
  html_object_path          text,
  docx_object_path          text,
  -- overlay type: overlay_pdf_object_path is the rendered editor canvas (equal to the
  -- upload if it was already a PDF, otherwise a one-time LibreOffice-converted copy);
  -- overlay_source_object_path is the original upload, kept for reference/re-conversion.
  overlay_pdf_object_path   text,
  overlay_source_object_path text,
  assets                    jsonb not null default '[]',   -- inline asset array (service-managed)
  created_at                timestamptz not null default now(),
  updated_at                timestamptz not null default now()
);
create index if not exists templates_firm_folder_idx on templates (law_firm_id, folder_id);

-- The Word-first template library (migration 0048). Separate from `templates`:
-- an uploaded .docx or fillable PDF is stored byte for byte and filled in
-- place, and an html template keeps its body in storage. A row points at its
-- body or its source file, never both.
create table if not exists word_templates (
  id                   uuid not null default gen_random_uuid(),
  law_firm_id          uuid not null references law_firms(id) on delete cascade,
  name                 text not null check (length(btrim(name)) between 1 and 200),
  type                 text not null check (type in ('html', 'docx', 'pdf-form')),
  -- Storage object holding an html template's body.
  html_object_path     text,
  -- Storage object holding a docx or pdf-form template's original file.
  source_object_path   text,
  original_file_name   text check (original_file_name is null or length(original_file_name) <= 255),
  fields               text[] not null default '{}',
  repeaters            jsonb not null default '[]',
  -- Images embedded in an html template: [{ id, object_path, mime_type, file_name }].
  assets               jsonb not null default '[]',
  created_by           text references users(id) on delete restrict,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  constraint word_templates_body_present check (
    (type = 'html' and html_object_path is not null and source_object_path is null)
    or (type in ('docx', 'pdf-form') and source_object_path is not null and html_object_path is null)
  )
);
-- The library lists one firm's templates by name.
create index if not exists word_templates_firm_name_idx
  on word_templates (law_firm_id, name);
-- Same-name detection on upload, and the guarantee behind it: two concurrent
-- uploads of one name cannot both create a row.
create unique index if not exists word_templates_firm_type_name_key
  on word_templates (law_firm_id, type, lower(name))
  where type in ('docx', 'pdf-form');
create index if not exists word_templates_created_by_idx
  on word_templates (created_by);
comment on table word_templates is 'Word-first template library: an uploaded .docx or fillable PDF filled in place, or an HTML template whose body lives in storage.';
comment on column word_templates.source_object_path is 'Storage object of the original .docx or .pdf. Replaced by writing a new versioned object, repointing this column, then deleting the old one.';

-- Page-relative overlay boxes for overlay-type templates, one row per field (or per
-- repeater column on its authored row). Position is percent-of-page, mirroring
-- signature_fields. templates.fields/templates.repeaters remain the source of truth for
-- "what fields exist"; this table is "where they sit on the page".
create table if not exists template_field_placements (
  id                 uuid primary key default gen_random_uuid(),
  law_firm_id        uuid not null references law_firms(id) on delete cascade,
  template_id        uuid not null references templates(id) on delete cascade,
  field_name         text not null,
  field_type         text not null default 'text'
    check (field_type in ('text', 'date', 'checkbox', 'textbox', 'image')),
  page               int not null,
  x_percent          numeric not null,
  y_percent          numeric not null,
  width_percent      numeric not null,
  height_percent     numeric not null,
  repeater_name      text,
  repeater_row_index int,
  sort_order         int not null default 0,
  -- Literal text for a textbox placement, stamped as-is on every filled
  -- document. Null for other field types.
  text_content       text,
  -- GCS object path + MIME type of an uploaded image placement. Null for
  -- other field types.
  image_object_path  text,
  image_mime_type    text,
  -- Text styling (text/date/textbox placements; checkbox/image ignore it).
  -- font_size null keeps the historical auto-fit-to-box behavior. helvetica/
  -- times/courier are pdf-lib's built-in fonts; calibri/cambria/pt-serif/
  -- pt-sans are real TTFs fontkit-embedded by the stamping path (see
  -- backend/src/modules/templates/fonts).
  font_size          numeric,
  font_family        text not null default 'times'
    check (font_family in ('helvetica', 'times', 'courier', 'calibri', 'cambria', 'pt-serif', 'pt-sans')),
  bold               boolean not null default false,
  italic             boolean not null default false,
  color              text not null default '#000000',
  text_align         text not null default 'left'
    check (text_align in ('left', 'center', 'right')),
  -- Each non-blank line gets a bullet prefix before layout (text/date/textbox
  -- only; a plain boolean since the content is a single string, not markup).
  bullet_list        boolean not null default false,
  -- Mixed-formatting rich text for a 'textbox' placement: an array of
  -- paragraph blocks, each an array of styled runs (bold/italic/color per
  -- run, plus an optional fieldName making the run a merge-field chip
  -- resolved at fill time). Null keeps the placement on the flat
  -- text_content/bullet_list rendering path above unchanged; text_content/
  -- bullet_list are kept as a plain-text mirror of rich_text when it's set.
  rich_text          jsonb,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index if not exists template_field_placements_template_id_idx
  on template_field_placements (template_id);

-- =====================================================================
-- FILES (metadata; bytes in GCS)
-- =====================================================================

-- One row per file or folder. The tree is `parent_id`; the object under
-- `lawfirmids/{law_firm_id}/objects/{id}` is written once and never moves, so a
-- rename or a move is an update here rather than a copy of every byte beneath a
-- prefix. Every scope (a matter, a task, a client, the firm's general area) owns
-- exactly one root folder, which is what lets one index and one query serve the
-- root and every subfolder alike.
create table if not exists files (
  id                  uuid primary key default gen_random_uuid(),
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  kind                text not null default 'file' check (kind in ('file', 'folder')),
  name                text not null,
  -- Null only on a scope root. Everything else hangs off one.
  parent_id           uuid,
  -- Which tree this row belongs to. A root names its scope through the id
  -- columns below; every descendant carries the same values so a listing can
  -- filter without walking to the root.
  scope               text not null check (scope in ('matter', 'task', 'client', 'firm')),
  matter_id           uuid,
  -- A matter-linked task's document carries BOTH ids: it belongs to the task,
  -- and the matter listing excludes it on that basis.
  task_id             uuid,
  client_id           uuid,
  -- The storage key, assigned at insert and never changed. A folder has none.
  object_path         text,
  mime_type           text,
  size_bytes          bigint check (size_bytes is null or size_bytes >= 0),
  -- An upload is a row before it is bytes: the row is inserted to claim the
  -- name, then the browser writes the object, then this is stamped. A row that
  -- never gets here is an abandoned upload and the sweeper collects it with its
  -- object. Only finalized rows count toward a firm's usage or appear in a list.
  finalized_at        timestamptz,
  uploaded_by         text references users(id) on delete restrict,
  -- The signing session that filed this document, when one did. It makes filing
  -- retry-safe: the terminal 'completed' write can fail after the bytes land,
  -- and the recovery pass has to re-use the same row rather than file a second
  -- copy of the same executed document beside the first.
  signed_via_session  text,
  -- Shared into the client portal. A folder shares everything beneath it; see
  -- `file_client_visibility` for the per-client narrowing.
  client_visible      boolean not null default false,
  folder_color        text,
  -- Soft delete. The row and its object survive a retention window so a delete
  -- is recoverable and a legal hold still has something to hold; the sweeper
  -- destroys both afterwards.
  deleted_at          timestamptz,
  deleted_by          text references users(id) on delete restrict,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (law_firm_id, id),
  foreign key (law_firm_id, parent_id) references files (law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, matter_id) references matters (law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, task_id) references tasks (law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, client_id) references clients (law_firm_id, id) on delete cascade,
  -- What a filesystem allows in one name, and what a download's
  -- Content-Disposition header can carry. The object path no longer grows with
  -- the name, so this is about the name being usable, not about storage: it is
  -- rendered in a listing, sent as a download filename, and written as a zip
  -- entry. A scope root is the exception: nothing renders it, so it has no name.
  constraint files_name_length check (
    char_length(name) <= 255 and (parent_id is null or char_length(name) >= 1)
  ),
  constraint files_folder_has_no_object check (kind = 'file' or object_path is null),
  constraint files_file_has_object check (kind = 'folder' or object_path is not null),
  -- A root has to name the scope it serves, or it is a tree nothing can find.
  constraint files_root_names_scope check (
    parent_id is not null or (
      (scope = 'matter' and matter_id is not null and task_id is null and client_id is null) or
      (scope = 'task' and task_id is not null and client_id is null) or
      (scope = 'client' and client_id is not null and matter_id is null and task_id is null) or
      (scope = 'firm' and matter_id is null and task_id is null and client_id is null)
    )
  )
);

-- A name is unique among its live siblings, case-insensitively: two documents
-- whose names differ only in case are the same document to a person, and cannot
-- both be saved by a case-insensitive client. Soft-deleted rows are excluded so
-- deleting a file and uploading a replacement under its name works.
create unique index if not exists files_sibling_name_uidx
  on files (law_firm_id, parent_id, lower(name)) where parent_id is not null and deleted_at is null;

-- One root per scope. `ensureScopeRoot` inserts on conflict against these, so
-- two concurrent first writes to a matter cannot build two trees for it.
create unique index if not exists files_matter_root_uidx
  on files (law_firm_id, matter_id) where parent_id is null and scope = 'matter';
create unique index if not exists files_task_root_uidx
  on files (law_firm_id, task_id) where parent_id is null and scope = 'task';
create unique index if not exists files_client_root_uidx
  on files (law_firm_id, client_id) where parent_id is null and scope = 'client';
create unique index if not exists files_firm_root_uidx
  on files (law_firm_id) where parent_id is null and scope = 'firm';

create index if not exists files_parent_idx on files (law_firm_id, parent_id) where deleted_at is null;
create index if not exists files_firm_matter_idx on files (law_firm_id, matter_id);
create index if not exists files_firm_client_idx on files (law_firm_id, client_id);
create index if not exists files_firm_task_idx on files (law_firm_id, task_id);
-- The sweeper's two work queues.
create index if not exists files_deleted_idx on files (deleted_at) where deleted_at is not null;
create index if not exists files_deleted_by_idx on files (deleted_by) where deleted_by is not null;
create unique index if not exists files_signed_via_session_uidx
  on files (law_firm_id, signed_via_session) where signed_via_session is not null;
create index if not exists files_unfinalized_idx
  on files (created_at) where kind = 'file' and finalized_at is null;
create unique index if not exists files_object_path_uidx on files (object_path) where object_path is not null;

-- Narrows a shared file or folder to named clients. `client_visible` with no
-- rows here means every client on the scope; with rows, only those clients.
-- Replaces the `visibleClientIds` key that used to live on the object metadata,
-- where no SQL read could enforce it.
create table if not exists file_client_visibility (
  law_firm_id uuid not null references law_firms(id) on delete cascade,
  file_id     uuid not null,
  client_id   uuid not null,
  -- No `updated_at`: `setVisibility` replaces the whole set for a file, so a row
  -- is created and destroyed but never updated.
  created_at  timestamptz not null default now(),
  primary key (law_firm_id, file_id, client_id),
  foreign key (law_firm_id, file_id) references files (law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, client_id) references clients (law_firm_id, id) on delete cascade
);
create index if not exists file_client_visibility_client_idx
  on file_client_visibility (law_firm_id, client_id);

-- Buffer of not-yet-notified document shares, one row per (client, object). A
-- trailing-edge debounce flushes all of a client's unsent rows into a single
-- digest, so a burst of shares becomes one email + one bell item instead of one
-- per file (see modules/files/shareNotifications.service.js). Migration 0108.

-- =====================================================================
-- FILE CLIENT ACCESS (unified access ledger from migration 0236)
-- =====================================================================

create table if not exists file_client_access (
  id                  uuid primary key default gen_random_uuid(),
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  file_id             uuid not null references files(id) on delete cascade,
  client_user_id      text not null references users(id) on delete cascade,
  is_folder           boolean not null default false,
  is_email_enabled    boolean not null default true,
  shared_by           text references users(id) on delete restrict,
  shared_at           timestamptz not null default now(),
  notified_at         timestamptz,
  first_seen_at       timestamptz,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (law_firm_id, id),
  foreign key (law_firm_id, file_id) references files(law_firm_id, id) on delete cascade
);

drop trigger if exists set_updated_at on file_client_access;
create trigger set_updated_at before update on file_client_access
  for each row execute function set_updated_at();

create unique index if not exists file_client_access_firm_user_file_uq on file_client_access (law_firm_id, client_user_id, file_id);
create index if not exists file_client_access_pending_idx on file_client_access (law_firm_id, client_user_id) where notified_at is null;
create index if not exists file_client_access_client_user_id_idx on file_client_access (client_user_id);
create index if not exists file_client_access_shared_by_idx on file_client_access (shared_by) where shared_by is not null;
create index if not exists file_client_access_firm_file_idx on file_client_access (law_firm_id, file_id) where file_id is not null;
create index if not exists file_client_access_file_id_idx on file_client_access (file_id) where file_id is not null;

-- =====================================================================
-- FILE EXPORT JOBS (durable folder archives)
-- =====================================================================

-- A folder download used to be an archive streamed out of the API: the request
-- opened a read stream per document and piped all of them into one response, so
-- one person downloading a large matter held an instance for as long as the
-- transfer took and nothing recorded what was owed if it died partway. A
-- truncated archive is also indistinguishable from a complete one to whoever
-- opens it on the other end.
--
-- A row here is the promise that an archive is owed. It survives the process, it
-- names exactly what to archive, and any instance can pick it up.
--
-- The lease is what makes that safe, and it is the part that is easy to leave
-- out. A worker claims the job by writing a token and an expiry, and every write
-- afterwards re-checks that token. A worker that stalls past its expiry loses
-- the job, and its later writes are refused rather than landing on top of its
-- replacement's. Without the token both workers publish, and the firm is charged
-- for two archives of the same folder while the row points at one of them.
create table if not exists file_export_jobs (
  id                uuid primary key default gen_random_uuid(),
  law_firm_id       uuid not null references law_firms(id) on delete cascade,
  -- The folder the archive is rooted at. Entry paths come out relative to it,
  -- so this is also what makes an archive's contents reproducible.
  root_file_id      uuid not null,
  -- Who asked. The finished archive is handed back to this user and nobody
  -- else: the job carried their access, not the firm's.
  requested_by      text not null references users(id) on delete cascade,
  -- Which selection this job covers, so two clicks on the same download return
  -- one job instead of archiving the folder twice. A whole-subtree export uses
  -- a fixed marker; a multi-select uses a digest of its source ids.
  selection_digest  text not null,
  status            text not null default 'queued'
                      check (status in ('queued', 'leased', 'succeeded', 'failed', 'cancelled')),
  attempt           int not null default 0,
  next_attempt_at   timestamptz not null default now(),
  lease_owner       text,
  lease_token       uuid,
  lease_expires_at  timestamptz,
  -- Where the finished archive landed and the exact version of it this job
  -- produced. The generation is pinned into every read URL minted from here, so
  -- a retry that rewrote the object cannot be served against a URL authorized
  -- for the previous attempt.
  object_path       text,
  object_generation text,
  entry_count       int,
  size_bytes        bigint check (size_bytes is null or size_bytes >= 0),
  -- The last phase whose output is durable, and what it produced. An
  -- interrupted job resumes from here instead of starting over.
  phase             text,
  phase_state       jsonb,
  failure_code      text,
  failure_detail    text,
  -- When the temporary archive object is swept and this row stops minting URLs.
  expires_at        timestamptz not null default now() + interval '24 hours',
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (law_firm_id, id),
  foreign key (law_firm_id, root_file_id)
    references files (law_firm_id, id) on delete cascade
);

drop trigger if exists set_updated_at on file_export_jobs;
create trigger set_updated_at before update on file_export_jobs
  for each row execute function set_updated_at();

-- One live job per person per selection. The conflict target for the enqueue,
-- so a second request returns the first job rather than a rival that would
-- archive the same folder again and charge the transfer twice.
create unique index if not exists file_export_jobs_live_idx
  on file_export_jobs (law_firm_id, requested_by, root_file_id, selection_digest)
  where status in ('queued', 'leased');

create index if not exists file_export_jobs_ready_idx
  on file_export_jobs (next_attempt_at) where status = 'queued';
create index if not exists file_export_jobs_lease_idx
  on file_export_jobs (lease_expires_at) where status = 'leased';
create index if not exists file_export_jobs_firm_idx
  on file_export_jobs (law_firm_id, requested_by, created_at desc);
-- The TTL sweep's work queue: archives that still have an object to remove.
create index if not exists file_export_jobs_expiry_idx
  on file_export_jobs (expires_at) where object_path is not null;
create index if not exists file_export_jobs_root_idx
  on file_export_jobs (law_firm_id, root_file_id);
create index if not exists file_export_jobs_requested_by_idx
  on file_export_jobs (requested_by);

-- What a multi-select export was asked for, one row per selected file or
-- folder. No rows means the whole subtree under `root_file_id`.
--
-- A table rather than a uuid array on the job: an array cannot carry a foreign
-- key, so a selected document deleted before the worker reaches it would leave
-- an id pointing at nothing and the archive would decide what to do about it at
-- read time.
create table if not exists file_export_job_sources (
  law_firm_id uuid not null references law_firms(id) on delete cascade,
  job_id      uuid not null,
  file_id     uuid not null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  primary key (law_firm_id, job_id, file_id),
  foreign key (law_firm_id, job_id)
    references file_export_jobs (law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, file_id)
    references files (law_firm_id, id) on delete cascade
);

drop trigger if exists set_updated_at on file_export_job_sources;
create trigger set_updated_at before update on file_export_job_sources
  for each row execute function set_updated_at();

-- Only the file arm needs its own index. The job arm leads the primary key
-- already, so a second index on it would be one the planner never picks and one
-- more structure every insert has to maintain. The file arm is a foreign key
-- that leads no other index, so without one a cascade delete of a document
-- scans the whole table.
create index if not exists file_export_job_sources_file_idx
  on file_export_job_sources (law_firm_id, file_id);

-- =====================================================================
-- STORAGE RESERVATIONS (quota held by uploads still in flight)
-- =====================================================================

-- One row per file an upload-init opened, holding its declared size against the
-- firm's quota until finalize charges what landed and deletes the row, a cancel
-- deletes it, or it expires. `law_firms.storage_used_bytes` counts SAVED files
-- only; admission counts that plus every live row here, under a lock on the
-- firm row so two concurrent uploads cannot both slip past a hard limit.
--
-- The expiry is what makes an abandoned upload harmless: a crashed tab or a
-- failed browser upload frees its quota when the row lapses, without anyone
-- acting. A lapsed row is ignored by the sum and purged by the next reservation
-- or recount. See shared/utils/storageUsage.ts.
--
-- Rows are inserted and deleted, never updated, so there is no `updated_at`.
create table if not exists storage_reservations (
  id           uuid not null default gen_random_uuid(),
  law_firm_id  uuid not null references law_firms(id) on delete cascade,
  -- The uploader. Only they may release it early, so one member cannot free
  -- quota another member is holding for an upload still in flight.
  created_by   text not null references users(id) on delete cascade,
  bytes        bigint not null check (bytes >= 0),
  created_at   timestamptz not null default now(),
  -- After this the reservation no longer counts, whether or not anyone
  -- released it.
  expires_at   timestamptz not null,
  primary key (id),
  unique (law_firm_id, id),
  constraint storage_reservations_expiry_after_creation check (expires_at > created_at)
);

-- The admission sum and the purge both read one firm's rows by expiry.
create index if not exists storage_reservations_firm_expiry_idx
  on storage_reservations (law_firm_id, expires_at);
create index if not exists storage_reservations_created_by_idx
  on storage_reservations (created_by);




create table if not exists document_requests (
  id           uuid not null default gen_random_uuid(),
  law_firm_id  uuid not null references law_firms(id) on delete cascade,
  matter_id    uuid,
  -- The client the request is addressed to (must be a client on the matter,
  -- or any client of the firm when matter_id is null).
  client_id    uuid not null,
  title        text not null,
  note         text,
  status       text not null default 'open'
               check (status in ('open','completed','cancelled')),
  due_date     date,
  created_by   text references users(id) on delete restrict,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  foreign key (law_firm_id, matter_id) references matters (law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, client_id) references clients (law_firm_id, id) on delete cascade
);
create index if not exists document_requests_firm_client_idx on document_requests (law_firm_id, client_id);

-- One requested document. 'received' once at least one file is uploaded against
-- it; 'waived' if the firm decides it is no longer needed.
create table if not exists document_request_items (
  id           uuid not null default gen_random_uuid(),
  law_firm_id  uuid not null references law_firms(id) on delete cascade,
  request_id   uuid not null references document_requests(id) on delete cascade,
  label        text not null,
  -- Optional detail shown to the client alongside the label, explaining what
  -- exactly is needed for this item. Migration 0163.
  description  text,
  status       text not null default 'pending'
               check (status in ('pending','received','waived')),
  sort_order   integer not null default 0,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id)
);
create index if not exists document_request_items_request_idx on document_request_items (request_id, sort_order);

-- Persist upload sessions so a lost init response can be retried safely.
create table if not exists document_request_uploads (
  id uuid primary key default gen_random_uuid(),
  law_firm_id uuid not null references law_firms(id) on delete cascade,
  item_id uuid not null,
  created_by text not null references users(id) on delete restrict,
  action_key uuid not null,
  position integer not null check (position >= 0),
  request_hash text not null,
  file_id uuid not null,
  upload_url text not null,
  reservation_id uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (law_firm_id, id),
  unique (law_firm_id, item_id, created_by, action_key, position),
  foreign key (law_firm_id, item_id) references document_request_items(law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, file_id) references files(law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, reservation_id) references storage_reservations(law_firm_id, id) on delete set null (reservation_id)
);
create index if not exists document_request_uploads_item_idx on document_request_uploads (item_id);
create index if not exists document_request_uploads_creator_idx on document_request_uploads (created_by);
create index if not exists document_request_uploads_file_idx on document_request_uploads (file_id);
create index if not exists document_request_uploads_reservation_idx on document_request_uploads (reservation_id);
create index if not exists document_request_uploads_firm_file_idx on document_request_uploads (law_firm_id, file_id);
create index if not exists document_request_uploads_firm_reservation_idx on document_request_uploads (law_firm_id, reservation_id);

-- Links an item to the file(s) that answered it, through the `attachments`
-- table's `document_request_item_id` arm. The file itself is a `files` row like
-- any other, so a rename or a move leaves the link intact.

create table if not exists document_request_templates (
  id             uuid not null default gen_random_uuid(),
  law_firm_id    uuid not null references law_firms(id) on delete cascade,
  name           text not null,
  default_title  text not null,
  default_note   text,
  items          jsonb not null default '[]',
  archived       boolean not null default false,
  created_by     text references users(id) on delete restrict,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id)
);
create index if not exists document_request_templates_firm_idx on document_request_templates (law_firm_id, archived, name);

-- Secure external file share links: expiring, optionally password-protected links
-- to a file, or to several files and folders, for parties without a portal account (opposing counsel, experts,
-- courts). The token is the credential; a PUBLIC route resolves it to a short-lived
-- signed URL and never exposes the object path. SQL-authoritative. Migration 0118.
--
-- The token is the primary key. `file_id` and `revoked_at` (migration 0236) are the
-- first half of the D1 cutover: the link is being repointed from `object_path` onto
-- the `files` row, and `revoked` is being replaced by a timestamp. Both old columns
-- are still authoritative for readers, so both pairs are kept in step by
-- `file_share_links_sync_revoked` below until the second half retires them.
create table if not exists file_share_links (
  token          text primary key,
  law_firm_id    uuid not null references law_firms(id) on delete cascade,
  -- `set null`, not `cascade`: a destroyed document REVOKES its links (the
  -- sweeper writes that) and the row survives, so the public route can answer
  -- "revoked" rather than "no such link". A soft-deleted file keeps its id, so
  -- an ordinary delete leaves this pointing at the row it always did.
  file_id        uuid references files(id) on delete set null,
  display_name   text not null,
  mime_type      text,
  -- 'view' forces inline disposition; 'download' forces attachment.
  permission     text not null default 'download'
                 check (permission in ('view','download')),
  -- scrypt hash (never the plaintext); null = no password required.
  password_hash  text,
  expires_at     timestamptz not null,
  -- Null means live. There is no separate boolean: two columns for one fact is
  -- how they came to disagree.
  revoked_at     timestamptz,
  access_count   integer not null default 0,
  last_accessed_at timestamptz,
  created_by     text references users(id) on delete restrict,
  created_at     timestamptz not null default now(),
  -- What `file_share_link_items` points at, so an item cannot name a link in
  -- another firm. Migration 0014.
  unique (law_firm_id, token),
  foreign key (law_firm_id, file_id) references files(law_firm_id, id) on delete set null (file_id)
);

create index if not exists file_share_links_firm_file_idx on file_share_links (law_firm_id, file_id) where file_id is not null;
create index if not exists file_share_links_file_id_idx on file_share_links (file_id) where file_id is not null;

-- The files and folders a multi-item share link names (migration 0014). A link
-- with rows here carries a null `file_id`; a link without rows is the
-- single-file shape above. A folder shares what is inside it when the link is
-- opened, not what was inside it when the link was made. Written once with the
-- link and never updated: revoking acts on the link, and a deleted item drops
-- out of what the link resolves to at read time.
create table if not exists file_share_link_items (
  law_firm_id uuid not null references law_firms(id) on delete cascade,
  token       text not null,
  file_id     uuid not null,
  created_at  timestamptz not null default now(),
  primary key (law_firm_id, token, file_id),
  foreign key (law_firm_id, token) references file_share_links (law_firm_id, token) on delete cascade,
  foreign key (law_firm_id, file_id) references files (law_firm_id, id) on delete cascade
);
create index if not exists file_share_link_items_file_idx
  on file_share_link_items (law_firm_id, file_id);

-- Column comments. These were written by earlier migrations and never carried
-- into the domain files, so a database built from schema.sql lacked them while
-- a migrated one had them. They are the reference for what each column means.
comment on column document_requests.matter_id is 'Matter this request targets. Null means a client-level "General" request not tied to any matter.';
comment on column template_field_placements.font_size is 'User-chosen point size. Null keeps the historical auto-fit-to-box behavior (text/date placements created before this column existed).';
comment on column template_field_placements.image_mime_type is 'MIME type of image_object_path''s bytes. Null for other types.';
comment on column template_field_placements.image_object_path is 'GCS object path of the uploaded image for an image placement (field_type = image). Null for other types.';
comment on column template_field_placements.text_content is 'Literal text for a textbox placement (field_type = textbox), stamped as-is on every filled document. Null for other types.';
comment on column templates.overlay_pdf_object_path is 'GCS object path of the PDF rendered as the overlay editor canvas. Equal to the uploaded file when it was already a PDF, otherwise a one-time LibreOffice-converted copy made at upload.';
comment on column templates.overlay_source_object_path is 'GCS object path of the original uploaded file for an overlay-type template (PDF or a convertible format), kept for reference/re-conversion.';

-- >>> 86_messaging.sql <<<
-- =====================================================================
-- MESSAGING (RLS on)
-- =====================================================================

create table if not exists conversations (
  id                   uuid not null default gen_random_uuid(),
  law_firm_id          uuid references law_firms(id) on delete cascade,
  client_id            text references users(id) on delete set null,
  last_message_at      timestamptz,
  last_sender_user_id  text references users(id) on delete restrict,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  last_notification_email_at timestamptz,
  conversation_type    text not null default 'direct'
                         check (conversation_type in ('direct','group')),   -- migration 0102
  title                text,                                                 -- group title (migration 0102)
  matter_id            uuid,                                                 -- group confidentiality scope (migration 0102)
  created_by           text references users(id) on delete restrict,                                                 -- migration 0102
  hide_client_names    boolean not null default false,                       -- per-conversation client-name masking (migration 0106)
  archived_at          timestamptz,                                          -- firm-side archive; null = active (migration 0109)
  archived_by          text references users(id) on delete restrict,                                                 -- who archived it (migration 0109)
  -- The clients.id this group conversation is the canonical company thread
  -- for (organization-clients plan). Null for direct (person) conversations
  -- and for ordinary group threads with no company binding. client_id above
  -- stays the PERSON direct-thread identity (a Firebase UID); this is the
  -- separate company identity. No ON DELETE SET NULL (would null law_firm_id
  -- too on this composite FK) and no ON DELETE CASCADE (a client delete must
  -- not silently destroy message history) - the default RESTRICT blocks
  -- deleting a company client with a live canonical conversation.
  client_record_id     uuid,
  primary key (id),
  unique (law_firm_id, id),
  -- Direct threads dedupe by (firm, client). Group threads set client_id = NULL;
  -- Postgres treats NULLs as distinct here, so unlimited groups coexist.
  unique (law_firm_id, client_id),
  -- restrict on purpose: a client with a conversation cannot be deleted out
  -- from under it. It was the one key the retired SOFT-REFERENCE sweep spared.
  foreign key (law_firm_id, client_record_id) references clients (law_firm_id, id) on delete restrict
);
create index if not exists conversations_firm_idx on conversations (law_firm_id, last_message_at desc);
create index if not exists conversations_client_idx on conversations (client_id, last_message_at desc);
create index if not exists conversations_archived_idx on conversations (law_firm_id, archived_at);
-- One canonical (non-archived) company conversation per (firm, client). The
-- archived_at exclusion matters: without it, archiving a company's canonical
-- thread would permanently block creating or finding a replacement, because
-- the index would still reject the new insert.
create unique index if not exists conversations_client_record_active_idx
  on conversations (law_firm_id, client_record_id)
  where client_record_id is not null and archived_at is null;

-- Group-conversation membership (migration 0102). Direct threads do NOT use this
-- table; they keep the client_id column + read_by_firm/read_by_client flags.

-- =====================================================================
-- CONVERSATION PARTICIPANTS (merged from migration 0234)
-- =====================================================================

create table if not exists conversation_participants (
  id                  uuid not null default gen_random_uuid(),
  conversation_id     uuid not null references conversations(id) on delete cascade,
  participant_user_id text references users(id) on delete restrict,
  client_id           uuid references clients(id) on delete cascade,
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  participant_type    text not null check (participant_type in ('client', 'firm_member')),
  added_by            text references users(id) on delete restrict,
  added_at            timestamptz not null default now(),
  removed_at          timestamptz,
  last_read_at        timestamptz,
  history_visible_from timestamptz,
  primary key (id),
  unique (law_firm_id, id),
  foreign key (law_firm_id, client_id) references clients(law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, conversation_id) references conversations(law_firm_id, id) on delete cascade,
  constraint conversation_participants_actor_ck check (participant_user_id is not null or client_id is not null)
);

create unique index if not exists conv_participants_conv_user_idx
  on conversation_participants (conversation_id, participant_user_id);

create unique index if not exists conv_participants_conv_client_idx
  on conversation_participants (conversation_id, client_id);

create index if not exists conv_participants_client_idx
  on conversation_participants (client_id)
  where client_id is not null;

create index if not exists conv_participants_firm_client_idx
  on conversation_participants (law_firm_id, client_id)
  where client_id is not null;

create index if not exists conv_participants_firm_conv_idx
  on conversation_participants (law_firm_id, conversation_id);

create index if not exists conv_participants_user_idx
  on conversation_participants (participant_user_id) where removed_at is null;

create index if not exists conv_participants_conv_idx
  on conversation_participants (conversation_id) where removed_at is null;


create table if not exists conversation_matters (
  conversation_id uuid not null references conversations(id) on delete cascade,
  law_firm_id     uuid not null references law_firms(id) on delete cascade,
  matter_id       uuid not null,
  position        integer not null default 0,
  created_at      timestamptz not null default now(),
  primary key (conversation_id, matter_id),
  foreign key (law_firm_id, matter_id) references matters (law_firm_id, id) on delete cascade
);
create index if not exists conversation_matters_matter_idx
  on conversation_matters (law_firm_id, matter_id);

create table if not exists messages (
  id                  uuid primary key default gen_random_uuid(),
  conversation_id     uuid not null references conversations(id) on delete cascade,
  law_firm_id         uuid references law_firms(id) on delete cascade,
  sender_user_id      text references users(id) on delete restrict,
  content             text not null default '',
  attachments         jsonb,
  mentions            jsonb not null default '[]',
  -- NULL is a real value: recordParticipantEvent writes system rows for inline
  -- participant add and remove events, which have no sender.
  sender_type         text
    check (sender_type is null or sender_type in ('client', 'firm_member')),
  -- Who spoke, as THIS FIRM recorded it. Not a cache of users.name: a firm that
  -- erases a client tombstones this copy (anonymizeParticipantIdentity) even
  -- when the person is still a live client of another firm, whose threads keep
  -- the name. A join has one value platform-wide and cannot express that.
  sender_name         text,
  sent_as_firm        boolean not null default false,                          -- "send as firm" snapshot (migration 0107)
  read                boolean not null default false,
  read_by_firm        boolean not null default false,
  read_by_client      boolean not null default false,
  read_at             timestamptz,
  matter_id           uuid,
  status              text default 'sent',
  edited_at           timestamptz,                                            -- set when the sender edits (marker only; original text not retained) (migration 0110)
  deleted_at          timestamptz,                                            -- soft delete: row retained, content masked on read (migration 0110)
  deleted_by          text references users(id) on delete restrict,                              -- who soft-deleted the message (migration 0110)
  kind                text not null default 'user'
                        check (kind in ('user','system')),                    -- 'system' = inline participant add/remove event (migration 0114)
  system_event        jsonb,                                                  -- structured payload for kind='system' rows (migration 0114)
  created_at          timestamptz not null default now(),
  updated_at          timestamptz
);
create index if not exists messages_conversation_created_idx on messages (conversation_id, created_at desc) include (content);
-- Unread counts. `CONV_JOINS` counts per conversation with `filter (where
-- sender_type = ... and read_by_... = false)`, and the two firm-wide unread
-- counters and the mark-read update filter the same way. Each partial holds
-- only the rows still unread on that side, so the count is a tiny index scan
-- rather than a walk of every message the conversation ever had.
create index if not exists messages_client_unread_idx on messages (conversation_id)
  where sender_type = 'firm_member' and read_by_client = false;
create index if not exists messages_firm_unread_idx on messages (conversation_id)
  where sender_type = 'client' and read_by_firm = false;
-- FK probe support (see migration 0130): messages had no law_firm_id index, so
-- deleting a firm scanned the whole table.
create index if not exists messages_firm_idx
  on messages (law_firm_id);
create index if not exists messages_deleted_by_idx
  on messages (deleted_by) where deleted_by is not null;

-- ── messaging RLS (migration 0025): Realtime reads via a Firebase-uid JWT ──
-- Backend writes as `postgres` (bypasses RLS); the Realtime client connects as
-- `authenticated` (sub = firebase uid) and only sees its own rows.
create or replace function public.rls_is_firm_member(p_firm uuid, p_uid text)
returns boolean language sql security definer stable set search_path = public as $$
  select exists (select 1 from members m where m.law_firm_id = p_firm and m.user_id = p_uid)
$$;
revoke all on function public.rls_is_firm_member(uuid, text) from public;
grant execute on function public.rls_is_firm_member(uuid, text) to authenticated;

create or replace function public.rls_is_conversation_client(p_conversation uuid, p_uid text)
returns boolean language sql security definer stable set search_path = public as $$
  select exists (
    select 1 from conversations c
     where c.id = p_conversation and c.client_id = p_uid
  )
$$;
revoke all on function public.rls_is_conversation_client(uuid, text) from public;
grant execute on function public.rls_is_conversation_client(uuid, text) to authenticated;

-- Group conversations are visible only to their participants (migration 0103);
-- direct threads keep firm-wide + client-owner visibility.
create or replace function public.rls_is_conversation_participant(p_conversation uuid, p_uid text)
returns boolean language sql security definer stable set search_path = public, pg_catalog as $$
  select exists (
    select 1 from conversation_participants cp
     where cp.conversation_id = p_conversation
       and cp.participant_user_id = p_uid
       and cp.removed_at is null
  )
$$;
revoke all on function public.rls_is_conversation_participant(uuid, text) from public;
grant execute on function public.rls_is_conversation_participant(uuid, text) to authenticated;

alter table conversations enable row level security;
drop policy if exists conversations_realtime_select on conversations;
create policy conversations_realtime_select on conversations for select using (
  case when conversation_type = 'group'
    then public.rls_is_conversation_participant(id, auth.jwt() ->> 'sub')
    else ((auth.jwt() ->> 'sub') = client_id
          or public.rls_is_firm_member(law_firm_id, auth.jwt() ->> 'sub'))
  end
);

-- consolidated messages access helper (migration 0072): folds the client-
-- participant and firm-member checks into one SECURITY DEFINER call so the
-- messages policy is a single cheap function call instead of a per-row
-- correlated subquery. Returns true when the uid is the conversation's client
-- OR a member of the conversation's firm. search_path is pinned to block the
-- classic SECURITY DEFINER search_path hijack.
create or replace function public.messaging_can_access_conversation(p_conversation uuid, p_uid text)
returns boolean language sql security definer stable set search_path = public, pg_catalog as $$
  select exists (
    select 1 from conversations c
     where c.id = p_conversation
       and (
         case when c.conversation_type = 'group'
           then exists (select 1 from conversation_participants cp
                         where cp.conversation_id = c.id
                           and cp.participant_user_id = p_uid
                           and cp.removed_at is null)
           else (c.client_id = p_uid
                 or exists (select 1 from members m where m.law_firm_id = c.law_firm_id and m.user_id = p_uid))
         end
       )
  )
$$;
revoke all on function public.messaging_can_access_conversation(uuid, text) from public;
grant execute on function public.messaging_can_access_conversation(uuid, text) to authenticated;

-- Realtime MESSAGE-row access (migrations 0105 and 0040). Firm members only.
-- A raw messages row is unmasked: it carries the plaintext sender_name and
-- sender_user_id of a "send as firm" message, a co-client's real name in a
-- group, and the retained content of a soft-deleted message in an UPDATE
-- payload. So no client may stream message rows, in a group or a direct
-- thread. Clients get live updates by watching their conversations row (and
-- the content-free group broadcast) and refetching through the masked REST
-- reads. A group still needs the member to be an active participant.
create or replace function public.messaging_realtime_message_access(p_conversation uuid, p_uid text)
returns boolean language sql security definer stable set search_path = public, pg_catalog as $$
  select exists (
    select 1 from conversations c
     where c.id = p_conversation
       and exists (select 1 from members m
                    where m.law_firm_id = c.law_firm_id and m.user_id = p_uid)
       and (c.conversation_type <> 'group'
            or exists (select 1 from conversation_participants cp
                        where cp.conversation_id = c.id
                          and cp.participant_user_id = p_uid
                          and cp.removed_at is null))
  )
$$;
revoke all on function public.messaging_realtime_message_access(uuid, text) from public;
grant execute on function public.messaging_realtime_message_access(uuid, text) to authenticated;

alter table messages enable row level security;
drop policy if exists messages_realtime_select on messages;
create policy messages_realtime_select on messages for select using (
  public.messaging_realtime_message_access(messages.conversation_id, auth.jwt() ->> 'sub')
);

-- Participant rows (migration 0040): a firm member with access to the thread
-- sees the whole roster; anyone else (a client) sees only their own row, so a
-- client cannot read lawyers' last_read_at, co-clients' history_visible_from,
-- or a pending recipient's client_id. Clients read the masked roster over REST.
alter table conversation_participants enable row level security;
drop policy if exists conversation_participants_select on conversation_participants;
create policy conversation_participants_select on conversation_participants for select using (
  public.messaging_can_access_conversation(conversation_id, auth.jwt() ->> 'sub')
  and (participant_user_id = (auth.jwt() ->> 'sub')
       or public.rls_is_firm_member(law_firm_id, auth.jwt() ->> 'sub'))
);

grant usage on schema public to authenticated;
grant select on conversations to authenticated;
grant select on messages to authenticated;
grant select on conversation_participants to authenticated;
do $$
begin
  begin execute 'alter publication supabase_realtime add table conversations'; exception when others then null; end;
  begin execute 'alter publication supabase_realtime add table messages'; exception when others then null; end;
  begin execute 'alter publication supabase_realtime add table conversation_participants'; exception when others then null; end;
end $$;

-- =====================================================================
-- ATTACHMENTS (polymorphic attachment ledger from migration 0236)
-- =====================================================================

create table if not exists attachments (
  id                        uuid primary key default gen_random_uuid(),
  law_firm_id               uuid not null references law_firms(id) on delete cascade,
  file_id                   uuid not null references files(id) on delete cascade,
  note_id                   uuid,
  note_reply_id             uuid,
  message_id                uuid references messages(id) on delete cascade,
  task_id                   uuid,
  event_id                  uuid,
  activity_id               uuid,
  document_request_item_id  uuid,
  -- Who attached the file. For a document request this is what separates a
  -- client's own upload from one a firm member attached on their behalf, which
  -- the portal delete path asks before it lets a client remove a row.
  created_by                text references users(id) on delete restrict,
  -- Position within the parent record, 0-based. `created_at` cannot serve: it
  -- defaults to now(), the TRANSACTION timestamp, so every row one save writes
  -- carries the same value. Only the three arcs that replaced an ordered jsonb
  -- array in migration 0260 write it; it is null everywhere else.
  sort_order                int,
  created_at                timestamptz not null default now(),
  updated_at                timestamptz not null default now(),
  unique (law_firm_id, id),
  foreign key (law_firm_id, file_id) references files(law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, note_id) references notes(law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, note_reply_id) references note_replies(law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, task_id) references tasks(law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, event_id) references events(law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, activity_id) references activities(law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, document_request_item_id) references document_request_items(law_firm_id, id) on delete cascade,
  check (num_nonnulls(note_id, note_reply_id, message_id, task_id, event_id, activity_id, document_request_item_id) = 1)
);

drop trigger if exists set_updated_at on attachments;
create trigger set_updated_at before update on attachments
  for each row execute function set_updated_at();

comment on column attachments.sort_order is 'Position within the parent record, 0-based. Written by the note, note reply and task arcs, which replaced an ordered jsonb array in migration 0260; null on every other arc, which orders by its own key.';

create index if not exists attachments_file_id_idx on attachments (file_id);
create index if not exists attachments_created_by_idx on attachments (created_by) where created_by is not null;
create index if not exists attachments_firm_file_idx on attachments (law_firm_id, file_id);
create index if not exists attachments_firm_note_idx on attachments (law_firm_id, note_id) where note_id is not null;
create index if not exists attachments_firm_note_reply_idx on attachments (law_firm_id, note_reply_id) where note_reply_id is not null;
create index if not exists attachments_message_idx on attachments (message_id) where message_id is not null;
create index if not exists attachments_firm_task_idx on attachments (law_firm_id, task_id) where task_id is not null;
create index if not exists attachments_firm_event_idx on attachments (law_firm_id, event_id) where event_id is not null;
create index if not exists attachments_firm_activity_idx on attachments (law_firm_id, activity_id) where activity_id is not null;
create index if not exists attachments_firm_doc_req_item_idx on attachments (law_firm_id, document_request_item_id) where document_request_item_id is not null;


-- =====================================================================
-- RLS for messaging (policies added in the Realtime phase)
-- =====================================================================
alter table conversations enable row level security;
alter table messages      enable row level security;

-- Column comments. These were written by earlier migrations and never carried
-- into the domain files, so a database built from schema.sql lacked them while
-- a migrated one had them. They are the reference for what each column means.
comment on column conversations.client_record_id is 'The clients.id this group conversation is the canonical company thread for. Null for direct (person) conversations and for ordinary group threads with no company binding.';

-- >>> 87_signatures.sql <<<
-- =====================================================================
-- SIGNATURES  (native relational; session PK is the text token. See 0029.)
-- =====================================================================

-- =====================================================================
-- SIGNATURE SOURCES
-- =====================================================================
-- The admission boundary. Every document that reaches a signer passes through a
-- row here first, whichever route uploaded it, and nothing downstream may read
-- bytes that this row does not vouch for.
--
-- The row exists because "the caller uploaded it" is not the same fact as "this
-- is a document we can sign". The upload routes could each check the bytes
-- themselves, and did, in three places that drifted: one checked the leading
-- bytes, one trusted the declared size, and the template route checked neither.
-- A single record with a status is the only shape where a new entry point
-- cannot quietly skip the check, because there is nothing else to point a
-- session at.
--
-- `object_generation` is TEXT, not a number. A GCS generation is a 64-bit value
-- and a JS number rounds past 2^53, so two different versions of an object
-- would compare equal and a document replaced mid-signing would be signed half
-- from one version and half from the next.
create table if not exists signature_sources (
  id                      uuid primary key default gen_random_uuid(),
  law_firm_id             uuid not null references law_firms(id) on delete cascade,
  uploaded_by             text references users(id) on delete restrict,
  -- The immutable object the signer's document is read from, pinned to the
  -- exact version that was inspected.
  object_path             text not null,
  object_generation       text,
  size_bytes              bigint,
  -- SHA-256 of the bytes as uploaded, before any preparation.
  document_hash           text,
  -- Which admission policy accepted this. A source admitted under an older
  -- policy is not silently re-admitted under a newer one.
  profile_version         int not null default 1,
  status                  text not null default 'pending'
                            check (status in ('pending','preparing','ready','failed')),
  -- One of the stable refusal codes the routes return. Parser internals never
  -- reach a user; this is what the copy is chosen from.
  failure_code            text
                            check (failure_code is null or failure_code in (
                              'PDF_INVALID','PDF_ENCRYPTED','PDF_EXISTING_SIGNATURE',
                              'PDF_UNSUPPORTED_FORM','PDF_RESOURCE_LIMIT',
                              'FILE_TOO_LARGE','SOURCE_CHANGED')),
  failure_detail          text,
  -- What the signer actually views: the source after forms are flattened. It is
  -- a separate object, because the completed PDF must retain these bytes
  -- exactly and the original upload has to stay untouched as evidence.
  prepared_object_path    text,
  prepared_generation     text,
  prepared_size_bytes     bigint,
  prepared_hash           text,
  page_count              int,
  -- The saved SHA-256 state over the prepared source, so sealing never reads
  -- those bytes again. It is meaningless without the three columns beside it:
  -- resumed over a different object, a different version, or a different
  -- length, it produces a digest of a byte sequence that was never in any file,
  -- and that digest signs cleanly.
  digest_algorithm        text,
  digest_library_version  text,
  -- Base64, not bytea. The state is 116 opaque bytes, and text keeps it
  -- readable in a psql session and correctly typed by the generated Drizzle
  -- schema, which maps bytea to the wrong column type.
  digest_state            text,
  digest_state_bytes      bigint,
  digest_state_generation text,
  -- The durable preparation operation, for polling readiness. Hashing 2 GB does
  -- not fit inside an interactive request.
  operation_id            uuid,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  unique (law_firm_id, id),
  -- One source per stored object. A second admission of the same bytes would be
  -- a second opinion on whether they are signable.
  unique (law_firm_id, object_path)
);

create index if not exists signature_sources_firm_status_idx
  on signature_sources (law_firm_id, status, created_at desc);
-- The delete of a user is `restrict`, so it has to look for rows naming that
-- account. Without a leading index that look is a scan of every source the
-- platform has ever admitted.
create index if not exists signature_sources_uploaded_by_idx
  on signature_sources (uploaded_by);
-- Drives the drain that finishes interrupted preparations.
create index if not exists signature_sources_preparing_idx
  on signature_sources (status, updated_at)
  where status in ('pending', 'preparing');

alter table signature_sources enable row level security;
drop policy if exists signature_sources_select on signature_sources;
create policy signature_sources_select on signature_sources for select to authenticated
  using (public.rls_is_firm_member(law_firm_id, auth.jwt()->>'sub'));

create table if not exists signature_sessions (
  id                      uuid not null default gen_random_uuid(),
  token                   text not null unique,
  law_firm_id             uuid not null references law_firms(id) on delete cascade,
  created_by              text references users(id) on delete restrict,
  routing_mode            text not null default 'sequential'
                            check (routing_mode in ('sequential','parallel')),
  -- The admitted source these bytes came from. A session with no source has not
  -- passed the admission boundary and must not reach a signer.
  -- The admitted source this session was built from. Recorded when the session
  -- is created, so finalization reads the PREPARED copy and the hash state
  -- saved over it rather than pinning an upload and streaming it again.
  source_id               uuid not null,
  object_path             text,
  working_object_path     text,
  final_object_path       text,
  signed_object_path      text,
  file_name               text,
  -- The folder the executed copy is filed into. A folder ROW, not a path: the
  -- session outlives what it points at, and a path could name a folder that a
  -- matter delete already swept, filing an executed document where nothing
  -- lists it. The FK makes that impossible; the cascade is `set null`, which
  -- the filing code reads as "file it into General Files instead".
  destination_folder_id   uuid,
  destination_label       text,
  status                  text not null default 'pending'
                            check (status in ('pending','in_progress','completed','cancelled','expired')),
  current_signer_order    int,
  document_hash           text,
  -- A completed session seals TWO PDFs: the copy filed in the firm's documents,
  -- which carries the appended Signature Certificate page (signed_document_hash),
  -- and the copy emailed to signers and posted into the portal, which does not
  -- (delivery_document_hash). Sealing makes their bytes differ, so /signing/verify
  -- has to recognise both or it rejects the very PDF the signer was sent.
  signed_document_hash    text,
  delivery_document_hash  text,
  notify_email            citext,
  notify_name             text,
  email_signers_on_complete boolean not null default false,
  started_at              timestamptz,
  completed_at            timestamptz,
  -- The last time the sealed artifacts were re-read from storage and checked
  -- against what this row says they are, and what that check found.
  --
  -- Production verification resumes the same saved hash state it signed with,
  -- so a defect in the resume path is invisible to it: the same wrong answer
  -- twice agrees with itself. This audit is the only reader that does not
  -- share that assumption, because it streams every byte back out of storage.
  audited_at              timestamptz,
  audit_result            text
                            check (audit_result is null or audit_result in ('ok', 'mismatch', 'unreadable')),
  audit_detail            text,
  -- Delivery of the executed copies, recorded so a crash between completing a
  -- session and emailing its signers cannot lose the emails (migration 0018).
  -- `delivery_owed_at` is stamped by the completion write; null means nothing
  -- is owed through this mechanism, which is every session completed before it
  -- existed. A worker claims by taking `delivery_lease_expires_at` BEFORE it
  -- sends and stamps `delivered_at` AFTER, so a crash mid-send is re-sent once
  -- the lease lapses: at least once, never lost, never re-sent once stamped.
  delivery_owed_at          timestamptz,
  delivery_lease_expires_at timestamptz,
  delivery_attempts         int not null default 0,
  delivered_at              timestamptz,
  -- NOT NULL with a default (migration 0223); see invitations.expires_at.
  expires_at              timestamptz not null default now() + interval '30 days',
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  primary key (id),
  unique (law_firm_id, id),
  foreign key (law_firm_id, destination_folder_id)
    references files (law_firm_id, id) on delete set null,
  -- Restrict, not cascade. A source is the evidence of what was signed, so it
  -- outlives nothing: deleting one out from under a live session would leave
  -- the session unable to say what it put in front of the signer.
  constraint signature_sessions_source_fkey foreign key (law_firm_id, source_id)
    references signature_sources (law_firm_id, id) on delete restrict,
  constraint signature_sessions_delivered_requires_owed
    check (delivered_at is null or delivery_owed_at is not null)
);
-- The drain's pick of completed sessions whose copies are still owed. Partial,
-- because a delivered session never matches again.
create index if not exists signature_sessions_delivery_owed_idx
  on signature_sessions (delivery_owed_at)
  where delivery_owed_at is not null and delivered_at is null;
-- Without this the cascade behind a folder delete scans every session row.
create index if not exists signature_sessions_destination_idx
  on signature_sessions (law_firm_id, destination_folder_id);
create index if not exists signature_sessions_status_idx on signature_sessions (status);
-- The audit's pick: least recently checked first, never checked before that.
-- Partial, because the audit only ever looks at completed sessions and those
-- are a minority of the table for a busy firm.
create index if not exists signature_sessions_audit_idx
  on signature_sessions (audited_at nulls first, completed_at)
  where status = 'completed';
create index if not exists signature_sessions_signed_hash_idx on signature_sessions (signed_document_hash);
create index if not exists signature_sessions_delivery_hash_idx on signature_sessions (delivery_document_hash);
create index if not exists signature_sessions_firm_created_idx on signature_sessions (law_firm_id, created_at desc);
-- Drives the "sessions I sent that are still open" half of pending-for-user.
-- Partial on the open statuses: settled sessions are the bulk of the table and
-- that read never wants them.
create index if not exists signature_sessions_creator_open_idx
  on signature_sessions (law_firm_id, created_by, created_at desc)
  where status in ('pending', 'in_progress');

alter table signature_sessions enable row level security;
drop policy if exists signature_sessions_select on signature_sessions;
create policy signature_sessions_select on signature_sessions for select to authenticated
  using (public.rls_is_firm_member(law_firm_id, auth.jwt()->>'sub'));

-- =====================================================================
-- SIGNATURE PARTICIPANTS & TOKENS (normalized from migration 0235)
-- =====================================================================

create table if not exists signature_participants (
  id                       text primary key default gen_random_uuid()::text,
  session_id               uuid not null references signature_sessions(id) on delete cascade,
  law_firm_id              uuid not null references law_firms(id) on delete cascade,
  role_label               text,
  signing_order            int,
  delivery_method          text,
  name                     text,
  email                    citext,
  member_user_id           text references users(id) on delete restrict,
  client_user_id           text references users(id) on delete restrict,
  status                   text not null default 'waiting'
                             check (status in ('active','waiting','completed','declined','cancelled','expired')),
  requires_verification    boolean not null default false,
  -- The one-time code's outcome, kept here rather than on its challenge row:
  -- passing that gate verifies the PERSON's email address, which outlives any
  -- one code. The access code's outcome is per-code and lives on its row.
  email_verified           boolean not null default false,
  started_at               timestamptz,
  completed_at             timestamptz,
  consent                  jsonb,
  signer_uid               text,
  signer_name              text,
  signer_ip                text,
  facilitated_by           text references users(id) on delete restrict,
  field_values             jsonb,
  working_object_path      text,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now(),
  unique (law_firm_id, id),
  foreign key (law_firm_id, session_id) references signature_sessions(law_firm_id, id) on delete cascade
);

create index if not exists signature_participants_firm_session_idx on signature_participants (law_firm_id, session_id);
create index if not exists signature_participants_firm_status_idx on signature_participants (law_firm_id, status);
create index if not exists signature_participants_session_order_idx on signature_participants (session_id, signing_order);
create index if not exists signature_participants_member_idx on signature_participants (member_user_id);
create index if not exists signature_participants_client_idx on signature_participants (client_user_id);

alter table signature_participants enable row level security;
drop policy if exists signature_participants_select on signature_participants;
create policy signature_participants_select on signature_participants for select to authenticated
  using (
    client_user_id = auth.jwt()->>'sub'
    or member_user_id = auth.jwt()->>'sub'
    or public.rls_is_firm_member(law_firm_id, auth.jwt()->>'sub')
  );

create table if not exists signature_participant_tokens (
  token           text primary key,
  participant_id  text not null,
  session_id      uuid not null references signature_sessions(id) on delete cascade,
  law_firm_id     uuid not null references law_firms(id) on delete cascade,
  delivery_method text,
  created_at      timestamptz not null default now(),
  consumed_at     timestamptz,
  foreign key (law_firm_id, session_id) references signature_sessions(law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, participant_id) references signature_participants(law_firm_id, id) on delete cascade
);
create index if not exists signature_participant_tokens_session_id_idx on signature_participant_tokens (session_id);
create index if not exists signature_participant_tokens_participant_idx on signature_participant_tokens (participant_id);
create index if not exists signature_participant_tokens_firm_session_idx on signature_participant_tokens (law_firm_id, session_id);
create index if not exists signature_participant_tokens_firm_part_idx on signature_participant_tokens (law_firm_id, participant_id);


-- =====================================================================
-- SIGNATURE FIELDS (normalized from migration 0235)
-- =====================================================================

-- A field id is the client's name for the field, unique only within its
-- session: sessions sent from one signing template reuse the template's ids.
-- Nothing references a field row, so the tenant boundary is the composite
-- foreign key to the session rather than a `unique (law_firm_id, id)`.
create table if not exists signature_fields (
  id              text not null default gen_random_uuid()::text,
  session_id      uuid not null references signature_sessions(id) on delete cascade,
  law_firm_id     uuid not null references law_firms(id) on delete cascade,
  signer_id       text,
  page            int,
  x_percent       numeric,
  y_percent       numeric,
  width_percent   numeric,
  height_percent  numeric,
  field_type      text
    check (field_type is null or field_type in
      ('signature', 'initials', 'date', 'text', 'checkbox')),
  label           text,
  required        boolean,
  style           text,
  sort_order      int,
  config          jsonb,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint signature_fields_pkey primary key (session_id, id),
  foreign key (law_firm_id, session_id) references signature_sessions(law_firm_id, id) on delete cascade
);
create index if not exists signature_fields_firm_session_idx on signature_fields (law_firm_id, session_id);


-- =====================================================================
-- SIGNATURE CHALLENGES (from migration 0235)
-- =====================================================================

create table if not exists signature_challenges (
  id                  uuid primary key default gen_random_uuid(),
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  session_id          uuid not null references signature_sessions(id) on delete cascade,
  participant_id      text not null references signature_participants(id) on delete cascade,
  kind                text not null check (kind in ('otp', 'access_code')),
  secret_hash         text,
  expires_at          timestamptz,
  attempts            int not null default 0,
  lifetime_attempts   int not null default 0,
  locked_until        timestamptz,
  verified_at         timestamptz,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (law_firm_id, id),
  foreign key (law_firm_id, session_id) references signature_sessions(law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, participant_id) references signature_participants(law_firm_id, id) on delete cascade
);
-- One row per participant per gate. The repository upserts on this key.
create unique index if not exists signature_challenges_participant_kind_uq
  on signature_challenges (participant_id, kind);
create index if not exists signature_challenges_firm_session_idx on signature_challenges (law_firm_id, session_id);
-- Leads with session_id, which the single-column foreign key to
-- signature_sessions(id) needs for its cascade. `(participant_id)` alone is
-- deliberately absent: it is a strict prefix of the unique gate key above.
create index if not exists signature_challenges_session_idx on signature_challenges (session_id);
create index if not exists signature_challenges_firm_part_idx on signature_challenges (law_firm_id, participant_id);


create table if not exists signature_templates (
  id               uuid primary key default gen_random_uuid(),
  law_firm_id      uuid not null references law_firms(id) on delete cascade,
  name             text,
  description      text,
  fields           jsonb,
  signer_roles     jsonb,
  source_file_name text,
  source_object_path text,
  -- The admitted source. Saving or applying a template requires one.
  source_id        uuid,
  routing_mode     text,
  created_by       text references users(id) on delete restrict,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (law_firm_id, id),
  constraint signature_templates_source_fkey foreign key (law_firm_id, source_id)
    references signature_sources (law_firm_id, id) on delete restrict
);
-- signature_templates_firm_idx covered by unique (law_firm_id, id)
create index if not exists signature_sessions_source_idx
  on signature_sessions (law_firm_id, source_id);
create index if not exists signature_templates_source_idx
  on signature_templates (law_firm_id, source_id);

-- =====================================================================
-- SIGNATURE PROCESSING JOBS
-- =====================================================================
-- Durable work for the two operations that cannot fit in a request.
--
-- Preparation hashes a whole document and finalization seals two artifacts.
-- Both used to run inside the request that triggered them, which means the work
-- existed only in one process's memory: kill the instance and the session was
-- left half-processed with nothing recording that anything was owed. Cloud Run
-- also stops scheduling CPU once a response is sent, so "return early and
-- finish in the background" does not finish.
--
-- A row here is the promise that the work is owed. It survives the process, it
-- names exactly what to do, and it can be picked up by a different instance.
--
-- The lease is what makes that safe. A worker claims a job by writing a token
-- and an expiry, and every checkpoint and every publish re-checks that token.
-- A worker that stalls past its expiry loses the job to someone else, and when
-- it wakes up its writes are refused rather than landing on top of the new
-- worker's. Without the token, a slow worker and its replacement both publish,
-- and the session ends up with two artifact sets and two completion emails.
create table if not exists signature_processing_jobs (
  id                uuid primary key default gen_random_uuid(),
  law_firm_id       uuid not null references law_firms(id) on delete cascade,
  -- The source the work reads. A preparation and a finalization both name one:
  -- every session records its source when it is created.
  source_id         uuid not null,
  -- Null for a preparation, which happens before any session exists.
  session_id        uuid,
  kind              text not null check (kind in ('prepare', 'finalize')),
  status            text not null default 'queued'
                      check (status in ('queued', 'leased', 'succeeded', 'failed', 'cancelled')),
  -- What the job was committed FOR: the source generation, or the field-layout
  -- revision the signer saw. A job that wakes up against a different revision
  -- refuses rather than applying old coordinates to a new document.
  input_revision    text,
  attempt           int not null default 0,
  next_attempt_at   timestamptz not null default now(),
  lease_owner       text,
  lease_token       uuid,
  lease_expires_at  timestamptz,
  -- The last phase whose output is durable, and the artifact generations it
  -- produced. An interrupted job resumes from here instead of starting over.
  phase             text,
  phase_state       jsonb,
  failure_code      text,
  failure_detail    text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (law_firm_id, id),
  -- Each kind names the thing it acts on. A preparation with no source has
  -- nothing to prepare, and a finalization with no session has nothing to
  -- finalize; both would sit in the queue failing for a reason no column states.
  -- A finalization names the session whose artifacts it produces. Without this
  -- such a job sits in the queue failing for a reason no column states. The
  -- other half of the old check, "a preparation names a source", is the NOT
  -- NULL on `source_id` above.
  constraint signature_processing_jobs_finalize_names_session check (
    kind <> 'finalize' or session_id is not null
  ),
  foreign key (law_firm_id, source_id)
    references signature_sources (law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, session_id)
    references signature_sessions (law_firm_id, id) on delete cascade
);

-- One LIVE job per logical operation. Two finalize jobs for one session would
-- each seal, publish and notify, and the session would end with two artifact
-- sets. Settled rows are excluded so a retry after a failure is still possible.
--
-- BOTH nullable columns are coalesced, and that is not cosmetic. Postgres treats
-- two NULLs as distinct in a unique index, so leaving either bare would let two
-- live jobs exist for exactly the rows that carry a null there: a preparation
-- has no session, and a finalization of a session admitted before the boundary
-- existed has no source. The guarantee would hold everywhere except the cases
-- it was written for.
create unique index if not exists signature_processing_jobs_live_idx
  on signature_processing_jobs (
    law_firm_id, kind, source_id,
    coalesce(session_id, '00000000-0000-0000-0000-000000000000'::uuid)
  )
  where status in ('queued', 'leased');

-- The drain's poll. Partial, because settled jobs are the bulk of the table and
-- this read never wants them.
create index if not exists signature_processing_jobs_ready_idx
  on signature_processing_jobs (next_attempt_at)
  where status = 'queued';

-- Reclaiming a job whose worker died. Same reason for the partial.
create index if not exists signature_processing_jobs_lease_idx
  on signature_processing_jobs (lease_expires_at)
  where status = 'leased';

create index if not exists signature_processing_jobs_firm_idx
  on signature_processing_jobs (law_firm_id, source_id, created_at desc);
-- The cascade behind a session delete finds this table's rows through the
-- composite key (law_firm_id, session_id), so the index has to lead with those
-- two in that order. The firm index above leads with law_firm_id and then
-- source_id, which does not serve it.
create index if not exists signature_processing_jobs_session_idx
  on signature_processing_jobs (law_firm_id, session_id);

alter table signature_processing_jobs enable row level security;
drop policy if exists signature_processing_jobs_select on signature_processing_jobs;
create policy signature_processing_jobs_select on signature_processing_jobs for select to authenticated
  using (public.rls_is_firm_member(law_firm_id, auth.jwt()->>'sub'));

-- =====================================================================
-- SIGNATURE AUDIT EVENTS (normalized from migration 0235)
-- =====================================================================

-- `participant_id` deliberately carries NO foreign key. The immutability trigger
-- below blocks every UPDATE on this table, so an `on delete set null` key would
-- turn deleting a participant into an aborted transaction rather than a cascade.
create table if not exists signature_audit_events (
  id              uuid primary key default gen_random_uuid(),
  session_id      uuid not null references signature_sessions(id) on delete cascade,
  law_firm_id     uuid not null references law_firms(id) on delete cascade,
  participant_id  text,
  -- The AUDIT_EVENTS constant in signatures/audit.ts. All write sites pass the
  -- constant rather than a literal.
  event_type      text
    check (event_type is null or event_type in (
      'session.created', 'session.viewed', 'document.viewed', 'consent.given',
      'session.completed', 'session.expired', 'session.cancelled',
      'participant.declined', 'participant.removed', 'email.sent',
      'reminder.sent', 'accesscode.verified', 'accesscode.failed')),
  ip              text,
  user_agent      text,
  actor_uid       text,
  metadata        jsonb,
  created_at      timestamptz not null default now(),
  unique (law_firm_id, id),
  foreign key (law_firm_id, session_id) references signature_sessions(law_firm_id, id) on delete cascade
);

create index if not exists signature_audit_events_session_id_idx on signature_audit_events (session_id, created_at);
create index if not exists signature_audit_events_firm_session_idx on signature_audit_events (law_firm_id, session_id);


-- =====================================================================
-- SIGNATURE AUDIT IMMUTABILITY
-- =====================================================================
-- Append-only audit trail. Blocks UPDATE only (tamper-prevention). DELETE is
-- intentionally allowed so the `on delete cascade` from signature_sessions (and
-- the session cleanup job) can purge audit rows; a blanket delete-block would
-- abort session deletion. Rows remain un-editable in place.
create or replace function signature_audit_immutable() returns trigger as $$
begin
  raise exception 'signature_audit_events are append-only: rows cannot be updated (id=%)', old.id;
end;
$$ language plpgsql;

drop trigger if exists signature_audit_immutable on signature_audit_events;
create trigger signature_audit_immutable before update on signature_audit_events
  for each row execute function signature_audit_immutable();

-- Realtime reads these two through the `authenticated` role. Without the grant
-- the policies above never get a chance to run: every read answers "permission
-- denied for table" instead of returning the rows the policy allows.
grant usage on schema public to authenticated;
grant select on signature_sessions     to authenticated;
grant select on signature_participants to authenticated;

do $$
begin
  begin execute 'alter publication supabase_realtime add table signature_sessions'; exception when duplicate_object then null; end;
  begin execute 'alter publication supabase_realtime add table signature_participants'; exception when duplicate_object then null; end;
end $$;

-- >>> 90_platform.sql <<<
-- =====================================================================
-- NOTIFICATIONS
-- =====================================================================

create table if not exists notifications (
  id                  uuid primary key default gen_random_uuid(),
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  user_id             text not null references users(id) on delete cascade,
  type                text not null,
  title               text not null,
  body                text not null,
  read                boolean not null default false,
  entity_type         text check (entity_type in ('task','matter','invoice','message','note','file')),
  entity_id           uuid,
  matter_id             uuid,
  action_url          text,
  created_by          text references users(id) on delete restrict,
  created_at          timestamptz not null default now(),
  -- unix-minute time bucket written by the repository at insert (floor(epoch/60));
  -- backs the atomic dedupe unique index below (see migration 0057).
  dedupe_bucket       bigint,
  -- md5 of the caller-declared dedupe key, or (by default) of the whole visible
  -- payload. Written by the repository at insert; see migration 0128.
  dedupe_hash         text
);
create index if not exists notifications_unread_idx on notifications (user_id, created_at desc) where not read;
create index if not exists notifications_user_idx on notifications (law_firm_id, user_id, created_at desc);
-- Atomic dedupe (migrations 0057, 0128): an event-outbox retry re-runs the
-- notification listener; this partial unique index + `insert ... on conflict do
-- nothing` makes the insert atomic so concurrent retries in the same minute
-- bucket can't double-insert.
--
-- The key is the payload hash, NOT (type, entity). Keying on the entity made two
-- notifications that shared a type and entity but differed in text collide, and
-- `on conflict do nothing` swallowed the second with no error. It also had to
-- disagree with the repository's pre-check, which matched `title`. Hashing what
-- the user actually sees makes the two agree: a retry re-sends a byte-identical
-- payload and collapses, while two genuinely different notifications both land.
create unique index if not exists notifications_dedupe_uq
  on notifications (law_firm_id, user_id, dedupe_hash, dedupe_bucket)
  where dedupe_hash is not null;
-- Cascade deletes when the entity a notification points at is deleted.
create index if not exists notifications_entity_idx
  on notifications (law_firm_id, entity_type, entity_id);
-- Retention sweep: delete read notifications older than the cutoff.
create index if not exists notifications_created_at_idx on notifications (created_at);

-- ── notifications RLS (migration 0074): Realtime reads via a Firebase-uid JWT ──
-- A notification belongs to one user, so the policy is a direct uid match (no
-- membership join). Backend writes as `postgres` (bypasses RLS); the Realtime
-- client connects as `authenticated` and only sees its own rows.
alter table notifications enable row level security;
drop policy if exists notifications_realtime_select on notifications;
create policy notifications_realtime_select on notifications for select using (
  (auth.jwt() ->> 'sub') = user_id
);
grant usage on schema public to authenticated;
grant select on notifications to authenticated;
-- REPLICA IDENTITY FULL (migration 0078): DELETE realtime events otherwise carry
-- only the PK, so the client's `user_id=eq.<uid>` filter can't evaluate and
-- deletions never sync across tabs/devices. FULL puts the whole old row in the
-- WAL so RLS + the client filter can match `user_id` on DELETE.
alter table notifications replica identity full;
do $$
begin
  begin execute 'alter publication supabase_realtime add table notifications'; exception when others then null; end;
end $$;

-- =====================================================================
-- INVITATIONS (unified)
-- =====================================================================

create table if not exists invitations (
  id                  uuid primary key default gen_random_uuid(),
  law_firm_id         uuid not null references law_firms(id) on delete cascade,
  email               citext not null,
  invite_type         text not null check (invite_type in ('member','client')),
  role_id             uuid,
  token               text not null unique,
  status              text not null default 'pending' check (status in ('pending','accepted','revoked','expired')),
  matter_ids            uuid[],
  invited_by          text references users(id) on delete restrict,
  invited_at          timestamptz,
  invitation_sent_at  timestamptz,
  invitation_email    citext,
  invitation_failed   boolean not null default false,
  invitation_resend_count integer not null default 0,
  -- NOT NULL with a default (migration 0223). A null here meant an invitation
  -- that never expired, which was never a considered choice: it is what a writer
  -- that did not think about expiry produced.
  expires_at          timestamptz not null default now() + interval '7 days',
  accepted_at         timestamptz,
  accepted_by         text references users(id) on delete restrict,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  -- Targeted invitations (organization-clients plan). Single-column FKs,
  -- matching the court_id/practice_area_id pattern: a composite tenant FK to
  -- clients(law_firm_id, id) can't ON DELETE SET NULL without nulling
  -- law_firm_id too, which would force ON DELETE CASCADE and silently drop
  -- invitation audit history whenever a client is deleted. Firm/client/link
  -- agreement is checked in the service layer.
  client_id           uuid references clients(id) on delete set null,
  contact_client_id   uuid references contact_clients(id) on delete set null,
  -- Single column, for the same reason as the client keys above and as
  -- members.role_id: a composite ON DELETE SET NULL would null law_firm_id too
  -- (migration 0186).
  constraint invitations_role_fk foreign key (role_id) references roles(id) on delete set null,
  -- Member invites carry no client identity.
  constraint invitations_member_no_client_check check (invite_type = 'client' or (client_id is null and contact_client_id is null)),
  -- A roster-link target implies its owning client is also set.
  constraint invitations_roster_requires_client_check check (contact_client_id is null or client_id is not null)
);
create index if not exists invitations_email_type_pending_idx on invitations (email, invite_type) where status = 'pending';
create index if not exists invitations_client_idx on invitations (law_firm_id, client_id) where client_id is not null;
create index if not exists invitations_contact_client_idx on invitations (law_firm_id, contact_client_id) where contact_client_id is not null;
-- Serves the on-delete walk of invitations_client_id_fkey (migration 0225).
create index if not exists invitations_client_id_idx on invitations (client_id);

-- One live pending invite per (firm, email), scoped to member invites.
create unique index if not exists invitations_member_pending_idx
  on invitations (law_firm_id, email)
  where invite_type = 'member' and status = 'pending';
-- One live pending invite per (firm, client) for person-client invites.
-- Legacy rows (and any invite issued before client_id is resolved) carry
-- client_id = null, which this partial unique index does not deduplicate
-- (Postgres never treats two NULLs as equal) - the application's pre-create
-- existence check is the operative safeguard for those.
create unique index if not exists invitations_person_client_pending_idx
  on invitations (law_firm_id, client_id)
  where invite_type = 'client' and contact_client_id is null and status = 'pending';
-- One live pending invite per (firm, roster link) for company roster
-- invites, so the same email can hold independent pending invites for two
-- different companies at once.
create unique index if not exists invitations_company_roster_pending_idx
  on invitations (law_firm_id, contact_client_id)
  where invite_type = 'client' and contact_client_id is not null and status = 'pending';

-- =====================================================================
-- COMPLIANCE: audit log, conflict-check records, legal holds
-- =====================================================================

-- Append-only security/data-access audit log. UPDATE is blocked by a trigger;
-- DELETE is allowed so the on-delete cascade from law_firms can purge a deleted
-- firm's rows. law_firm_id is nullable (some actions have no firm context).
create table if not exists audit_events (
  id            uuid primary key default gen_random_uuid(),
  law_firm_id   uuid references law_firms(id) on delete cascade,
  actor_uid     text,
  actor_email   text,
  action        text not null,
  resource_type text,
  resource_id   text,
  method        text,
  path          text,
  status_code   integer,
  ip            text,
  user_agent    text,
  metadata      jsonb not null default '{}'::jsonb,
  created_at    timestamptz not null default now()
);
create index if not exists audit_events_firm_time_idx on audit_events (law_firm_id, created_at desc);
create index if not exists audit_events_actor_idx on audit_events (actor_uid, created_at desc);

create or replace function audit_events_immutable() returns trigger as $$
begin
  raise exception 'audit_events are append-only: rows cannot be updated (id=%)', old.id;
end;
$$ language plpgsql;

drop trigger if exists audit_events_immutable on audit_events;
create trigger audit_events_immutable before update on audit_events
  for each row execute function audit_events_immutable();

-- Persisted conflict-of-interest checks performed at intake, so the firm can show
-- a check was run, by whom, against what, and what it returned.
create table if not exists conflict_check_records (
  id                 uuid primary key default gen_random_uuid(),
  law_firm_id        uuid not null references law_firms(id) on delete cascade,
  performed_by       text references users(id) on delete restrict,
  matter_id          uuid,
  query_name         text,
  query_email        text,
  query_organization text,
  result_count       integer not null default 0,
  results            jsonb not null default '[]'::jsonb,
  created_at         timestamptz not null default now()
);
create index if not exists conflict_check_firm_time_idx on conflict_check_records (law_firm_id, created_at desc);

-- activities.source_event_id is declared above, but `events` is created after
-- activities, so its FK has to be attached here. ON DELETE SET NULL: deleting
-- the event must not delete the billable time recorded against it.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'activities_source_event_fk') then
    alter table activities
      add constraint activities_source_event_fk
      foreign key (source_event_id) references events (id) on delete set null;
  end if;
end $$;

-- A legal hold is a ROW in `legal_holds`, not four columns copied onto three
-- tables (migration 0221). A `before delete` trigger on `matters` and `clients`
-- refuses while an unreleased hold exists, so a delete path that forgets to
-- check cannot quietly destroy preserved evidence.
--
-- The `files` arm exists and has no rows: nothing in the application ever set
-- `files.legal_hold`, so a hold placed there could never be lifted, and the
-- matter's hold governs its documents instead. The arm is there so the retention
-- work can use it deliberately.
create table if not exists legal_holds (
  id            uuid primary key default gen_random_uuid(),
  law_firm_id   uuid not null references law_firms(id) on delete cascade,
  matter_id     uuid,
  client_id     uuid,
  file_id       uuid,
  reason        text,
  placed_by     text references users(id) on delete restrict,
  placed_at     timestamptz not null default now(),
  -- A released hold is KEPT: which evidence was held, by whom and for how long
  -- is itself the record a hold exists to produce.
  released_by   text references users(id) on delete restrict,
  released_at   timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (law_firm_id, id),
  constraint legal_holds_one_subject check (num_nonnulls(matter_id, client_id, file_id) = 1),
  foreign key (law_firm_id, matter_id) references matters (law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, file_id)   references files   (law_firm_id, id) on delete cascade
);
-- One partial index per arm, restricted to LIVE holds: the only question the
-- trigger asks.
create index if not exists legal_holds_matter_idx
  on legal_holds (law_firm_id, matter_id) where matter_id is not null and released_at is null;
create index if not exists legal_holds_client_idx
  on legal_holds (law_firm_id, client_id) where client_id is not null and released_at is null;
create index if not exists legal_holds_file_idx
  on legal_holds (law_firm_id, file_id) where file_id is not null and released_at is null;

create or replace function legal_hold_blocks_delete() returns trigger
  language plpgsql as $$
declare
  held boolean;
begin
  select exists (
    select 1 from legal_holds h
     where h.released_at is null
       and h.law_firm_id = old.law_firm_id
       and ((tg_argv[0] = 'matter' and h.matter_id = old.id)
         or (tg_argv[0] = 'client' and h.client_id = old.id))
  ) into held;
  if held then
    raise exception 'record is under legal hold and cannot be deleted'
      using errcode = 'restrict_violation';
  end if;
  return old;
end;
$$;

drop trigger if exists matters_legal_hold_delete_guard on matters;
create trigger matters_legal_hold_delete_guard before delete on matters
  for each row execute function legal_hold_blocks_delete('matter');

drop trigger if exists clients_legal_hold_delete_guard on clients;
create trigger clients_legal_hold_delete_guard before delete on clients
  for each row execute function legal_hold_blocks_delete('client');

-- =====================================================================
-- REMINDERS (unified reminder table from migration 0238)
-- =====================================================================

create table if not exists task_reminder_deliveries (
  id uuid primary key default gen_random_uuid(),
  law_firm_id uuid not null references law_firms(id) on delete cascade,
  task_id uuid not null,
  recipient_key text not null,
  last_sent_at timestamptz,
  sent_count int not null default 0 check (sent_count >= 0),
  claim_token uuid,
  claim_expires_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (law_firm_id, id),
  unique (law_firm_id, task_id, recipient_key),
  foreign key (law_firm_id, task_id) references tasks(law_firm_id, id) on delete cascade,
  check ((claim_token is null) = (claim_expires_at is null))
);

create table if not exists reminders (
  id                        uuid primary key default gen_random_uuid(),
  law_firm_id               uuid not null references law_firms(id) on delete cascade,
  invoice_id                uuid,
  task_id                   uuid,
  event_id                  uuid,
  signature_participant_id  text,
  last_sent_at              timestamptz,
  sent_count                int not null default 0 check (sent_count >= 0),
  is_opted_out              boolean not null default false,
  pre_due_days              int check (pre_due_days is null or pre_due_days >= 0),
  pre_due_sent_at           timestamptz,
  recent_manual_sends       timestamptz[] not null default '{}',
  next_run_at               timestamptz,
  created_at                timestamptz not null default now(),
  updated_at                timestamptz not null default now(),
  unique (law_firm_id, id),
  constraint reminders_parent_ck check (
    num_nonnulls(invoice_id, task_id, event_id, signature_participant_id) = 1
  ),
  foreign key (law_firm_id, invoice_id) references invoices(law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, task_id) references tasks(law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, event_id) references events(law_firm_id, id) on delete cascade,
  foreign key (law_firm_id, signature_participant_id) references signature_participants(law_firm_id, id) on delete cascade
);


create unique index if not exists reminders_invoice_uq on reminders (law_firm_id, invoice_id) where invoice_id is not null;
create unique index if not exists reminders_task_uq on reminders (law_firm_id, task_id) where task_id is not null;
create unique index if not exists reminders_event_uq on reminders (law_firm_id, event_id) where event_id is not null;
create unique index if not exists reminders_participant_uq on reminders (law_firm_id, signature_participant_id) where signature_participant_id is not null;
-- Each read joins on one arm, so each arm needs an index leading with it. The
-- uniques above lead with law_firm_id and cannot serve that.
create index if not exists reminders_invoice_idx on reminders (invoice_id) where invoice_id is not null;
create index if not exists reminders_task_idx on reminders (task_id) where task_id is not null;
create index if not exists reminders_event_idx on reminders (event_id) where event_id is not null;
create index if not exists reminders_participant_idx on reminders (signature_participant_id) where signature_participant_id is not null;
create index if not exists reminders_next_run_idx on reminders (law_firm_id, next_run_at) where next_run_at is not null;


-- =====================================================================
-- EVENT OUTBOX (durability backstop for the in-process event bus)
-- =====================================================================
-- The live primary dispatch path stays the synchronous EventEmitter in
-- `eventBus.js`; this table is a SECONDARY safety net so a crash/transient
-- error between a DB commit and an async listener does not silently drop a
-- notification. A worker (gated by EVENT_OUTBOX_WORKER) claims rows
-- with FOR UPDATE SKIP LOCKED and re-dispatches them through the same bus with
-- at-least-once retry. Additive only: nothing touches this table unless the
-- worker is enabled.
-- Resume point for the per-firm passes of the daily reminder cron. Each pass
-- walks every firm inside one scheduler request; this records the last firm each
-- pass finished so the next run starts after it and wraps around. Without it a
-- pass cut short by the request timeout would restart from the same end of an
-- arbitrary ordering every day, and the firms past the cut-off would never be
-- reached. No FK on `last_firm_id`: a deleted firm should just fail to match and
-- restart the rotation, not delete the resume point.
create table if not exists cron_pass_state (
  pass_name    text primary key,
  last_firm_id uuid,
  updated_at   timestamptz not null default now()
);

-- Lease rows behind `withLock` / `tryLock` (`shared/database/advisoryLock.ts`,
-- migration 0013). Acquiring is one upsert that takes the row only when it is
-- absent or `locked_until` has passed; releasing deletes it only when
-- `owner_token` still matches, so an owner whose lease expired never deletes
-- the next owner's. No pool connection is held while the locked work runs.
-- Not tenant-owned: a key names a platform-wide thing (a cron pass, a payment
-- intent, a user's calendar).
create table if not exists lock_leases (
  domain       text        not null,
  lock_key     text        not null,
  owner_token  uuid        not null,
  locked_until timestamptz not null,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  primary key (domain, lock_key)
);

-- Send-once-per-local-day record for the daily digest.
--
-- The digest cron runs hourly (it has to: recipients pick a delivery hour in
-- their own timezone, so a single daily fire cannot serve every zone). The
-- primary key is the idempotency mechanism: a claim is an
-- `insert ... on conflict do nothing returning *`, and only the run that gets a
-- row back sends. That makes a double-fire, a manual re-trigger, and a retry
-- after a partial failure all safe without any advisory lock.
--
-- `sent_on` is the recipient's LOCAL date, not a UTC date - two recipients in
-- different zones legitimately roll over to a new digest day at different UTC
-- instants.
create table if not exists digest_sends (
  law_firm_id uuid    not null references law_firms(id) on delete cascade,
  user_id     text    not null references users(id) on delete cascade,
  sent_on     date    not null,
  item_count  integer not null default 0,
  created_at  timestamptz not null default now(),
  primary key (law_firm_id, user_id, sent_on)
);

create index if not exists digest_sends_sent_on_idx on digest_sends (sent_on);
-- Serves the on-delete walk of digest_sends_user_id_fkey (migration 0224).
create index if not exists digest_sends_user_id_idx on digest_sends (user_id);

create table if not exists event_outbox (
  id            uuid primary key default gen_random_uuid(),
  law_firm_id   uuid,
  event_type    text not null,
  payload       jsonb not null,
  status        text not null default 'pending'
                  check (status in ('pending','processing','done','failed')),
  attempts      int not null default 0,
  last_error    text,
  created_at    timestamptz not null default now(),
  processed_at  timestamptz
);

create index if not exists event_outbox_status_created_idx
  on event_outbox (status, created_at);
-- Supports the worker's retention sweep (delete 'done' rows by processed_at) and
-- dead-letter inspection by status (migration 0057). law_firm_id has no FK by
-- design -- it's a denormalized, nullable copy from the payload.
create index if not exists event_outbox_status_processed_idx
  on event_outbox (status, processed_at);
create index if not exists event_outbox_law_firm_idx
  on event_outbox (law_firm_id);

-- Column comments. These were written by earlier migrations and never carried
-- into the domain files, so a database built from schema.sql lacked them while
-- a migrated one had them. They are the reference for what each column means.
comment on column invitations.client_id is 'The clients.id this invitation was issued for. Set for both person-client invites and company roster invites (see contact_client_id); null for member invites and for legacy client invites issued before this column existed.';
comment on column invitations.contact_client_id is 'The contact_clients.id (roster link) a company invite targets. Null for person-client invites (client_id alone identifies the target) and for member invites.';

-- >>> 95_deferred_fks.sql <<<
-- =====================================================================
-- DEFERRED CROSS-TABLE FOREIGN KEYS
--   Two reasons a foreign key lives here rather than on its table:
--   a genuine circular dependency (invoices <-> billing_plan_periods), or a
--   plain forward reference to a table created later in this file. Either way
--   an inline declaration makes the whole file unappliable to an EMPTY
--   database, which is the one case this file exists to serve.
--
--   Every entry is guarded on pg_constraint, so re-applying is a no-op and an
--   existing database keeps the constraint it already has.
-- =====================================================================
do $$
begin
  -- note_links is defined after `tasks` now, but the deferred form is kept: the
  -- table is created in the notes block, which sits with the other note tables
  -- rather than being ordered around this one key.
  if not exists (select 1 from pg_constraint where conname = 'note_links_law_firm_id_task_id_fkey') then
    alter table note_links add constraint note_links_law_firm_id_task_id_fkey
      foreign key (law_firm_id, task_id) references tasks (law_firm_id, id) on delete cascade;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'invoices_plan_fk') then
    alter table invoices      add constraint invoices_plan_fk         foreign key (billing_plan_id) references billing_plans(id) on delete set null;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'invoices_plan_period_fk') then
    alter table invoices      add constraint invoices_plan_period_fk  foreign key (billing_plan_period_id) references billing_plan_periods(id) on delete set null;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'period_generated_invoice_fk') then
    alter table billing_plan_periods add constraint period_generated_invoice_fk foreign key (generated_invoice_id) references invoices(id) on delete set null;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'trust_txn_invoice_fk') then
    -- Tenant-scoped, matching the declaration on the table above. The
    -- single-column form this block used to add let a trust entry point at an
    -- invoice belonging to another firm; migration 0181 replaces it where it
    -- was already created that way.
    alter table trust_transactions add constraint trust_txn_invoice_fk foreign key (law_firm_id, invoice_id) references invoices(law_firm_id, id) on delete set null;
  end if;
end $$;

